local config = {
  ui_story_5004_50040101_1_dialog_content = "PlayerName！",
  ui_story_5004_50040101_2_dialog_content = "PlayerName、下がって！！",
  ui_story_5004_50040101_3_dialog_content = "（打ち寄せる大きな波に飲まれそうだ）",
  ui_story_5004_50040101_4_dialog_content = "（黒い雲の中を走る赤紫色の雷が、耳をつんざく轟音と共に地面を打ち付ける）",
  ui_story_5004_50040101_5_dialog_content = "（隕石が空を破り、僕たちに向かって落ちてくるのが見える）",
  ui_story_5004_50040101_6_dialog_content = "（彼方には不吉な黒い城が、ゆっくりと海底から姿を現しつつある。\nまるで僕の心の中の絶望を映し出すかのように…）",
  ui_story_5004_50040101_7_dialog_content = "（そして、バイスとカレンは僕の前に立ち、\n終わりの見えない戦いから僕を守ろうとしていた…）",
  ui_story_5004_50040101_8_dialog_content = "（でもすでに、何もかもが手遅れだった）",
  ui_story_5004_50040101_9_dialog_content = "（僕が災いを呼び寄せ、すべてが破壊されることになるなんて…\nつゆほどにも思っていなかった）",
  ui_story_5004_50040101_10_dialog_content = "それじゃ、彼女のことはあなたに任せたよ。僕は先に失礼する。",
  ui_story_5004_50040101_11_dialog_content = "ま、待って。突然女の子を連れてきて「任せる」だなんて、\n僕のこと何だと思ってるの…？",
  ui_story_5004_50040101_12_dialog_content = "名前だって知らないんだよ？",
  ui_story_5004_50040101_13_dialog_content = "…",
  ui_story_5004_50040101_14_dialog_content = "えっと……",
  ui_story_5004_50040101_15_dialog_content = "私は…",
  ui_story_5004_50040101_16_dialog_content = "彼女は<color=#FFB400>ベリエ</color>。これでもうお知り合いだね。\nそれじゃ、僕はここで。",
  ui_story_5004_50040101_17_dialog_content = "待って！ちゃんと説明してよ。",
  ui_story_5004_50040101_18_dialog_content = "仕方ないね。そこまで真理にこだわるというのなら、いいだろう…",
  ui_story_5004_50040101_19_dialog_content = "いやいや…真理の話はしなくていいよ。君はさっき…",
  ui_story_5004_50040101_20_dialog_content = "…",
  ui_story_5004_50040101_21_dialog_content = "その…「ベリエ」は<color=#FFB400>病気にかかっている</color>って言ったよね？",
  ui_story_5004_50040101_22_dialog_content = "さあね。",
  ui_story_5004_50040101_23_dialog_content = "えっ？？",
  ui_story_5004_50040101_24_dialog_content = "僕には何も分からないから、あなたに任せることにしたんだ。",
  ui_story_5004_50040101_25_dialog_content = "空の末裔には、特殊な感知能力がある。\nそれに治癒効果のある光力術に長けた光霊の友人も、大勢いるだろう。",
  ui_story_5004_50040101_26_dialog_content = "ビクトリア様も、彼女の世話役にはあなたが最適だと。",
  ui_story_5004_50040101_27_dialog_content = "真理結社って慈善団体か何かだったの…？",
  ui_story_5004_50040101_28_dialog_content = "…",
  ui_story_5004_50040101_29_dialog_content = "ファウスト、2人だけで話ができるかな。",
  ui_story_5004_50040101_30_dialog_content = "あのさ…",
  ui_story_5004_50040101_31_dialog_content = "もしかしてだけど、あの子…",
  ui_story_5004_50040101_32_option_content = "「ビクトリア様」の娘じゃないよね？",
  ui_story_5004_50040101_33_dialog_content = "いいや。ビクトリア様はただひたすらに真理への道を求めていらっしゃる。\n世俗の欲望などかけらもお持ちではない。",
  ui_story_5004_50040101_34_option_content = "君たちが妙な儀式で使う生贄じゃないよね？",
  ui_story_5004_50040101_35_dialog_content = "もちろん違うさ。真理を求めるということは、悪の道とは違う。",
  ui_story_5004_50040101_36_dialog_content = "ベリエは真理結社の幹部なんだ。",
  ui_story_5004_50040101_37_dialog_content = "あの…",
  ui_story_5004_50040101_38_dialog_content = "ふーん。とにかく、怪しい計画とかじゃなければそれでいいよ…",
  ui_story_5004_50040101_39_dialog_content = "だけど、どうして僕が選ばれたのか、まだ納得いかないなぁ。",
  ui_story_5004_50040101_40_dialog_content = "ビクトリア様のお考えをすべて理解する必要はない。",
  ui_story_5004_50040101_41_dialog_content = "あのお方の命令を抜かりなく遂行してさえいれば、\n真理に近づくことができるんだ。",
  ui_story_5004_50040101_42_dialog_content = "（うまいこと丸め込もうって魂胆かな。余計に怪しい…）",
  ui_story_5004_50040101_43_dialog_content = "分かったよ。ちょうどラファエルが巨像にいるから、\n会って病気をみてもらおう。",
  ui_story_5004_50040101_44_dialog_content = "<color=#e8d9bb>数分後</color>",
  ui_story_5004_50040101_45_dialog_content = "う～ん…",
  ui_story_5004_50040101_46_dialog_content = "むむ…むむぅ…",
  ui_story_5004_50040101_47_dialog_content = "天使さん、どうだろう？",
  ui_story_5004_50040101_48_dialog_content = "今できる限りの検査方法じゃぁ、彼女の体に何も異常は見つからなかったよ…！",
  ui_story_5004_50040101_49_dialog_content = "お名前はベリエ、で良かったっけ？",
  ui_story_5004_50040101_50_dialog_content = "ええ…",
  ui_story_5004_50040101_51_dialog_content = "じゃあベリエちゃん、どこか具合が悪い所はある？",
  ui_story_5004_50040101_52_dialog_content = "ベリエちゃん…？",
  ui_story_5004_50040101_53_dialog_content = "ごめんなさい。私、自分の体のことはよく分からなくて…",
  ui_story_5004_50040101_54_dialog_content = "でも、最近すごく疲れやすくて、光力もうまくコントロールできないの…",
  ui_story_5004_50040101_55_dialog_content = "たまに全身に激しい痛みを感じることもあるの…体中が何かに蝕まれるような感覚よ…",
  ui_story_5004_50040101_56_dialog_content = "そうなんだ…",
  ui_story_5004_50040101_57_dialog_content = "ベリエちゃんみたいな症状の患者さんは、ラファエルも初めてだよ。",
  ui_story_5004_50040101_58_dialog_content = "PlayerNameはどう思う？",
  ui_story_5004_50040101_59_dialog_content = "（ベリエはずっと険しい顔つきをしてる。何か心配事でもあるのかな）",
  ui_story_5004_50040101_60_option_content = "何かつらいことがあったんじゃない？",
  ui_story_5004_50040101_61_dialog_content = "その可能性もあるね！",
  ui_story_5004_50040101_62_dialog_content = "カレンちゃんも、城主様とケンカするたびにこういう顔してるもん。",
  ui_story_5004_50040101_63_dialog_content = "今のベリエちゃんにそっくりだよ。",
  ui_story_5004_50040101_64_option_content = "僕の感知能力で探ってみようか？",
  ui_story_5004_50040101_65_dialog_content = "ダメだよ！デリカシーがないんだから！",
  ui_story_5004_50040101_66_dialog_content = "手術で切開してから患部を探そうとするのと同じだよ！\nそんな荒っぽいやり方はダメ！",
  ui_story_5004_50040101_67_dialog_content = "とにかく！",
  ui_story_5004_50040101_68_dialog_content = "体と心、どっちが原因にしても、ラファエルにど～んと任せて！",
  ui_story_5004_50040101_69_dialog_content = "ベリエちゃん、心配しないでね。\n主治医として、付きっきりで見てあげるから！",
  ui_story_5004_50040101_70_dialog_content = "病気の原因をつきとめて、「ひといきで」心も回復させちゃうから！",
  ui_story_5004_50040101_71_dialog_content = "いっそ「ひと思いに」ってことにならないといいけど…",
  ui_story_5004_50040101_72_dialog_content = "PlayerName～！",
  ui_story_5004_50040101_X72_dialog_content = "病気の人の前でそんな冗談はダメ！",
  ui_story_5004_50040101_73_dialog_content = "でも、ありがとう…",
  ui_story_5004_50040101_74_dialog_content = "こんなところで集まって何してるの？",
  ui_story_5004_50040101_75_dialog_content = "PlayerName、ごきげんよう。ラファエルもいたのね。",
  ui_story_5004_50040101_76_dialog_content = "あっ、カレンちゃん～！何しに来たの？",
  ui_story_5004_50040101_77_dialog_content = "白夜城を代表して情報の交換に来たの。ついでにバイスと雑談していたわ。",
  ui_story_5004_50040101_78_dialog_content = "こちらのお2人は…",
  ui_story_5004_50040101_79_dialog_content = "彼はファウスト。",
  ui_story_5004_50040101_80_dialog_content = "ごきげんよう、高貴な麗人方。",
  ui_story_5004_50040101_81_dialog_content = "あなた、<color=#FFB400>真理結社</color>の人間ね？",
  ui_story_5004_50040101_82_dialog_content = "真理結社をご存じとは。",
  ui_story_5004_50040101_83_dialog_content = "もしや、あなたも真理の追求者かな？",
  ui_story_5004_50040101_84_dialog_content = "「真理」とやらに興味はないわ。私には私の信仰があるもの。",
  ui_story_5004_50040101_85_dialog_content = "それは残念だ。",
  ui_story_5004_50040101_86_dialog_content = "しかし真理の価値について考えているということは、\nすでに真理の道へと一歩踏み出しているということでもある。喜ばしいことだ。",
  ui_story_5004_50040101_87_dialog_content = "いずれ、真理の最果てでめぐり会うこともあるかもしれない。",
  ui_story_5004_50040101_88_dialog_content = "口が達者ね…PlayerName、こちらの女性は？",
  ui_story_5004_50040101_89_dialog_content = "彼女はベリエ。ファウストが面倒を見てくれって連れて来たんだ…\nファウストの…友達って言うのかな？",
  ui_story_5004_50040101_90_dialog_content = "カレンちゃん～！ベリエちゃんは今日から私の患者さんだよ。",
  ui_story_5004_50040101_91_dialog_content = "そうだったの…よかったわね、ラファエル。",
  ui_story_5004_50040101_92_dialog_content = "白夜の名を汚さぬよう、全力で治療に当たりなさい。",
  ui_story_5004_50040101_93_dialog_content = "ふふふ～、当然だよ！",
  ui_story_5004_50040101_94_dialog_content = "でもね、ベリエちゃんの不調の原因が何なのか、まだ分かってないんだ…",
  ui_story_5004_50040101_X94_dialog_content = "精神的な要因があるんじゃないかって推測してるとこ…\n過剰なストレスが原因かも…",
  ui_story_5004_50040101_95_dialog_content = "ラファエルって、精神的な病気も診られるの？\nミサイルで戦うだけの天使じゃなかったのね！",
  ui_story_5004_50040101_96_dialog_content = "えへへ。白夜城の天使を甘く見ちゃダメだよん、バイスちゃん～",
  ui_story_5004_50040101_97_dialog_content = "（ラファエルとバイスはかなり仲良くなってるみたいだ…よかった）",
  ui_story_5004_50040101_98_dialog_content = "PlayerName？どうしたの？ニヤニヤして。いいもの持って来たわよ。",
  ui_story_5004_50040101_99_dialog_content = "何かの役に立つかもね。",
  ui_story_5004_50040101_100_dialog_content = "はい、手紙。",
  ui_story_5004_50040101_101_dialog_content = "手紙？",
  ui_story_5004_50040101_102_dialog_content = "さっきカラスが持ってきたのよ。\n<color=#FFB400>ホテル「フルート・プラチナ」</color>ってマークがあるわ。",
  ui_story_5004_50040101_103_dialog_content = "でも送り主の名前がないのよ。変よね。",
  ui_story_5004_50040101_104_dialog_content = "開けてみる？",
  ui_story_5004_50040101_105_option_content = "怪しい…今は開けないでおこう",
  ui_story_5004_50040101_106_dialog_content = "そんなに怖がってどうするの？ただの手紙よ。",
  ui_story_5004_50040101_107_dialog_content = "代わりに私が開けてあげる。えい！",
  ui_story_5004_50040101_108_dialog_content = "待って、爆発物が入ってたりは…！",
  ui_story_5004_50040101_109_dialog_content = "紙しか入ってないわよ。ごく普通の便せんみたいね。\nツヤ消しされた模様がついてるわ。",
  ui_story_5004_50040101_110_dialog_content = "何事もなくてよかった…",
  ui_story_5004_50040101_111_option_content = "何てことないよ、開けちゃおう",
  ui_story_5004_50040101_112_dialog_content = "早く早く。何が入ってるのか私も知りたいわ。",
  ui_story_5004_50040101_113_dialog_content = "ん？紙が入ってるみたいだ。",
  ui_story_5004_50040101_114_dialog_content = "紙だけ？",
  ui_story_5004_50040101_115_dialog_content = "PlayerName、何が書いてあるの？",
  ui_story_5004_50040101_116_dialog_content = "えっと…",
  ui_story_5004_50040101_117_dialog_content = "親愛なるPlayerName様",
  ui_story_5004_50040101_118_dialog_content = "この度、当ホテル「フルート・プラチナ」は、貴方を夏のバカンスにご招待させていただきます。",
  ui_story_5004_50040101_X118_dialog_content = "私どもが真心を込めてご用意する<color=#FFB400>潮汐祭</color>へ、是非ともご参加ください。",
  ui_story_5004_50040101_119_dialog_content = "招待状も入ってる。御友人様6名まで同行可能、だって。",
  ui_story_5004_50040101_120_dialog_content = "高級ホテルの部屋やレジャー施設をタダで楽しめるってこと…！？",
  ui_story_5004_50040101_121_dialog_content = "最高じゃない！私、海に行ってみたいって思ってたの！",
  ui_story_5004_50040101_122_dialog_content = "お祭りでしょ…？ベリエにとってもいい刺激になりそうな気がするわ！",
  ui_story_5004_50040101_123_dialog_content = "心の病にかかってるなら、\n思いっきり遊んでリフレッシュすれば治るかも！",
  ui_story_5004_50040101_124_dialog_content = "PlayerName、ベリエちゃんを連れて海へ行こうよ～！\nいいでしょ？ねえ、いいでしょ～？",
  ui_story_5004_50040101_125_dialog_content = "ちょっと待って。まだ状況が把握し切れていないよ。\nホテルの名前も今まで聞いたことがないし…",
  ui_story_5004_50040101_126_dialog_content = "心配いらないわよ。そのホテルなら超有名よ。",
  ui_story_5004_50040101_127_dialog_content = "確かにそうね。フルート・プラチナといえば、ここ数年、白夜城の貴族の間で\nちょっとした話題になっているわ。私の耳にも入るぐらいには。",
  ui_story_5004_50040101_128_dialog_content = "ホテルのオーナーが経営上手だと聞いているわ。",
  ui_story_5004_50040101_129_dialog_content = "この招待状や「潮汐祭」というのも、\nその人が考えた集客の手法なのかもしれないわね。",
  ui_story_5004_50040101_130_dialog_content = "でも、どうして僕なんかを招待したんだろう？",
  ui_story_5004_50040101_131_dialog_content = "それも経営戦略のうちではないかしら。",
  ui_story_5004_50040101_132_dialog_content = "「空の末裔」に興味を持っている光霊は多いもの。",
  ui_story_5004_50040101_133_dialog_content = "空の末裔が来たことのあるホテル、泊まった部屋、食事をしたテーブル…\nどれも観光スポットとしてホテルの宣伝になるのかもしれないわ。",
  ui_story_5004_50040101_134_dialog_content = "そう言われると、まるで僕が珍しい生き物か何かみたいだね…",
  ui_story_5004_50040101_135_dialog_content = "…",
  ui_story_5004_50040101_136_dialog_content = "…",
  ui_story_5004_50040101_137_dialog_content = "えっ、なんで急に静かになるの？",
  ui_story_5004_50040101_138_dialog_content = "とにかく、白夜城の貴族が御用達のリゾートでバカンス…\nホテルにとっても、私たちにとってもメリットがあるってことね。",
  ui_story_5004_50040101_139_dialog_content = "それなら危ないこともなさそうね。",
  ui_story_5004_50040101_140_dialog_content = "意見がまとまったようだね。",
  ui_story_5004_50040101_141_dialog_content = "ファウスト？まだいたの？",
  ui_story_5004_50040101_142_dialog_content = "それじゃあ、ベリエのことは任せたよ。バカンスを満喫してくれたまえ。では。",
  ui_story_5004_50040101_143_dialog_content = "…ファウストって、いつもあっという間にいなくなるわね。",
  ui_story_5004_50040101_144_dialog_content = "やったね、ベリエちゃん！お医者さんとして、私がしっかり面倒見るからね！",
  ui_story_5004_50040101_145_dialog_content = "この話…なんだか裏がありそうな気がするなあ。",
  ui_story_5004_50040101_146_dialog_content = "ほら早く。向こうに海が見えるわ。",
  ui_story_5004_50040101_147_dialog_content = "私、海を見るのはこれが初めてなのよ。",
  ui_story_5004_50040101_148_dialog_content = "えっ？バイスも？",
  ui_story_5004_50040101_149_dialog_content = "僕だけかと思ってた…",
  ui_story_5004_50040101_150_dialog_content = "あなただけじゃないわ。巨像がなければ、こんな遠出はそうそうできないもの。",
  ui_story_5004_50040101_151_dialog_content = "海風が心地いい…見渡す限り美しい青ね。気持ちも軽くなるわ。",
  ui_story_5004_50040101_152_dialog_content = "ベリエの病気にも、きっと効果があるはずよ！",
  ui_story_5004_50040101_153_dialog_content = "ねぇ…ベリエのためって言うけど、\n本当は自分が海へ遊びに行きたかっただけだよね。",
  ui_story_5004_50040101_154_dialog_content = "確かにそれもあるわ。",
  ui_story_5004_50040101_155_dialog_content = "ほとんどの光霊にとって、海に行ける機会なんてめったにないの。",
  ui_story_5004_50040101_156_dialog_content = "ずっと巨像の中で暮らしてきたあなたには、よく分からないかも知れないけど。",
  ui_story_5004_50040101_157_dialog_content = "海でバカンスなんて、今の光霊にとっては勇敢な人向けの<color=#FFB400>大冒険</color>も同然なのよ。",
  ui_story_5004_50040101_158_dialog_content = "どういうこと…？",
  ui_story_5004_50040101_159_dialog_content = "考えてもみて。海岸だってどこもかしこも暗鬼がうようよしてるの。",
  ui_story_5004_50040101_160_dialog_content = "太陽や海を楽しむのと同時に、いつでも暗鬼の急襲に対応できるよう\n準備もしておかないといけないのよ。",
  ui_story_5004_50040101_161_dialog_content = "のんびりした風景に見えても、常に危険がつきまとってるってこと。\nスリルいっぱいでしょ？",
  ui_story_5004_50040101_162_dialog_content = "スリルって言うのかな？単に危ないだけの気がするけど…",
  ui_story_5004_50040101_163_dialog_content = "たとえば、僕が砂に埋められている時に暗鬼が現れたらどうするの？",
  ui_story_5004_50040101_164_dialog_content = "僕を置いて逃げたりしないよね？",
  ui_story_5004_50040101_165_dialog_content = "私たちは仲間でしょ、そんなことしないわよ！",
  ui_story_5004_50040101_166_dialog_content = "いずれにしても、夏の爽やかな海は心の傷にとって一番いい薬だと思うわ。",
  ui_story_5004_50040101_167_dialog_content = "ここなら、ベリエも心身ともにリラックスできるはずよ。",
  ui_story_5004_50040101_168_dialog_content = "海ってことは泳ぐ？…でも僕たち、<color=#FFB400>水着</color>なんて持ってないよね。",
  ui_story_5004_50040101_169_dialog_content = "それなら心配ないわ。",
  ui_story_5004_50040101_170_dialog_content = "ホテルで有名ブランドの水着が販売されているはず。",
  ui_story_5004_50040101_171_dialog_content = "白夜城の貴族たちが相手だもの、その辺りはぬかりないわ。",
  ui_story_5004_50040101_172_dialog_content = "水着まで売ってるんだ。さすがのサービス精神だね。",
  ui_story_5004_50040101_173_dialog_content = "当然のことよ。ビーチの水着は戦場の鎧と同じ。",
  ui_story_5004_50040101_174_dialog_content = "啓光の兵士にせよ、白夜城の貴族にせよ、\nビーチでは水着を着ていなければならないの。",
  ui_story_5004_50040101_175_dialog_content = "それが「ビーチの作法」！",
  ui_story_5004_50040101_176_dialog_content = "そ、そうなんだ…？",
  ui_story_5004_50040101_177_dialog_content = "（ソラヴァンから聞いた話と違う…水着ってそんなに大事な物なの…？）",
  ui_story_5004_50040101_178_dialog_content = "カレンって…ホテルや水着に詳しいみたいだね？",
  ui_story_5004_50040101_179_dialog_content = "別にどこもおかしくないわ。私は白夜城の護衛隊長だもの。",
  ui_story_5004_50040101_180_dialog_content = "貴族の間で何が流行っているのか把握しておくことも、務めの1つよ。",
  ui_story_5004_50040101_181_dialog_content = "とにかく、PlayerName。\n海と言う戦場に出る私の戦装束、楽しみにしておくことね。",
  ui_story_5004_50040101_182_dialog_content = "（カレンの水着姿…）",
  ui_story_5004_50040101_183_dialog_content = "う…うん。",
  ui_story_5004_50040101_184_dialog_content = "PlayerName、その目は何？",
  ui_story_5004_50040101_185_dialog_content = "何か変なものでもついていたかしら？",
  ui_story_5004_50040101_186_dialog_content = "べ、別に何も。そうだ！ホテルについて他に知っていることは？",
  ui_story_5004_50040101_187_dialog_content = "ホテルは昔、白夜城の貴族の所有物だったそうよ。",
  ui_story_5004_50040101_188_dialog_content = "ところが経営不振に陥って、影ノ街の謎の組織に売り渡された、と言う話よ。",
  ui_story_5004_50040101_189_dialog_content = "でも、影ノ街は一筋縄ではいかない。\n情報が錯綜していて、真偽が定かじゃないの。",
  ui_story_5004_50040101_190_dialog_content = "わざわざ正体を隠している組織のことなら、なおさらね。",
  ui_story_5004_50040101_191_dialog_content = "影ノ街の内部に通じた人間でなければ、詳しい事情は知る由もないわ。",
  ui_story_5004_50040101_192_dialog_content = "そうなんだ…影ノ街って、複雑な場所なんだね。",
  ui_story_5004_50040101_193_dialog_content = "そうよ。影ノ街が比較的安定して平和を保てているのもすべては…",
  ui_story_5004_50040101_194_dialog_content = "ちょっと待った～！さっきからマジメな話ばっかりだよ！",
  ui_story_5004_50040101_195_dialog_content = "一番の目的はベリエちゃんに気晴らししてもらって、\n一刻も早く元気になってもらうことなんだよ？",
  ui_story_5004_50040101_196_dialog_content = "私は平気よ…",
  ui_story_5004_50040101_197_dialog_content = "！！！",
  ui_story_5004_50040101_198_dialog_content = "PlayerName！？",
  ui_story_5004_50040101_199_dialog_content = "ソラヴァン！",
  ui_story_5004_50040101_200_dialog_content = "PlayerName、巡航システムが目的地からの強力な干渉を受けています。",
  ui_story_5004_50040101_201_dialog_content = "このまま進行すると、飛行中の制御が不可能になる恐れがあります。",
  ui_story_5004_50040101_202_dialog_content = "ううっ――！！",
  ui_story_5004_50040101_203_dialog_content = "ベリエちゃん？どうかした？",
  ui_story_5004_50040101_204_dialog_content = "どこか具合が悪いの？",
  ui_story_5004_50040101_205_dialog_content = "ソラヴァン！ひとまず目的地から離れて、すぐに着陸地点を決めよう！",
  ui_story_5004_50040101_206_dialog_content = "承知しました。",
  ui_story_5004_50040101_207_dialog_content = "ベリエ、大丈夫？",
  ui_story_5004_50040101_208_dialog_content = "…これは？",
  ui_story_5004_50040101_209_dialog_content = "ここはどこだ…？",
  ui_story_5004_50040101_210_dialog_content = "燃えるように暑い…それに焦げ臭い…大勢の光霊が泣き叫ぶ声がする…",
  ui_story_5004_50040101_211_dialog_content = "それなのに何も見えない…",
  ui_story_5004_50040101_212_dialog_content = "ここは一体…どこなんだ？",
  ui_story_5004_50040101_213_dialog_content = "PlayerName！",
  ui_story_5004_50040101_214_dialog_content = "PlayerName！！",
  ui_story_5004_50040101_215_dialog_content = "バイス…？",
  ui_story_5004_50040101_216_dialog_content = "PlayerName、大丈夫？",
  ui_story_5004_50040101_217_dialog_content = "何が起きたの…？",
  ui_story_5004_50040101_218_dialog_content = "ベリエに触れた途端、あなたが動かなくなったのよ。",
  ui_story_5004_50040101_219_dialog_content = "また何か感知したの？",
  ui_story_5004_50040101_220_dialog_content = "うん…ぼんやりとしてたけど、何かが見えたよ…それより、今の状況は？",
  ui_story_5004_50040101_221_dialog_content = "干渉圏内から離脱しました。着陸地点を探索しています。",
  ui_story_5004_50040101_222_dialog_content = "ベリエちゃん、ケガはない？",
  ui_story_5004_50040101_223_dialog_content = "ええ…",
  ui_story_5004_50040101_224_dialog_content = "さっきのは一体…",
  ui_story_5004_50040201_1_dialog_content = "ッたく…なんで私があんたらを乗せてかなきゃならないのさ。\n巨像が飛ばないのは私のせいじゃないだろ。",
  ui_story_5004_50040201_2_dialog_content = "ちょうど巨像の酒場で演奏しようと思ってたところだったのによ。",
  ui_story_5004_50040201_3_dialog_content = "その、ナントカってホテルにはホントに豪華な音響設備があるんだろうね？",
  ui_story_5004_50040201_4_dialog_content = "ウソだったら…灼熱の太陽がどれほど熱いか思い知らせてやるからな！",
  ui_story_5004_50040201_5_dialog_content = "ちょっと、車の天井を叩かないで！落ちちゃうよ！",
  ui_story_5004_50040201_6_dialog_content = "音響設備ならあるよ…たぶん！",
  ui_story_5004_50040201_7_dialog_content = "なかった時は…",
  ui_story_5004_50040201_8_dialog_content = "巨像の音響設備を君が欲しいって言ってた\n「ドッカン・ダイナマイト」ブランドに変えてあげるから…",
  ui_story_5004_50040201_9_dialog_content = "とにかく今は運転に集中して。ルーフの上には僕が乗ってるんだ！\n安全運転でお願いするよ！",
  ui_story_5004_50040201_10_dialog_content = "ごめんなさい…私のせいでPlayerNameが車の上に…",
  ui_story_5004_50040201_11_dialog_content = "いいんだ、気にしないで。",
  ui_story_5004_50040201_12_dialog_content = "こんな「特等席」、女の子に座らせるわけにはいかないよ。",
  ui_story_5004_50040201_13_dialog_content = "見かけによらず紳士なこって。",
  ui_story_5004_50040201_14_dialog_content = "ちゃんと前を見て運転して！ハンドルから手を放さないで！",
  ui_story_5004_50040201_15_dialog_content = "ビビんなって――運転なんてな、R・Wの連中なら生まれた時からお手の物さ。",
  ui_story_5004_50040201_16_dialog_content = "上級暗鬼がやってきたって、頭からひいてやればいいだけの話だ。",
  ui_story_5004_50040201_17_dialog_content = "それにしてもあんたら、ラッキーだったね。<color=#FFB400>ヘール</color>の<color=#FFB400>車</color>をちょうど修理してたんだ。\nでなきゃ今ごろ歩いて――",
  ui_story_5004_50040201_18_dialog_content = "前を見て！",
  ui_story_5004_50040201_19_dialog_content = "レジーナ！正面に暗鬼よ！",
  ui_story_5004_50040201_20_dialog_content = "何！？",
  ui_story_5004_50040201_21_dialog_content = "痛ッ…クソったれ、どっから来やがった…！20数年生きてきたが、初めて車で…",
  ui_story_5004_50040201_22_dialog_content = "グオォ――",
  ui_story_5004_50040201_23_dialog_content = "うぅ…少しめまいがするわ…暗鬼をはねちゃったの？",
  ui_story_5004_50040201_24_dialog_content = "みんな無事だね…？",
  ui_story_5004_50040201_25_dialog_content = "ええ、軽傷で済んだわ。",
  ui_story_5004_50040201_26_dialog_content = "グアァァ――！！",
  ui_story_5004_50040201_27_dialog_content = "暗鬼がこんなにたくさん…みんな！戦闘準備を！",
  ui_story_5004_50040201_28_dialog_content = "武器はトランクに詰めちゃってるわ、座席を空けるために…！",
  ui_story_5004_50040201_29_dialog_content = "モタモタしてたら囲まれるわ！",
  ui_story_5004_50040201_30_dialog_content = "ベリエちゃん、目を覚まして。",
  ui_story_5004_50040201_31_dialog_content = "うっ…",
  ui_story_5004_50040201_32_dialog_content = "ラファエル…？",
  ui_story_5004_50040201_33_dialog_content = "危ない――！",
  ui_story_5004_50040201_34_dialog_content = "…！！",
  ui_story_5004_50040201_35_dialog_content = "血染めの結晶…！",
  ui_story_5004_50040201_36_dialog_content = "ガウッ…",
  ui_story_5004_50040201_37_dialog_content = "グオォ！！グゴゴオォ！！！",
  ui_story_5004_50040201_38_dialog_content = "車をひっくり返すつもり！？",
  ui_story_5004_50040201_39_dialog_content = "咲き誇れ！！",
  ui_story_5004_50040201_40_dialog_content = "ガゥ…",
  ui_story_5004_50040201_41_dialog_content = "強い…一瞬で倒した！？",
  ui_story_5004_50040201_42_dialog_content = "あなたにこれほどのパワーがあったなんて。\n真理結社も単なる凡人の集まりではなさそうね。",
  ui_story_5004_50040201_43_dialog_content = "一度にあんなにたくさんの結晶を放出して暗鬼を倒すだなんて、\n白夜城の天使にも引けを取らないわね。",
  ui_story_5004_50040201_44_dialog_content = "違いないわ。",
  ui_story_5004_50040201_45_dialog_content = "すごい…あっ、ベリエちゃん！ありがとう！",
  ui_story_5004_50040201_46_dialog_content = "はぁ…はぁ…",
  ui_story_5004_50040201_47_dialog_content = "ベリエちゃん？…大丈夫？",
  ui_story_5004_50040201_48_dialog_content = "おいおい、お嬢ちゃんたち、おしゃべりはその辺にして、\n今のうちに武器を取ってきな。まだまだ暗鬼がやってくるよ！",
  ui_story_5004_50040301_1_dialog_content = "ふぅ――どうにか着いたよ。とうぶん運転はしたくないね。",
  ui_story_5004_50040301_2_dialog_content = "手足がついたままで送り届けてくれてありがとう…",
  ui_story_5004_50040301_3_dialog_content = "無駄口叩いてないで、駐車場を探しな。",
  ui_story_5004_50040301_4_dialog_content = "おい！お前たち、なんでここにいるんだ？",
  ui_story_5004_50040301_5_dialog_content = "それに俺の車まで！どうしてフロントカバーがヘコんでるんだ！？",
  ui_story_5004_50040301_6_dialog_content = "PlayerName、俺たちの仲とはいえ、きっちり説明してくれないと困るぜ。",
  ui_story_5004_50040301_7_option_content = "じ、実はレジーナがドライブしたいって言いだして…",
  ui_story_5004_50040301_8_dialog_content = "バカ言え、ドライブしたいっつったって、\nレジーナが自分で運転するなんてありえねーよ。",
  ui_story_5004_50040301_9_dialog_content = "どんな弱みを握ったってんだ？",
  ui_story_5004_50040301_10_dialog_content = "ナメんじゃないよ。\n私が弱みを握られたぐらいで動くようなヤツだとでも？",
  ui_story_5004_50040301_11_dialog_content = "それなら…PlayerNameに音響設備を\nグレードアップしてやるとでも言われたな？",
  ui_story_5004_50040301_12_dialog_content = "言い当てられた！？",
  ui_story_5004_50040301_13_dialog_content = "何だよ？俺だってバカじゃない。\nお前らがするような取引なんて一瞬でお見通しだ！",
  ui_story_5004_50040301_14_option_content = "修理した君の車を届けに来たんだよ！",
  ui_story_5004_50040301_15_dialog_content = "何？俺がここにいるってこと、お前に話したか？",
  ui_story_5004_50040301_16_dialog_content = "か、感知能力で突き止めたんだ！",
  ui_story_5004_50040301_17_dialog_content = "ずいぶん離れてるのに感知できたってのか！？すげぇな！",
  ui_story_5004_50040301_18_dialog_content = "ボンネットのヘコみは…暗鬼のせいか？",
  ui_story_5004_50040301_19_dialog_content = "そんなことまで分かるの！？",
  ui_story_5004_50040301_20_dialog_content = "おいおい、俺を見くびるなよな。\nこちとら1年でサイテー何百匹かは暗鬼をはねてるんだ。",
  ui_story_5004_50040301_21_dialog_content = "この形を見れば一発で分かる。手強いのを仕留めたな？",
  ui_story_5004_50040301_22_dialog_content = "どんな暗鬼だったかまで分かるの！？ごめん、ちゃんと修理して返すよ！",
  ui_story_5004_50040301_23_dialog_content = "気にしなくていいぜ。\n俺の愛車にまた1つ手柄を立てさせてくれたってことにしておくからよ。",
  ui_story_5004_50040301_24_dialog_content = "あとで<color=#FFB400>整備士のダチ</color>に修理を頼むさ。",
  ui_story_5004_50040301_25_dialog_content = "ところで、お前たち何しに来たんだ？バカンスか？",
  ui_story_5004_50040301_26_dialog_content = "そうよ！フルート・プラチナからPlayerNameに招待状が来たの。\n宿泊もタダよ、タダ！",
  ui_story_5004_50040301_27_dialog_content = "何だって？そりゃあ珍しいな。\nあそこのオーナー、そんなに太っ腹だったか？",
  ui_story_5004_50040301_28_dialog_content = "空の末裔であるPlayerNameを\n宣伝に利用する心づもりかも知れないわ。",
  ui_story_5004_50040301_29_dialog_content = "なるほどな、それはあり得る。",
  ui_story_5004_50040301_X29_dialog_content = "ん！？何でお前がこんなところに！？",
  ui_story_5004_50040301_30_dialog_content = "あなたは、R・Wの脱獄犯…！",
  ui_story_5004_50040301_31_dialog_content = "待った待った！今回はベリエを旅行に連れて来たんだ。\n犯人逮捕が目的じゃないでしょ！",
  ui_story_5004_50040301_32_dialog_content = "それにここは白夜城じゃないし、今は争いはよそう！ね？",
  ui_story_5004_50040301_33_dialog_content = "…仕方ないわね。",
  ui_story_5004_50040301_34_dialog_content = "でも、私がここにいる間、白夜城に害をなすようなことがあれば…",
  ui_story_5004_50040301_35_dialog_content = "連行して裁判を受けさせるわ。",
  ui_story_5004_50040301_36_dialog_content = "そういえば、ヘールはどうしてここにいるの？\nホテルのオーナーと知り合いみたいだけど。",
  ui_story_5004_50040301_37_dialog_content = "そのことか…ダチの手伝いに来たんだよ。さっき言った整備士のな。",
  ui_story_5004_50040301_38_dialog_content = "何つーか…俺も俺の車も、アイツには世話になってるからな。\n受けた恩は必ず返す。それがR・Wの美徳だ。",
  ui_story_5004_50040301_39_dialog_content = "フルート・プラチナに行くなら、アイツに会えると思うぜ。",
  ui_story_5004_50040301_40_dialog_content = "ひと目で分かる。色んな意味で目立つからな。",
  ui_story_5004_50040301_41_dialog_content = "そうだ、もう1ついいかな？",
  ui_story_5004_50040301_42_dialog_content = "ソラヴァンでここに向かってくる途中、\n干渉を受けたんだけど、何が原因か分かる？",
  ui_story_5004_50040301_43_dialog_content = "さあな。俺は巨像なんか運転したことないぜ。",
  ui_story_5004_50040301_44_dialog_content = "誰でも巨像を持ってるみたいに言うなよな？",
  ui_story_5004_50040301_45_dialog_content = "けど、巨像ってのは生き物と機械のあいのこ、なんだろ？",
  ui_story_5004_50040301_46_dialog_content = "ソラヴァンのヤツ、風邪でも引いたんじゃないか？",
  ui_story_5004_50040301_47_dialog_content = "<size=30>PlayerName…今のは冗談として受け取るべきかしら…？</size>",
  ui_story_5004_50040301_48_dialog_content = "<size=30>どうだろう…冗談なのか本気なのか分かんないや…</size>",
  ui_story_5004_50040301_49_dialog_content = "目の前で何ヒソヒソ話してやがる？",
  ui_story_5004_50040301_50_dialog_content = "そんじゃ、車は乗ってくぜ。この道沿いに行けばホテルに着く。",
  ui_story_5004_50040301_51_dialog_content = "（きれいだな…金色に輝く砂浜に青い波が打ち寄せてる）",
  ui_story_5004_50040301_52_dialog_content = "（向こうには名前の知らない青々とした木がそびえ立ってる。潮風に揺られて美しい）",
  ui_story_5004_50040301_53_dialog_content = "（それからビーチではしゃぐ人々）",
  ui_story_5004_50040301_54_dialog_content = "（のどかな太陽の光を全身に浴びて、何もかもが生き生きとしてる。\n思わず見入っちゃうな）",
  ui_story_5004_50040301_55_dialog_content = "…",
  ui_story_5004_50040301_56_dialog_content = "…想像してた以上に素晴らしい景色だね。",
  ui_story_5004_50040301_57_dialog_content = "PlayerName！ここが海よね…？",
  ui_story_5004_50040301_58_dialog_content = "このご時世に、こんな風にくつろげる場所があるだなんてね。",
  ui_story_5004_50040301_59_dialog_content = "きれいな海…",
  ui_story_5004_50040301_60_dialog_content = "ベリエちゃん、向こうの屋台に行列ができてるよ！見に行こうよ！",
  ui_story_5004_50040301_61_dialog_content = "うふふ…みなさん、<color=#FFB400>ルシェル・ド・アンジュビーチ</color>を\n気に入って頂けたようですね。",
  ui_story_5004_50040301_62_dialog_content = "！？",
  ui_story_5004_50040301_63_dialog_content = "慌てないでください。私は<color=#FFB400>ボナーズ</color>。\nホテルでゲストの応接を担当している者です。今回の潮汐祭の主催者でもあります。",
  ui_story_5004_50040301_64_dialog_content = "あ、ボナーズ…",
  ui_story_5004_50040301_65_dialog_content = "ベリエ、あなたも来たんですね。あの嫌味なメガネ男は一緒じゃありませんよね？",
  ui_story_5004_50040301_66_dialog_content = "ファウストのこと？…仕事があるからって、\n私はPlayerNameに預けられたの…",
  ui_story_5004_50040301_67_dialog_content = "そうでしたか。ということは、こちらの方がPlayerNameですね。",
  ui_story_5004_50040301_68_dialog_content = "大勢のかわいい女性に囲まれて、ずいぶんとおモテになるようですね。",
  ui_story_5004_50040301_69_dialog_content = "単なる仲間同士だよ…",
  ui_story_5004_50040301_70_dialog_content = "仲間、ですか…うふふ…",
  ui_story_5004_50040301_71_dialog_content = "改めてお顔を拝見しましたが、\n空の末裔には長い角や第3の目などはついていないのですね。",
  ui_story_5004_50040301_72_option_content = "悪かったね",
  ui_story_5004_50040301_73_dialog_content = "あら、面白いお方ですね。",
  ui_story_5004_50040301_74_option_content = "空の末裔と光霊の見た目はかなり似てるんだよ",
  ui_story_5004_50040301_75_dialog_content = "生真面目にお答えになるところも面白いですね。",
  ui_story_5004_50040301_76_dialog_content = "冗談を言ってみただけですから、かしこまらないでください。",
  ui_story_5004_50040301_77_dialog_content = "みなさんはホテルの大切なゲストです。\nそれから、潮汐祭の主要な参加者でもあります。",
  ui_story_5004_50040301_78_dialog_content = "この私、ボナーズが、真夏のビーチにふさわしい情熱的なサービスで\nみなさまにご奉仕させていただきます――",
  ui_story_5004_50040301_79_dialog_content = "いいよいいよ、自分たちのことは自分たちでやれるから。",
  ui_story_5004_50040301_80_dialog_content = "それより聞きたいんだけど、潮汐祭ってどんなお祭りなの？",
  ui_story_5004_50040301_81_dialog_content = "潮汐祭は、昔々、砂浜に暮らしていた光霊たちから\n受け継がれてきたお祭りです。",
  ui_story_5004_50040301_82_dialog_content = "「海は万物の源である。広大な胸にあらゆるものを迎え入れ、万物を育む。」",
  ui_story_5004_50040301_83_dialog_content = "「海を守る女神と海に挑む英雄たちが、ここで共に舞を繰り広げる。」",
  ui_story_5004_50040301_84_dialog_content = "潮汐祭を通じて、伝説で語られる「試練」を再現するのです。",
  ui_story_5004_50040301_85_dialog_content = "すなわち、<color=#FFB400>力</color>、<color=#FFB400>知恵</color>、<color=#FFB400>勇気</color>の3つを競い合い、\n最後まで勝ち残った者を勝者とするのです。",
  ui_story_5004_50040301_86_dialog_content = "神様は勝者に褒美を与え、この浜は天候に恵まれるよう祝福を受け、\n漁に出ればいつも大漁になるといいます。",
  ui_story_5004_50040301_87_dialog_content = "そして勝者は<color=#FFB400>「砂浜の勇者」</color>の称号を得るのです。",
  ui_story_5004_50040301_88_dialog_content = "その他、盛りだくさんの賞品やお楽しみの優勝賞品もご用意していますよ！",
  ui_story_5004_50040301_89_dialog_content = "夏の日差しと浜辺の風情を味わいながら、皆さんで色々な競技にご参加ください。",
  ui_story_5004_50040301_90_dialog_content = "もちろん、参加してくださいますよね。",
  ui_story_5004_50040301_91_dialog_content = "砂浜の…勇者…",
  ui_story_5004_50040301_92_dialog_content = "とりあえず、みんなに相談してからじゃないと…",
  ui_story_5004_50040301_93_dialog_content = "ええ、結構ですよ。ひとまず皆さんをロビーへお連れして、\nチェックインの手続きをいたしましょう。",
  ui_story_5004_50040301_94_dialog_content = "お祭りは明後日からになりますから、\n今日と明日は思う存分に羽を伸ばしてくださいね。",
  ui_story_5004_50040301_95_dialog_content = "…すごく豪華だ！",
  ui_story_5004_50040301_96_dialog_content = "確かに、白夜城や啓光の建築物とは様式が違うわ。",
  ui_story_5004_50040301_97_dialog_content = "旧文明の様式かしら？",
  ui_story_5004_50040301_98_dialog_content = "こちらがロビーです。\nあとはマネージャーの<color=#FFB400>フェラール</color>にお任せしましょう――",
  ui_story_5004_50040301_99_dialog_content = "フェラール？お客様ですよ？早くお迎えしてください。",
  ui_story_5004_50040301_100_dialog_content = "私は他に片付けることがありますので、ひとまずここで失礼しますね。\nまた後ほどお会いしましょう。",
  ui_story_5004_50040301_101_dialog_content = "フェラール？っていう人はどこにいるんだろう？",
  ui_story_5004_50040301_102_dialog_content = "す、すまない！",
  ui_story_5004_50040301_103_dialog_content = "今すぐ行くよ…！",
  ui_story_5004_50040301_104_dialog_content = "フェラール！",
  ui_story_5004_50040301_105_dialog_content = "フェラール様～！",
  ui_story_5004_50040301_106_dialog_content = "フェラールさん、今晩おヒマですか？",
  ui_story_5004_50040301_107_dialog_content = "ラルラル！僕と一緒にフィットネスに行かないか。\n俺のパーフェクトな腓腹筋を見てくれ――！！",
  ui_story_5004_50040301_108_dialog_content = "さっき焼いたおやつだよ。一口食べてみてよ、あ～ん…",
  ui_story_5004_50040301_109_dialog_content = "こんな人だかり、一体どうしたんだろう？それにフェラールって人も…",
  ui_story_5004_50040301_110_dialog_content = "あの人…奇妙な感じがするわ。",
  ui_story_5004_50040301_111_dialog_content = "PlayerName、あんたよりフェラールのほうが人気者みたいだな！",
  ui_story_5004_50040301_112_dialog_content = "僕はそういうのじゃないって…",
  ui_story_5004_50040301_113_dialog_content = "お待たせしてすまない。俺がフェラールだよ。\n巨像から来たっていうのは、キミたちだね？",
  ui_story_5004_50040301_114_dialog_content = "それから空の末裔、PlayerNameだな。\nヘールから話はよく聞いてるぜ。",
  ui_story_5004_50040301_115_dialog_content = "ヘールの知り合い？",
  ui_story_5004_50040301_116_dialog_content = "ああ。本職はR・Wの整備士なんだ。ヘールとは長い付き合いだ。",
  ui_story_5004_50040301_117_dialog_content = "ヘールが言ってた整備士って、君のことだったんだね！\n（確かに、すごく目立ってる…）",
  ui_story_5004_50040301_118_dialog_content = "そうさ。彼にも手伝ってもらってるんだ。",
  ui_story_5004_50040301_119_dialog_content = "あっ！思い出した。フェラールって、\n啓光の機械学院で伝説になってる人よね！",
  ui_story_5004_50040301_120_dialog_content = "啓光の先輩から話を聞いたことがあるわ。",
  ui_story_5004_50040301_121_dialog_content = "機械技術に精通してて、その上性格もいいって。\n<size=40>だけど…</size><size=35>ヘンというか</size><size=30><color=#FFB400>あんまりよくない噂も耳にしたわね</color>…</size>",
  ui_story_5004_50040301_122_dialog_content = "そんなヤツが、どうしてR・Wの整備士なんかになったんだ？",
  ui_story_5004_50040301_123_dialog_content = "サメヤマの兄貴がトラベラーの修理を任せてるぐらいだし、腕は確かなのによ。",
  ui_story_5004_50040301_124_dialog_content = "そういや、忙しいって言ってたよな。\n兄貴からキッチリ夏休みをもらって来たんだろうな？",
  ui_story_5004_50040301_125_dialog_content = "それに、こんなところでマネージャーなんて…\nそんな格好じゃマズいんじゃないのか？",
  ui_story_5004_50040301_126_dialog_content = "白夜城の貴族だって、中身はともかく身なりだけはご立派にしてるぜ。\nあんたもネクタイくらい締めるべきじゃないのか？",
  ui_story_5004_50040301_127_dialog_content = "…",
  ui_story_5004_50040301_128_dialog_content = "（白夜城の貴族、こっちにもいるんだけど…！）",
  ui_story_5004_50040301_129_dialog_content = "ここへ来たのはボナーズに呼ばれたからなんだ。\nまぁ、他にもちょっとした理由はあったけどな。",
  ui_story_5004_50040301_130_dialog_content = "ま～たうまいこと騙されてんじゃないか？あんたらしいよ。",
  ui_story_5004_50040301_131_dialog_content = "まぁいい、ガイドと運転手の仕事はここまでだ。\n私は酒場の音響設備を見てくるよ。",
  ui_story_5004_50040301_132_dialog_content = "用がない限り邪魔するなよ。",
  ui_story_5004_50040301_133_dialog_content = "ああ、気をつけてな、レジーナ。",
  ui_story_5004_50040301_134_dialog_content = "それじゃみんな、こちらへどうぞ。部屋を用意する。",
  ui_story_5004_50040301_135_dialog_content = "部屋割りはどうする？",
  ui_story_5004_50040301_136_dialog_content = "えっと、私…",
  ui_story_5004_50040301_137_dialog_content = "私はベリエちゃんと同じ部屋がいい！",
  ui_story_5004_50040301_138_dialog_content = "ベリエちゃんのお医者さんだもん、ずっと一緒にいなきゃ！",
  ui_story_5004_50040301_139_dialog_content = "いいでしょいいでしょ～！",
  ui_story_5004_50040301_140_dialog_content = "い、いいわ…私はそれで…問題ない…",
  ui_story_5004_50040301_141_dialog_content = "私とバイスはそれぞれひと部屋ずつにして。",
  ui_story_5004_50040301_142_option_content = "じゃあ僕は…",
  ui_story_5004_50040301_143_dialog_content = "あなたも1人で問題ないでしょう？ソラヴァンで10数年も一人だったんだもの、\n暗がりが怖いなんてこと、ないわよね。",
  ui_story_5004_50040301_144_dialog_content = "も、もちろん！1人で眠れるよ！",
  ui_story_5004_50040301_145_option_content = "レジーナは？",
  ui_story_5004_50040301_146_dialog_content = "彼女のことだから、音響設備に夢中で、\n数日はこっちに来ないでしょうね…",
  ui_story_5004_50040301_147_dialog_content = "ひとまず代わりに部屋を決めておいてあげよう。\nあとで鍵を渡してくるよ。",
  ui_story_5004_50040301_148_dialog_content = "それじゃあ…全部で5部屋だな。",
  ui_story_5004_50040301_149_dialog_content = "チ、チップを…",
  ui_story_5004_50040301_150_dialog_content = "おっと、こちらのみんなはホテルの特別なゲストだ。\nチップなんてねだるんじゃないぞ。",
  ui_story_5004_50040301_151_dialog_content = "は、はい…",
  ui_story_5004_50040301_152_dialog_content = "それじゃ、これがみんなの部屋の鍵だ。",
  ui_story_5004_50040301_153_dialog_content = "さっきのベルボーイさん、なんか見た目が変じゃなかった…？",
  ui_story_5004_50040301_154_dialog_content = "あはは、PlayerName。そんなことは言っちゃいけないよ。",
  ui_story_5004_50040301_155_dialog_content = "俺の頭にだって角が生えてるんだから。",
  ui_story_5004_50040301_156_dialog_content = "色々あるかもしれないが、\n俺はみんなが仲良くやっていければいいと思ってるんだ。",
  ui_story_5004_50040301_157_dialog_content = "（フェラール、いい人なんだね…）",
  ui_story_5004_50040301_158_dialog_content = "確かに…あいつら、変わった行動をすることはあるが…",
  ui_story_5004_50040301_159_dialog_content = "給料は安くていいし、残業もタダでやるって言うから、\nオーナーがそこを気に入ってな。",
  ui_story_5004_50040301_160_dialog_content = "迷いもせずに大勢を採用したんだとさ。",
  ui_story_5004_50040301_161_dialog_content = "そういえば、ヘールも言ってた。オーナーが変わった人なんだって？",
  ui_story_5004_50040301_162_dialog_content = "変わった人ねえ…影ノ街のとある組織のボスらしいとは聞いてるが…",
  ui_story_5004_50040301_163_dialog_content = "確かにビジネスセンスはあるし、金儲けに貪欲だ。\nだけど、ホテルの経営以外にも、良からぬことに手を出してるって噂を聞いたな。",
  ui_story_5004_50040301_164_dialog_content = "その辺は俺もあまり良くないと思ってるんだ。\nけど、ボナーズとの約束があるから、臨時の手伝いを断れなくてな。",
  ui_story_5004_50040301_165_dialog_content = "そうだ、注意しておくことがある。\nホテルやビーチで買い物する時は、ぼられることがあるから気をつけて。",
  ui_story_5004_50040301_166_dialog_content = "不逞の商人がいるのね。心しておくわ。",
  ui_story_5004_50040301_167_dialog_content = "それじゃ、みんなをそれぞれの部屋へ案内するよ。こちらへ。",
  ui_story_5004_50040401_168_dialog_content = "どうぞ、PlayerName。",
  ui_story_5004_50040401_169_dialog_content = "ここが僕の部屋かぁ。",
  ui_story_5004_50040401_170_dialog_content = "気に入ってくれると嬉しいよ。",
  ui_story_5004_50040401_171_dialog_content = "そうだ、実は機械のことについて、\n巨像の持ち主であるキミと込み入った話がしたいと思っててさ。",
  ui_story_5004_50040401_172_dialog_content = "でも今日は疲れただろうし、また今度話をしよう。",
  ui_story_5004_50040401_173_dialog_content = "それじゃ、ゆっくり休んでくれ。\n何かあれば、あそこの<color=#FFB400>通信装置</color>でフロントといつでも連絡が取れるから。",
  ui_story_5004_50040401_174_dialog_content = "分かったよ。ありがとう！",
  ui_story_5004_50040401_175_dialog_content = "…",
  ui_story_5004_50040401_176_dialog_content = "部屋は清潔だし、ベッドも心地よさそうだ。\nカーテンを開けると夜の海が見える…",
  ui_story_5004_50040401_177_dialog_content = "整然とした啓光の街並みとも、白夜城の華麗な雰囲気とも違う。\nここには生命力やエネルギーが溢れてる。",
  ui_story_5004_50040401_178_dialog_content = "ふぅ…",
  ui_story_5004_50040401_179_dialog_content = "思った通りふかふかだ…",
  ui_story_5004_50040401_180_dialog_content = "突然招待されて、海へ遊びに来て…こんなに心地いいベッドで横になってる。\nまるで夢を見てるみたいだ…",
  ui_story_5004_50040401_181_dialog_content = "あと、潮汐祭だっけ…参加するべきかな？なんだか怪しい気がするけど…",
  ui_story_5004_50040401_182_dialog_content = "みんなは今ごろ何をしてるんだろう…",
  ui_story_5004_50040401_183_dialog_content = "<color=#e8d9bb>ジリリリン――</color>",
  ui_story_5004_50040401_184_dialog_content = "え？何の音！？あ、さっきフェラールが言ってた通信装置かな？",
  ui_story_5004_50040401_185_dialog_content = "もしもし…？",
  ui_story_5004_50040401_186_dialog_content = "あ、もしもし！？",
  ui_story_5004_50040401_187_dialog_content = "チラシを見たんだけどよ…「7日間ですべての潜在能力を引き出し、\nより一層強い自分に成長できる」って本当か！？",
  ui_story_5004_50040401_188_dialog_content = "え？ヘール？何の話？",
  ui_story_5004_50040401_189_dialog_content = "…おい、なんでPlayerNameが出るんだよ。番号を間違えたか？",
  ui_story_5004_50040401_190_dialog_content = "話はまた今度な。今忙しいんだ！",
  ui_story_5004_50040401_191_dialog_content = "<color=#e8d9bb>ツーツーツー——</color>",
  ui_story_5004_50040401_192_dialog_content = "切れちゃった。何か怪しい…詐欺にでも遭ってないか心配だなぁ…",
  ui_story_5004_50040401_193_dialog_content = "…この装置、部屋番号を入力すれば直接つながるのかな…？",
  ui_story_5004_50040401_194_dialog_content = "試してみよう――！",
  ui_story_5004_50040401_195_option_content = "バイスにつなぐ",
  ui_story_5004_50040401_196_dialog_content = "もしもし、ナビゲーター？",
  ui_story_5004_50040401_197_dialog_content = "ホテルにこんなに便利な通信装置があるとは思わなかったわ。",
  ui_story_5004_50040401_198_dialog_content = "今お邪魔じゃなかった？特に用はないんだけど、\n手持無沙汰だったからバイスは何をしてるのか気になったんだ。",
  ui_story_5004_50040401_199_dialog_content = "別に何もしてないわ。ベッドでごろごろしてるところよ。とっても快適ね。",
  ui_story_5004_50040401_200_dialog_content = "ねぇ、潮汐祭のこと、どう思う？参加するべきかな？",
  ui_story_5004_50040401_201_dialog_content = "もちろんでしょ！フェラールも言ってたじゃない。",
  ui_story_5004_50040401_202_dialog_content = "それに、ホテルの宿泊代はタダだけど、\n食事や水着を買うのにはやっぱりお金がかかるわ…",
  ui_story_5004_50040401_203_dialog_content = "私たちのお財布事情だと、単にお金を使うだけじゃ…",
  ui_story_5004_50040401_204_dialog_content = "僕、スポーツの試合なんて勝てる自信がないよ…",
  ui_story_5004_50040401_205_dialog_content = "心配しないで。私や他のみんながいるわ。\n全力でサポートするから。",
  ui_story_5004_50040401_206_dialog_content = "それに、PlayerNameには指揮能力があるじゃない。\n他の人にはない大きな強みになるわ！",
  ui_story_5004_50040401_207_dialog_content = "そうだね、君の言う通りかもしれない…",
  ui_story_5004_50040401_208_dialog_content = "でも、もし賞品が白夜コインじゃなかったらどうする？",
  ui_story_5004_50040401_209_dialog_content = "どうってことないわよ。\nシェオルさん辺りが買ってくれるんじゃないかしら。",
  ui_story_5004_50040401_210_dialog_content = "とにかく安心して。今はゆっくり休みましょ。\n私たち、必ず優勝できるわ！",
  ui_story_5004_50040401_211_dialog_content = "バイスがそう言うなら、力を合わせて頑張ろう！",
  ui_story_5004_50040401_212_option_content = "カレンにつなぐ",
  ui_story_5004_50040401_213_dialog_content = "PlayerName？何か用かしら？",
  ui_story_5004_50040401_214_dialog_content = "あ、邪魔だったらごめん。\nカレンが何をしているのか気になっただけなんだ。",
  ui_story_5004_50040401_215_dialog_content = "いつも通りよ。もうすぐ就寝するわ。",
  ui_story_5004_50040401_216_dialog_content = "カレンはストイックだね。",
  ui_story_5004_50040401_217_dialog_content = "そうだ、潮汐祭のことだけど、どう思う？",
  ui_story_5004_50040401_218_dialog_content = "私たちなら優勝できるわ。",
  ui_story_5004_50040401_219_dialog_content = "えっ？まだ参加するかどうかも決めてないのに？",
  ui_story_5004_50040401_220_dialog_content = "参加しないつもり？\n招待されて来た以上、挑戦に応じるのは定め。",
  ui_story_5004_50040401_221_dialog_content = "真の戦士たるもの、いかなる戦いからも逃げ出したりはしないわ。",
  ui_story_5004_50040401_222_dialog_content = "PlayerName、戸惑いや不安があることは分かるわ。",
  ui_story_5004_50040401_223_dialog_content = "けれど、自分には困難に打ち勝ち、道を切り拓く力があると、\nそう信じてあげなければ。",
  ui_story_5004_50040401_224_dialog_content = "私を含むすべての光霊にとって、あなたは特別な存在なのよ。",
  ui_story_5004_50040401_225_dialog_content = "もしかして、激励してくれてる…？",
  ui_story_5004_50040401_226_dialog_content = "当然でしょう。戦う前には士気を高めるものよ。",
  ui_story_5004_50040401_227_dialog_content = "さすがは白夜城の護衛隊隊長だね。\nありがとう、やる気が出たよ。",
  ui_story_5004_50040401_228_dialog_content = "よかったわ。それなら、ゆっくり休むことね。",
  ui_story_5004_50040401_229_dialog_content = "うん。お祭りに参加すると決めたからには、\n英気を養っておかないとね！",
  ui_story_5004_50040401_230_dialog_content = "そういえば、みんなの部屋ってどれもシングルベッドなのかな？",
  ui_story_5004_50040401_230X1_dialog_content = "<color=#e8d9bb>ドンッ――！</color>",
  ui_story_5004_50040401_230X2_dialog_content = "うわっ！",
  ui_story_5004_50040401_230X3_dialog_content = "おっとっと、ごめんね！ケガはない？",
  ui_story_5004_50040401_230X4_dialog_content = "でも、どうしてお皿を持ったままドアの前に立ってるの？危ないよ？",
  ui_story_5004_50040401_230X5_dialog_content = "はぁ…はぁ…ラファエル…走るのが早すぎよ…",
  ui_story_5004_50040401_230X6_dialog_content = "こ、こちらのお部屋のお客様がお菓子をご所望でしたので、\nお運びしているのです。",
  ui_story_5004_50040401_230X7_dialog_content = "お怪我がないようでしたら失礼いたします。\n他のお客様をお待たせしておりますので…",
  ui_story_5004_50040401_230X8_dialog_content = "なんだか外が騒がしいなぁ…",
  ui_story_5004_50040401_230X9_dialog_content = "<color=#e8d9bb>トントントン</color>",
  ui_story_5004_50040401_231_dialog_content = "そういえば、ベリエたち2人は…",
  ui_story_5004_50040401_232_dialog_content = "PlayerName～！遊びに来たよ！\n私たちに隠れてこっそりおやつを食べようとしてたの？",
  ui_story_5004_50040401_233_dialog_content = "ラファエル？おやつなんて食べてないよ…",
  ui_story_5004_50040401_234_dialog_content = "こ、こんばんは…",
  ui_story_5004_50040401_235_dialog_content = "ベリエも来たんだね。",
  ui_story_5004_50040401_236_dialog_content = "ベリエちゃん、PlayerNameに話があるんでしょ？\nさあさあ、話して話して～！",
  ui_story_5004_50040401_237_dialog_content = "…でも…私のわがままだから…",
  ui_story_5004_50040401_238_dialog_content = "なぁに？話しづらいの？\nだったらラファエルが代わりに話してあげよっか？",
  ui_story_5004_50040401_239_dialog_content = "うん…",
  ui_story_5004_50040401_240_dialog_content = "りょ～かい、いいよいいよ～。",
  ui_story_5004_50040401_241_dialog_content = "あのね、ベリエちゃんは潮汐祭に参加したいって思ってるの。",
  ui_story_5004_50040401_242_dialog_content = "そうなんだ。",
  ui_story_5004_50040401_243_dialog_content = "でも、ベリエちゃん自身は参加できないの。",
  ui_story_5004_50040401_244_dialog_content = "えぇ？",
  ui_story_5004_50040401_245_dialog_content = "PlayerName、鈍すぎるよ～！\n私の言いたいことが分かんないの？",
  ui_story_5004_50040401_246_dialog_content = "…ラファエル、PlayerNameを責めないで…\n私のわがままなんだから…",
  ui_story_5004_50040401_247_dialog_content = "PlayerName、賞品の話、覚えてる？",
  ui_story_5004_50040401_248_dialog_content = "ああ、ベリエも賞金が欲しいの？実は僕たちも――",
  ui_story_5004_50040401_249_dialog_content = "違うよ～！「砂浜の勇者」って称号のこと！",
  ui_story_5004_50040401_250_dialog_content = "…？",
  ui_story_5004_50040401_251_dialog_content = "なぁにその顔！\n乙女の純粋な憧れの気持ちなんだよ！？",
  ui_story_5004_50040401_252_dialog_content = "否定するつもりはないよ！\nちょっと理解が追い付かなかっただけだよ。",
  ui_story_5004_50040401_253_dialog_content = "ベリエ…本当に参加したいの？",
  ui_story_5004_50040401_254_dialog_content = "うん…！",
  ui_story_5004_50040401_255_dialog_content = "参加すること自体は問題ないよ…\nみんなもそのつもりみたいだったしね。",
  ui_story_5004_50040401_256_dialog_content = "ほ、本当に？",
  ui_story_5004_50040401_257_dialog_content = "よかった…",
  ui_story_5004_50040401_258_dialog_content = "でも、君は参加できないってどういう意味？",
  ui_story_5004_50040401_259_dialog_content = "ベリエちゃんはね～…",
  ui_story_5004_50040401_260_dialog_content = "ラファエル…その話は自分でするわ、ありがとう…",
  ui_story_5004_50040401_261_dialog_content = "…",
  ui_story_5004_50040401_262_dialog_content = "今日、私の能力は見たでしょう？",
  ui_story_5004_50040401_263_dialog_content = "うん、ものすごいパワーだったね。",
  ui_story_5004_50040401_264_dialog_content = "でも、すぐに暴走するから、とても危ないの…",
  ui_story_5004_50040401_265_dialog_content = "それに、放つ力が強ければ強いほど、\n私の心や体への影響も大きくなるわ…",
  ui_story_5004_50040401_266_dialog_content = "今日みんなを助ける時に、たくさんの暗鬼を一度に相手にしたから…\nしばらくは激しい運動ができないの…",
  ui_story_5004_50040401_267_dialog_content = "なるほどね。分かったよ。\n僕たちを助けてくれたんだし、今度は僕たちが君を助ける番だ。",
  ui_story_5004_50040401_268_dialog_content = "みんなにも、ベリエは補欠として参加するって伝えておくね。",
  ui_story_5004_50040401_269_dialog_content = "実際に試合に出るかどうかは、体調を見て自分で判断してくれればいいよ。",
  ui_story_5004_50040401_270_dialog_content = "そういうことでいいかな？",
  ui_story_5004_50040401_271_dialog_content = "ええ…！",
  ui_story_5004_50040401_272_dialog_content = "そういえば、さっき心にも影響があるって言ってたよね？\n具体的にはどういうものなの？",
  ui_story_5004_50040401_273_dialog_content = "…とても悲しくなったり、絶望したりするわ…\nそうなると力もさらに大きくなって…ますます制御が効かなくなるの。",
  ui_story_5004_50040401_274_dialog_content = "それじゃ悪循環だね…",
  ui_story_5004_50040401_275_dialog_content = "ええ…",
  ui_story_5004_50040401_276_dialog_content = "…いつか悲しみや絶望にとらわれなくなって、\n自分の力をコントロールする勇気が持てるようになるといいね。",
  ui_story_5004_50040401_277_dialog_content = "そうなれた時には、どれほどの力が出せるようになるかな。\nちょっと楽しみだよ。",
  ui_story_5004_50040501_1_dialog_content = "…",
  ui_story_5004_50040501_2_dialog_content = "…",
  ui_story_5004_50040501_3_dialog_content = "…巨像以外の場所で寝るのはやっぱり慣れないなぁ…",
  ui_story_5004_50040501_4_option_content = "ゴロゴロする",
  ui_story_5004_50040501_5_dialog_content = "<color=#e8d9bb>トントントン――</color>",
  ui_story_5004_50040501_6_dialog_content = "PlayerName、起きてる？",
  ui_story_5004_50040501_7_option_content = "もう一度起きる",
  ui_story_5004_50040501_8_dialog_content = "うん…今ドアを開けるから待って。",
  ui_story_5004_50040501_9_dialog_content = "<color=#e8d9bb>ガチャ</color>",
  ui_story_5004_50040501_10_dialog_content = "おはよう、PlayerName。早く準備して。",
  ui_story_5004_50040501_11_dialog_content = "カレンたちはレストランで待ってるわ。",
  ui_story_5004_50040501_12_dialog_content = "おはよう、PlayerName。あまり休めなかったみたいね。",
  ui_story_5004_50040501_13_dialog_content = "おはよう。巨像以外の場所で寝るのに慣れてなくて…",
  ui_story_5004_50040501_14_dialog_content = "でも、特別な体験ができて、嬉しい気分なんだ。",
  ui_story_5004_50040501_15_dialog_content = "バイスとカレンに出会えてから、\n想像もできなかったようなことばかり経験してるよ。",
  ui_story_5004_50040501_16_dialog_content = "急に改まってどうしたの？",
  ui_story_5004_50040501_17_dialog_content = "ここの潮風には「魔力」でもあるのかしら。",
  ui_story_5004_50040501_18_dialog_content = "あははは…単純に寝不足なだけだよ…",
  ui_story_5004_50040501_19_dialog_content = "ラファエルとベリエは？",
  ui_story_5004_50040501_20_option_content = "よく眠れた？",
  ui_story_5004_50040501_21_dialog_content = "ええ…ベッドがちょっと窮屈だったけど…",
  ui_story_5004_50040501_22_dialog_content = "（やっぱりシングルベッドだったんだ…）",
  ui_story_5004_50040501_23_dialog_content = "PlayerName、知ってる？\nベリエちゃん、寝る時は何かを抱いて寝る派なんだよ～",
  ui_story_5004_50040501_24_dialog_content = "ま、枕を抱いて寝るのは普通でしょう…？",
  ui_story_5004_50040501_25_option_content = "ベッドは二つあったの？",
  ui_story_5004_50040501_26_dialog_content = "いいえ。ちょっぴり…窮屈だったわ…",
  ui_story_5004_50040501_27_dialog_content = "シングルベッドにベリエちゃんと私と、\nそれから超～でっかい枕が乗ってたからね。",
  ui_story_5004_50040501_28_dialog_content = "あれは私の…",
  ui_story_5004_50040501_29_dialog_content = "ベリエは抱き枕を使うんだね。",
  ui_story_5004_50040501_30_dialog_content = "ま、枕を抱いて寝るのは普通でしょう…？",
  ui_story_5004_50040501_31_dialog_content = "確かに初めは枕を抱いてたよ。",
  ui_story_5004_50040501_32_dialog_content = "そ、それ以上は言わないで！",
  ui_story_5004_50040501_33_dialog_content = "おはよう。よく休めたか？",
  ui_story_5004_50040501_34_dialog_content = "おはよう、フェラール。",
  ui_story_5004_50040501_35_dialog_content = "おかげさまで。部屋の設備は整ってたし、ベッドも心地よかったよ。",
  ui_story_5004_50040501_36_dialog_content = "まぁ、僕はあんまり慣れてなくて、寝つけなかったけど…",
  ui_story_5004_50040501_37_dialog_content = "あはは。宿泊客にはそういう人も多いんだ。\n特に今は、気軽に外出したり旅行したりなんてできないからな。",
  ui_story_5004_50040501_38_dialog_content = "外には暗鬼がウヨウヨいるから、\nいつもの自分の居場所でないと安心できない、ってな。",
  ui_story_5004_50040501_39_dialog_content = "気持ちは分かるよ。そういえばカレンが言ってたけど、\nホテルには<color=#FFB400>水着のお店</color>があるんだよね？",
  ui_story_5004_50040501_40_dialog_content = "フェラール、店の場所は知ってる？",
  ui_story_5004_50040501_41_dialog_content = "もちろん。<color=#FFB400>レストランの北東側</color>にあるよ。",
  ui_story_5004_50040501_42_dialog_content = "ありがとう。それじゃ、食事を終えたら出発しよう！",
  ui_story_5004_50040501_43_dialog_content = "お～～！！",
  ui_story_5004_50040601_44_dialog_content = "女の子の服選びって、こんなに時間がかかるものなのかな？",
  ui_story_5004_50040601_45_dialog_content = "<color=#FFB400>ビーチ</color>で待っててって言われたけど、\nもう小1時間待たされてる気がする…",
  ui_story_5004_50040601_46_dialog_content = "日差しが強いな。でも、こうやってのんびり日光を浴びるのも悪くないね…",
  ui_story_5004_50040601_47_dialog_content = "こうしてると、バイスたちとは単なる昔からの友達みたいな気がしてくるよ…\n暗鬼とか、奴らの陰謀とかについて考える必要さえなければ…",
  ui_story_5004_50040601_48_dialog_content = "のんびり太陽や海風を味わうって、本当に気持ちがいいな…",
  ui_story_5004_50040601_49_dialog_content = "…",
  ui_story_5004_50040601_50_dialog_content = "砂があったかい。何か描いてみようかな。",
  ui_story_5004_50040601_51_dialog_content = "PlayerName、それ、何描いてるの？タコ？",
  ui_story_5004_50040601_52_dialog_content = "猫だよ、猫！",
  ui_story_5004_50040601_53_dialog_content = "ああ、そのうねうねした触手みたいなのってヒゲだったの？",
  ui_story_5004_50040601_54_dialog_content = "私がもっときれいに描いてあげるわ。",
  ui_story_5004_50040601_55_dialog_content = "わっ、足で描かないでよ！腕よりヒゲが太いなんてヘンでしょ！\nもう、バイスは――",
  ui_story_5004_50040601_56_dialog_content = "…",
  ui_story_5004_50040601_57_dialog_content = "どうかした？",
  ui_story_5004_50040601_58_dialog_content = "なかなか…",
  ui_story_5004_50040601_59_dialog_content = "なかなか？何が？",
  ui_story_5004_50040601_60_dialog_content = "PlayerName、様子がおかしくない？",
  ui_story_5004_50040601_61_dialog_content = "まあいいわ。そんなことより海風を楽しまなくちゃ！",
  ui_story_5004_50040601_62_dialog_content = "やっぱり海と言えば水着よね。\nそれでこそ真夏のバカンスって感じだわ――",
  ui_story_5004_50040601_63_dialog_content = "あなたの水着、「ビーチの鎧」にしては頼りないわね！",
  ui_story_5004_50040601_64_dialog_content = "PlayerName！よく見ていなさい。\n荒波も怖れぬ騎士とは何か、私が教えてあげるわ――！",
  ui_story_5004_50040601_65_dialog_content = "（理由は違ってそうだけど、カレンまでテンションが高い…）",
  ui_story_5004_50040601_66_dialog_content = "（わざわざ僕に水着姿を見せつけようとするなんて…\nけっこう楽しんでるみたいだ）",
  ui_story_5004_50040601_67_dialog_content = "PlayerName、どうかしら？",
  ui_story_5004_50040601_68_dialog_content = "ど、どうかしらって？",
  ui_story_5004_50040601_69_dialog_content = "もちろん、水着のことよ。このビーチを制する勇者はどちらだと思う？",
  ui_story_5004_50040601_70_option_content = "バイスの水着は元気でかわいい感じだね",
  ui_story_5004_50040601_72_dialog_content = "PlayerNameはそういうのが好みなのね？",
  ui_story_5004_50040601_73_dialog_content = "でも、確かにバイスは学生の頃から元気いっぱいで知られていたわ。",
  ui_story_5004_50040601_74_dialog_content = "身体能力の訓練で目標の倍の数値を達成したり、\n何日も夜通しで授業の復習をしたりしていたわね。",
  ui_story_5004_50040601_75_dialog_content = "当然よ！体力と努力なら誰にも負けないわ！",
  ui_story_5004_50040601_76_option_content = "カレンの水着は上品で華やかだね",
  ui_story_5004_50040601_78_dialog_content = "私もそう思うわ！",
  ui_story_5004_50040601_79_dialog_content = "礼儀にうるさい世界で鍛えられてきたカレンだからこそ、\nここまでエレガントな雰囲気を醸し出せるのよ。",
  ui_story_5004_50040601_80_dialog_content = "啓光は命令至上主義の軍人気質だから、白夜城とは雰囲気が違うわね。",
  ui_story_5004_50040601_81_dialog_content = "学生の頃のバイスは、啓光の軍人でありながら、\n理科の成績では私に迫る勢いだったわね。",
  ui_story_5004_50040601_82_dialog_content = "えへへ。他に比べれば得意分野なのよ。",
  ui_story_5004_50040601_83_dialog_content = "芸術系の科目はまったくダメだったわね。",
  ui_story_5004_50040601_84_dialog_content = "それは…白夜城では機械製図が芸術科目に入ってなかったからよ。",
  ui_story_5004_50040601_85_dialog_content = "そもそも機械製図って芸術科目なの！？\n啓光以外じゃそんな授業はないと思うけど…",
  ui_story_5004_50040601_86_dialog_content = "あ、でも音楽の才能ならあるかもよ！\nPlayerNameが巨像を起動するのも手伝ってるし！",
  ui_story_5004_50040601_87_dialog_content = "はいはい。バイス中尉には僕とソラヴァンから\n改めてお礼を申し上げます、なんてね。",
  ui_story_5004_50040601_88_dialog_content = "実際、こうしてみんなと海で遊べるのは、君のお陰だよ。",
  ui_story_5004_50040601_89_dialog_content = "みんな、お待たせ～",
  ui_story_5004_50040601_90_dialog_content = "あれ、ラファエル？水着は？",
  ui_story_5004_50040601_91_dialog_content = "ラファエルはお医者さんとして勤務中なの！\n水着に着替えて、患者さんと一緒に気ままに遊びましょう！なんていかないよ。",
  ui_story_5004_50040601_92_dialog_content = "なるほどね。じゃあベリエは？",
  ui_story_5004_50040601_93_dialog_content = "あれ？ベリエちゃん？",
  ui_story_5004_50040601_94_dialog_content = "ベリエちゃん～！早くおいでよ。",
  ui_story_5004_50040601_95_dialog_content = "こっ…こんなのダメよ、恥ずかしすぎるわ…",
  ui_story_5004_50040601_96_dialog_content = "こんなに肌が露出する服は…今まで着たことがないの…",
  ui_story_5004_50040601_97_dialog_content = "恥ずかしがらないで！とってもかわいいよ～！",
  ui_story_5004_50040601_98_dialog_content = "ね、そうでしょ？PlayerName！",
  ui_story_5004_50040601_99_dialog_content = "うん、普段とは違う雰囲気だけど、すごく似合ってるよ。",
  ui_story_5004_50040601_100_dialog_content = "そうね。ベリエも砂浜の騎士として合格よ。私でも認めざるを得ないわ。",
  ui_story_5004_50040601_101_dialog_content = "仕立てたみたいにピッタリだわ。とても動きやすそうね。",
  ui_story_5004_50040601_102_dialog_content = "私も同感。普段のベリエの服より、ずっとかわいいわ。",
  ui_story_5004_50040601_103_dialog_content = "せっかく素敵な水着姿なんだし、一緒に泳ぎに行きましょ。",
  ui_story_5004_50040601_104_dialog_content = "ほらね！水着姿のベリエちゃんはますますキュートだって、\nみんなが思ってるんだよ。",
  ui_story_5004_50040601_105_dialog_content = "それに、みんなも水着姿なんだし。",
  ui_story_5004_50040601_106_dialog_content = "じゃあ…私も…",
  ui_story_5004_50040601_107_dialog_content = "このままで…",
  ui_story_5004_50040601_108_dialog_content = "そうそう。ベリエちゃん、気にすることないって～！",
  ui_story_5004_50040601_108X1_dialog_content = "<color=#e8d9bb>カシャ</color>",
  ui_story_5004_50040601_108X2_dialog_content = "<color=#e8d9bb>カシャ、カシャ</color>",
  ui_story_5004_50040601_108X3_dialog_content = "あれ？あの人、昨日のベルボーイさんじゃない？",
  ui_story_5004_50040601_108X4_dialog_content = "カメラを持ってるね～。白夜城で似たのを見たことがあるよ！",
  ui_story_5004_50040601_108X5_dialog_content = "ちょっと怪しいわね…どうしてあんなところで腹ばいになって\n写真を撮ってるのかしら？",
  ui_story_5004_50040601_108X6_dialog_content = "風景を撮って宣伝にでも使うんじゃない？\nあ、せっかくだから貸してもらえないか聞いてくる！",
  ui_story_5004_50040601_108X7_dialog_content = "お、女の子たちの…水着写真…これでノルマは達成した、はず…",
  ui_story_5004_50040601_108X8_dialog_content = "すみませ～ん！",
  ui_story_5004_50040601_108X9_dialog_content = "うわぁっ！！",
  ui_story_5004_50040601_108X10_dialog_content = "あれれ？カメラを貸してくれるの？まだ何も言ってないのに。",
  ui_story_5004_50040601_108X11_dialog_content = "使っていいんだね？じゃ、遠慮せず借りてくね～！",
  ui_story_5004_50040601_108X12_dialog_content = "お、驚いて放り投げただけだ…",
  ui_story_5004_50040601_108X13_dialog_content = "か…返してくれ…",
  ui_story_5004_50040601_108X14_dialog_content = "ラファエル…その人、困ってるみたいよ。カメラは返してあげたら…？",
  ui_story_5004_50040601_108X15_dialog_content = "ベリエちゃんは優しいね～。はい、もう落とさないようにね。",
  ui_story_5004_50040601_108X16_dialog_content = "あ、ありがとう…",
  ui_story_5004_50040601_109_dialog_content = "さ、遊びに行こ、ベリエちゃん。",
  ui_story_5004_50040601_110_dialog_content = "私たちも行くわよ、PlayerName。",
  ui_story_5004_50040601_111_dialog_content = "うん！",
  ui_story_5004_50040701_1_dialog_content = "…みんな、どうしてあんなに元気なんだろう…",
  ui_story_5004_50040701_2_dialog_content = "（バイスは浮き輪をはめて派手に波しぶきを立てながら、海を泳いでいる。\nまるでスクリューでも付いてるみたいだ）",
  ui_story_5004_50040701_3_dialog_content = "（カレンはというと、銛で知らない生き物を山ほど捕まえている）",
  ui_story_5004_50040701_4_dialog_content = "（そして自分の体よりも大きな生き物を、岸へ放り投げている）",
  ui_story_5004_50040701_5_dialog_content = "（ベリエとラファエルは楽しそうに貝殻を拾ったり、砂の城を作ったりしている）",
  ui_story_5004_50040701_6_dialog_content = "（ベリエの作る砂の城、すごく立派だ…）",
  ui_story_5004_50040701_7_dialog_content = "（至るところにトゲトゲがついてて、巨大な時計台まである）",
  ui_story_5004_50040701_X7_dialog_content = "（…なんだか悪者の城みたいだな…）",
  ui_story_5004_50040701_8_dialog_content = "僕は…体力がなさすぎるのかな？",
  ui_story_5004_50040701_9_dialog_content = "巨像の中じゃ、体を使うこともほとんどないし…",
  ui_story_5004_50040701_10_dialog_content = "戦闘でも動かず指揮してるだけだし…",
  ui_story_5004_50040701_11_dialog_content = "ビーチ沿いを走って体を鍛えるべきかな…",
  ui_story_5004_50040701_12_dialog_content = "よう！偉大なる巨像の主、未来の啓光将軍、白夜城の守護者――",
  ui_story_5004_50040701_13_dialog_content = "そして何より、R・Wの未来のボスの兄弟分、\nPlayerNameじゃねーか！",
  ui_story_5004_50040701_14_dialog_content = "ヘール？どうしてここに？",
  ui_story_5004_50040701_15_dialog_content = "フェラールの手伝いがあるんじゃなかったの？",
  ui_story_5004_50040701_16_dialog_content = "あと、君がサメヤマに勝ってR・Wのリーダーになれるとは当分思えないよ。",
  ui_story_5004_50040701_17_dialog_content = "PlayerName、お前には指揮の腕はあっても、人を見る目はないようだな！",
  ui_story_5004_50040701_18_dialog_content = "サメヤマの奴はもはや落ち目だ。\n一方の俺は、今まさに天空に上ってる新星だ――！",
  ui_story_5004_50040701_X18_dialog_content = "敗\n北",
  ui_story_5004_50040701_19_dialog_content = "R・Wの中でも俺を支持してる奴は大勢いるんだぜ。",
  ui_story_5004_50040701_20_dialog_content = "大勢って…誰がいるの？",
  ui_story_5004_50040701_21_dialog_content = "…フェラールだ。",
  ui_story_5004_50040701_22_dialog_content = "…",
  ui_story_5004_50040701_23_dialog_content = "…他には？",
  ui_story_5004_50040701_24_dialog_content = "フェラールとか、フェラールとか、あとはフェラールだ！\nそうだ、この機会にレジーナとも話をつけておくか！",
  ui_story_5004_50040701_25_dialog_content = "レジーナはそういう話に興味なさそうな感じがするけど。",
  ui_story_5004_50040701_26_dialog_content = "そんじゃ、お前に話をつけるか。",
  ui_story_5004_50040701_27_dialog_content = "それで空の末裔の一族の後ろ盾を得たってことにしたいわけ？",
  ui_story_5004_50040701_28_dialog_content = "頼むよPlayerName、俺が知ってる空の末裔の中で、\nお前ほど頭の切れるヤツはいねぇ！",
  ui_story_5004_50040701_29_dialog_content = "見え透いたお世辞だし、そもそも他に\n空の末裔の知り合いなんていないでしょ…？",
  ui_story_5004_50040701_30_dialog_content = "…しっ。",
  ui_story_5004_50040701_31_dialog_content = "…？",
  ui_story_5004_50040701_32_dialog_content = "PlayerName、<color=#FFB400>あいつ</color>が見えるか？",
  ui_story_5004_50040701_33_dialog_content = "あの女の子？",
  ui_story_5004_50040701_34_dialog_content = "そうだ。コソコソして怪しい…あちこちを見て回ってるようだが。",
  ui_story_5004_50040701_35_dialog_content = "そんなことないでしょ…落とし物を探してるだけかもよ。",
  ui_story_5004_50040701_36_dialog_content = "俺たちと同じくらいの大きさの石をひっくり返してるんだぞ。\nそれで何を探してるって言うんだ？",
  ui_story_5004_50040701_37_dialog_content = "なあ、見に行ってみようぜ。",
  ui_story_5004_50040701_38_option_content = "いいよ",
  ui_story_5004_50040701_39_dialog_content = "でも、どうしてそこまで気になるの？",
  ui_story_5004_50040701_40_dialog_content = "泥棒だったら困るだろ？",
  ui_story_5004_50040701_41_dialog_content = "あんなに大きな石をひっくり返して何を盗むっていうの！？\nあそこに物を隠す人なんていないよ。",
  ui_story_5004_50040701_42_dialog_content = "君ってR・Wの人だよね。\nそこまで正義感のある人だった覚えはないけど。",
  ui_story_5004_50040701_43_dialog_content = "そりゃ、状況が違うからな。フェラールに仕事を頼まれてるんだ！\nなんせ今の俺は<color=#FFB400>ルシェル・ド・アンジュビーチの保安官様</color>だぞ！",
  ui_story_5004_50040701_44_dialog_content = "（よりにもよってR・Wの人を保安官にするなんて、何考えてるの…？）",
  ui_story_5004_50040701_45_option_content = "首を突っ込まないほうがいい",
  ui_story_5004_50040701_46_dialog_content = "君ってR・Wの人だよね。\nそこまで正義感のある人だった覚えはないけど。",
  ui_story_5004_50040701_47_dialog_content = "そりゃ、状況が違うからな。フェラールに仕事を頼まれてるんだ！\nなんせ今の俺は<color=#FFB400>ルシェル・ド・アンジュビーチの保安官様</color>だぞ！",
  ui_story_5004_50040701_48_dialog_content = "（よりにもよってR・Wの人を保安官にするなんて、何考えてるの…？）",
  ui_story_5004_50040701_49_dialog_content = "無駄口はいいから、付いてこい。",
  ui_story_5004_50040701_50_dialog_content = "おい、そこの怪しいヤツ。",
  ui_story_5004_50040701_51_dialog_content = "…",
  ui_story_5004_50040701_52_dialog_content = "おい、聞いてんのか！？",
  ui_story_5004_50040701_53_dialog_content = "触んな！",
  ui_story_5004_50040701_54_dialog_content = "PlayerName、見ただろ！\nあっちが先に手を出してきやがったんだ――！",
  ui_story_5004_50040701_55_dialog_content = "待って、ちゃんと避けられたでしょ？\nむやみな暴力はやめた方がいいよ。",
  ui_story_5004_50040701_56_dialog_content = "アンタ誰？それにそっちの命知らずも。",
  ui_story_5004_50040701_57_dialog_content = "いきなり来て大声上げてさ。レディの肩に気安く触んなよ。",
  ui_story_5004_50040701_58_dialog_content = "ナンパなら他を当たりな！アンタらにはキョーミないし。",
  ui_story_5004_50040701_59_dialog_content = "PlayerName、放せ！\nあのアマ、車の後ろに縛り付けてドライブしてやる！",
  ui_story_5004_50040701_60_dialog_content = "やんの？面白いじゃん、ちょうどムシャクシャしてたんだよね――",
  ui_story_5004_50040701_61_dialog_content = "あらあら…<color=#FFB400>スモーキー</color>。\nしばらく見ない間にずいぶん野蛮な連中と付き合うようになってしまったのね。",
  ui_story_5004_50040701_62_dialog_content = "そのありさまじゃ、貴族の身分にふさわしいとは言えないわね？",
  ui_story_5004_50040701_63_dialog_content = "アンタ誰？…あたしと貴族が何か関係あるっての？",
  ui_story_5004_50040701_64_dialog_content = "な、なんですって！？私のことを忘れたとでも！？",
  ui_story_5004_50040701_65_dialog_content = "おい、俺たちの話はまだ――",
  ui_story_5004_50040701_66_dialog_content = "お黙り！",
  ui_story_5004_50040701_67_dialog_content = "この顔をよく見なさいよ！",
  ui_story_5004_50040701_68_dialog_content = "覚えてない。あと、近寄んな。",
  ui_story_5004_50040701_69_dialog_content = "私は<color=#FFB400>ジュヌヴィエーヴ</color>よ！\n<color=#FFB400>ヴロンスキー家</color>の<color=#FFB400>ジュヌヴィエーヴ</color>！",
  ui_story_5004_50040701_70_dialog_content = "あぁ…？何だっけな…",
  ui_story_5004_50040701_71_dialog_content = "ペドロ要塞の…",
  ui_story_5004_50040701_72_dialog_content = "あーはいはい、ペドロ要塞ね！",
  ui_story_5004_50040701_73_dialog_content = "<size=30>PlayerName、こいつら何なんだ…？</size>",
  ui_story_5004_50040701_74_dialog_content = "<size=30>知らないよ…</size>",
  ui_story_5004_50040701_75_dialog_content = "思い出した！ジュヌヴィエーヴじゃん！\nずいぶん背ぇ高くなったね。",
  ui_story_5004_50040701_76_dialog_content = "な、なんなの…さっきから癇に障るような態度ばかり…！！",
  ui_story_5004_50040701_77_dialog_content = "あなたのせいで私と私の一族は大恥をかいて…面目を失ったのよ！",
  ui_story_5004_50040701_78_dialog_content = "何の話？まったく身に覚えがないんだけど？",
  ui_story_5004_50040701_79_dialog_content = "あー、頭痛い。アンタのこと思い出そうとして、頭使いすぎたわ。",
  ui_story_5004_50040701_80_dialog_content = "う～ん、あっ！そーだ、あたし記憶喪失なんだよね。\nこれで納得してもらえる？",
  ui_story_5004_50040701_81_dialog_content = "んじゃ、もう行くわ。\n美人になったジュヌヴィエーヴのお嬢さん――！",
  ui_story_5004_50040701_82_dialog_content = "待ちなさい！行かせないわ！",
  ui_story_5004_50040701_83_dialog_content = "…",
  ui_story_5004_50040701_84_dialog_content = "僕を見られても困るよ…！",
  ui_story_5004_50040701_85_dialog_content = "あ？引っ張んないでよ。レディには手を出さないでいるつもりだけど…",
  ui_story_5004_50040701_86_dialog_content = "モメてるところを人に見られたら、あたしだってコマんだからね。",
  ui_story_5004_50040701_87_dialog_content = "イチャイチャしてると思われたらどうするワケ？",
  ui_story_5004_50040701_88_dialog_content = "スモーキー！！",
  ui_story_5004_50040701_89_dialog_content = "絶対に許さないわ！！",
  ui_story_5004_50040701_90_dialog_content = "PlayerName、ケンカだ、ケンカが始まるぞ！",
  ui_story_5004_50040701_91_dialog_content = "どうしてそんなにワクワクしてるの…？",
  ui_story_5004_50040701_92_dialog_content = "お前には分からないだろうが、R・Wじゃケンカはコミュニケーションのうちだ。\n実力を証明するための大事なスポーツでもある。",
  ui_story_5004_50040701_93_dialog_content = "どっちでもいいよ…あの金髪の女の子が勝つ気がする。",
  ui_story_5004_50040701_94_dialog_content = "なんでだ？",
  ui_story_5004_50040701_95_dialog_content = "空の末裔の勘ってやつかな。",
  ui_story_5004_50040701_96_dialog_content = "俺には分かんねえな。スモーキーって呼ばれてる銀髪の方はどうだ？",
  ui_story_5004_50040701_97_dialog_content = "動きが安定してるし、さっきも隙がなかった。",
  ui_story_5004_50040701_98_dialog_content = "それに余裕もあるし、自信に満ちた目をしてるぜ。\nありゃタダモンじゃねぇ。",
  ui_story_5004_50040701_99_dialog_content = "金髪のほうはすげぇ迫力だが、自分の感情をコントロールできてない。\nつまり、力も制御できないってことだ。",
  ui_story_5004_50040701_100_dialog_content = "光力術を操るにしても、うまく加減ができないだろうな。",
  ui_story_5004_50040701_101_dialog_content = "ヘール、急に専門家みたいな喋り方になってるの、ヘンだよ…。",
  ui_story_5004_50040701_102_dialog_content = "グァア――！",
  ui_story_5004_50040701_103_dialog_content = "邪魔しないで！",
  ui_story_5004_50040701_103X_dialog_content = "こんなところにも暗鬼が！？",
  ui_story_5004_50040701_103X1_dialog_content = "驚くこたぁないだろ。この地域の特産みたいなもんさ。",
  ui_story_5004_50040701_104_dialog_content = "すげえ。あのジュヌヴィエーヴってヤツも、なかなかやるな。",
  ui_story_5004_50040701_105_dialog_content = "おい！後ろにまだ暗鬼がいるぞ！",
  ui_story_5004_50040701_106_dialog_content = "ヘール、君は保安官だったんじゃないの？見物してていいの？",
  ui_story_5004_50040701_107_dialog_content = "あっ、そうだった！うっかりしてたぜ！",
  ui_story_5004_50040701_108_dialog_content = "おい、暗鬼のザコども。砂の中にぶち込まれる用意はいいか――！",
  ui_story_5004_50040701_109_dialog_content = "フルスロットル！！",
  ui_story_5004_50040701_110_dialog_content = "2人で協力すれば片付けられそうだね！",
  ui_story_5004_50040701_111_dialog_content = "当たり前だ、こんなのチョロいぜ。",
  ui_story_5004_50040701_112_dialog_content = "大丈夫？",
  ui_story_5004_50040701_113_dialog_content = "チッ…手を貸せなんて頼んだ覚えはないわよ！",
  ui_story_5004_50040701_114_dialog_content = "あなたたちが邪魔したせいで、\nスモーキーに逃げられちゃったじゃない！",
  ui_story_5004_50040701_115_dialog_content = "ご、ごめん！",
  ui_story_5004_50040701_116_dialog_content = "ああもう、腹立たしいわ！話しかけないでちょうだい！",
  ui_story_5004_50040701_117_dialog_content = "あの女が何をしているのか突き止めてやるわ…\nそして陰謀を徹底的に打ち砕いてやる…！",
  ui_story_5004_50040701_118_dialog_content = "それじゃあ、ごきげんよう！",
  ui_story_5004_50040701_119_dialog_content = "行っちゃった…",
  ui_story_5004_50040701_120_dialog_content = "PlayerName、今ので分かったろ。\n暗鬼なんかより、女同士のいざこざのほうがよっぽど怖ぇんだ。",
  ui_story_5004_50040701_121_dialog_content = "お前も無理していばらの道を進むこたぁないんだぜ。",
  ui_story_5004_50040701_122_dialog_content = "何の話かさっぱり…",
  ui_story_5004_50040701_123_dialog_content = "おいしい――！",
  ui_story_5004_50040701_124_dialog_content = "スープが口についているわよ。拭いてあげる。",
  ui_story_5004_50040701_125_dialog_content = "あっ…ありがとう！",
  ui_story_5004_50040701_126_dialog_content = "啓光の食堂でもこんなにおいしいものは食べたことないわ。\nもう、手が止まらないの！",
  ui_story_5004_50040701_127_dialog_content = "特に食堂のおばさんときたら、料理をよそう時に毎回手が震えてるのよ。\nただでさえみじめなくらいお肉が少ないのに、あれじゃ全部こぼしちゃうわ。",
  ui_story_5004_50040701_128_dialog_content = "私はまだ成長期真っ最中なのに――！",
  ui_story_5004_50040701_129_dialog_content = "それで、白夜城に留学している時には学院の食堂に入り浸っていたのね。",
  ui_story_5004_50040701_132_dialog_content = "フェラール、立ちっぱなしでいることないよ。\n友達なんだから、ここに座って一緒に食べよう。",
  ui_story_5004_50040701_133_dialog_content = "そういうわけにはいかない。みんなはホテルの大事なゲストだ。\nみんなのお世話をすることが、今の俺にとって何よりも大切な仕事だからな。",
  ui_story_5004_50040701_134_dialog_content = "でも…",
  ui_story_5004_50040701_135_dialog_content = "ほっとけよ、PlayerName。",
  ui_story_5004_50040701_136_dialog_content = "あいつはああいうヤツだってみんな知ってるさ。\nそれに、本人も楽しんでるんだ。",
  ui_story_5004_50040701_137_dialog_content = "ヘール、何か飲むか？",
  ui_story_5004_50040701_138_dialog_content = "冷たいものをくれ！",
  ui_story_5004_50040701_139_dialog_content = "オッケー。すぐに用意する。",
  ui_story_5004_50040701_140_dialog_content = "…",
  ui_story_5004_50040701_141_dialog_content = "PlayerName、顔が赤いぜ？",
  ui_story_5004_50040701_142_dialog_content = "そ、そんなことは…",
  ui_story_5004_50040701_143_dialog_content = "空の末裔でも、あいつの影響を受けずにはいられないんだな。",
  ui_story_5004_50040701_144_dialog_content = "影響って…どういうこと？",
  ui_story_5004_50040701_145_dialog_content = "フェラールに直接聞けよ。",
  ui_story_5004_50040701_146_dialog_content = "ところで、昼過ぎに会った2人の女ども、一体何だったんだろうな。",
  ui_story_5004_50040701_147_dialog_content = "さあ…僕も初めて会った人たちだったよ。",
  ui_story_5004_50040701_148_dialog_content = "超怪しいよな。俺を蹴った女、どう見てもあちこち何かを探し回ってた。",
  ui_story_5004_50040701_149_dialog_content = "車のキーの隠し場所を変えておかないとな…",
  ui_story_5004_50040701_150_dialog_content = "誰も君の車なんて盗んだりしないよ！",
  ui_story_5004_50040701_151_dialog_content = "なになに？あちこちで探し物をしてる人？\n私とベリエちゃんもお昼過ぎに見たよ。",
  ui_story_5004_50040701_152_dialog_content = "ね、ベリエちゃん。",
  ui_story_5004_50040701_153_dialog_content = "ええ…グレーっぽい髪色で…サングラスを掛けていたわ。\n人を寄せ付けない雰囲気で…ちょっと怖かった…",
  ui_story_5004_50040701_154_dialog_content = "（どうやら同一人物で間違いなさそうだ）",
  ui_story_5004_50040701_155_dialog_content = "PlayerName、その人、ひどいんだよ。\nウロウロしてて、そそっかしいのなんの！",
  ui_story_5004_50040701_156_dialog_content = "ベリエちゃんが苦労して作った砂の城、踏みつぶしちゃったんだから！",
  ui_story_5004_50040701_157_dialog_content = "3メートルのそれはそれはすごいお城だったんだよ。\nこ～んなに大きかったんだ！こ～んなに！",
  ui_story_5004_50040701_158_dialog_content = "もういいの。あの人、真剣に謝ってくれたでしょう？",
  ui_story_5004_50040701_159_dialog_content = "でも！半日かけたんだよ！？",
  ui_story_5004_50040701_160_dialog_content = "いいの…こうやって心行くまで羽を伸ばせてる…\nそれだけで…十分幸せだから。",
  ui_story_5004_50040701_161_dialog_content = "それに、あのお城は、ずっと私の頭の中にあるわ…\n目を閉じれば浮かんでくるの。",
  ui_story_5004_50040701_162_dialog_content = "ラファエルが気に入ってくれたのなら…明日も作ってあげる…",
  ui_story_5004_50040701_163_dialog_content = "えっ！ホント？それじゃ、次は私も一緒にやるね。",
  ui_story_5004_50040701_164_dialog_content = "ええ…",
  ui_story_5004_50040701_165_dialog_content = "結局、あいつが何者で、何を企んでやがるのかは分からずじまいだな。",
  ui_story_5004_50040701_166_dialog_content = "別にいいじゃない。ヘール、そこまで気にすることないよ。",
  ui_story_5004_50040701_167_dialog_content = "保安官の仕事をきっちり務めるって、フェラールに約束したんだ。",
  ui_story_5004_50040701_168_dialog_content = "（僕と会った時、サボってなかった…？）",
  ui_story_5004_50040701_169_dialog_content = "ああ、ヘールは確かに俺のお願いで来てくれたんだ。",
  ui_story_5004_50040701_170_dialog_content = "ほら、キミのドリンクだ。氷が丸ごと入ってる。召し上がれ。",
  ui_story_5004_50040701_171_dialog_content = "俺は約束を大事にする男なんだ…ぶっ！！！",
  ui_story_5004_50040701_172_dialog_content = "おい！何だこれ！？",
  ui_story_5004_50040701_173_dialog_content = "ああ、すまん。\nいつもみたいなレディーゼルオイルはないから、代わりに普通の材料を使ったんだ！",
  ui_story_5004_50040701_174_dialog_content = "ヘールっていつもオイルで作った飲み物を飲んでるの？\nR・Wの人たちってすごいな…",
  ui_story_5004_50040701_175_dialog_content = "これはキミのだ、PlayerName。",
  ui_story_5004_50040701_176_dialog_content = "特製ウェルカムドリンクだよ。",
  ui_story_5004_50040701_177_dialog_content = "特製…オイルは使ってないんだよね？",
  ui_story_5004_50040701_178_dialog_content = "心配いらない。酒もオイルも入ってないよ。\n子供からお年寄りまで、安心して飲んでもらえるぜ。",
  ui_story_5004_50040701_X178_dialog_content = "それならもらうよ、ありがとう！",
  ui_story_5004_50040701_179_dialog_content = "あと、もし都合が合えば…\nできるだけ早いうちに、PlayerNameと2人きりで話がしたいんだ。",
  ui_story_5004_50040701_180_dialog_content = "時間ならあるよ。",
  ui_story_5004_50040701_181_dialog_content = "（甘酸っぱい不思議な味だ…柑橘系の香りが混じってて、後味にも層がある）",
  ui_story_5004_50040701_182_dialog_content = "（すごく手の込んだドリンクだ…）",
  ui_story_5004_50040901_1_dialog_content = "しまった、起きないと…",
  ui_story_5004_50040901_2_dialog_content = "また部品の山に埋もれて寝ちゃってたか。\n歯車の角が当たってたせいで、背中が痛い…",
  ui_story_5004_50040901_3_dialog_content = "この図面は…昨日の夜に描いたものか。そうだな…",
  ui_story_5004_50040901_4_dialog_content = "使いものにはならなさそうだ。捨てるか。",
  ui_story_5004_50040901_5_dialog_content = "やっぱり<color=#FFB400>空の末裔の知識</color>に頼る必要があるな…",
  ui_story_5004_50040901_6_dialog_content = "啓光と白夜城のロボットを分析するだけじゃ、理想の「あれ」は作れない。",
  ui_story_5004_50040901_7_dialog_content = "ひとまずシャワーを浴びよう…それからPlayerNameに会いに行くか。",
  ui_story_5004_50040901_8_dialog_content = "潮汐祭を無事に開催させないと…\nこの<color=#FFB400>特殊な体質</color>の影響からは逃れられないままだ。",
  ui_story_5004_50040901_9_dialog_content = "（ごく普通の啓光の整備士として生きるはずだったのに…）",
  ui_story_5004_50040901_10_dialog_content = "（隔世遺伝した「特殊な体質」のせいで…）",
  ui_story_5004_50040901_11_dialog_content = "（学校に通っていた頃…）",
  ui_story_5004_50040901_12_dialog_content = "フェラール！<size=45>フェラール！</size>",
  ui_story_5004_50040901_13_dialog_content = "やあ、元気？",
  ui_story_5004_50040901_14_dialog_content = "フェラール、この問題、教えてくれない？",
  ui_story_5004_50040901_15_dialog_content = "もちろんいいよ。分からない所は何でも聞いて。",
  ui_story_5004_50040901_16_dialog_content = "あんた、1日中フェラールに付きまとってどういうつもり？",
  ui_story_5004_50040901_17_dialog_content = "フェラールに特別な感情でもあるわけ？",
  ui_story_5004_50040901_18_dialog_content = "そうだったら何よ！<size=45>フェラールはあなた1人のものじゃないでしょ！</size>",
  ui_story_5004_50040901_19_dialog_content = "ちょっと！女子たち、フェラールを追いかけまわすんじゃないよ。",
  ui_story_5004_50040901_20_dialog_content = "フェラールは君たち女子には興味ないんだ！そうだろ？",
  ui_story_5004_50040901_21_dialog_content = "どういうこと！？フェラール、女と男どっちが好きなの？",
  ui_story_5004_50040901_22_dialog_content = "みんなのことが好きだよ。",
  ui_story_5004_50040901_23_dialog_content = "彼には機械を扱う才能がある。仕事も真面目にこなすし、人当たりもいい…",
  ui_story_5004_50040901_24_dialog_content = "非常に優秀な啓光の者だ。",
  ui_story_5004_50040901_25_dialog_content = "だが彼は特殊な体質のせいで、周囲との協力に支障をきたしている…",
  ui_story_5004_50040901_26_dialog_content = "男女問わずどころか、動物までもが彼に影響される。",
  ui_story_5004_50040901_27_dialog_content = "しかも、<color=#FFB400>「例の一件」</color>で大勢がケガをした。",
  ui_story_5004_50040901_28_dialog_content = "そうだな。彼を新設の<color=#FFB400>シェルター38号</color>へ派遣してはどうだろう。\nあそこは他より光霊が少ない…",
  ui_story_5004_50040901_29_dialog_content = "そうそう問題は起きないだろう。",
  ui_story_5004_50040901_30_dialog_content = "フェラール、おめでとう。専門家として、\n君をシェルター38号へ派遣することが決まった。シェルター建設のサポートだ。",
  ui_story_5004_50040901_31_dialog_content = "千載一遇の機会だぞ。啓光が君を信頼しているという意味でもある。",
  ui_story_5004_50040901_32_dialog_content = "向こうでは君の能力が十分に発揮されるだろう。\n大いに活躍して、汚名を返上してくれたまえ！",
  ui_story_5004_50040901_33_dialog_content = "（あの頃は本当に幸せだった…人生は単純で、純粋で、静かだった）",
  ui_story_5004_50040901_34_dialog_content = "来週、女房が38号シェルターへ来るんです！\n俺たち、もう何年も会ってないんですよ！",
  ui_story_5004_50040901_35_dialog_content = "あいつがずっとここにいるせいで、\n夫婦の団らんもできないし、娘にも会えないんです！",
  ui_story_5004_50040901_36_dialog_content = "うちで飼ってるペットは毎日あいつのところへ行こうとするし！",
  ui_story_5004_50040901_37_dialog_content = "あいつを遠ざけないと、誰もが影響されてしまう！",
  ui_story_5004_50040901_38_dialog_content = "落ち着いてくれ。フェラールはお前たちが思うような恐ろしい存在などではない。",
  ui_story_5004_50040901_39_dialog_content = "見え透いた嘘だ！学校では<color=#FFB400>「あんな事件」</color>があったじゃないですか。\n啓光の人間ならみんな知ってますよ！",
  ui_story_5004_50040901_40_dialog_content = "あいつのせいで大勢がケガをしたっていうのに！\nどうしてあいつを庇うんです！？",
  ui_story_5004_50040901_42_dialog_content = "フェラール、シェルター38号へのこれまでの貢献には感謝している。",
  ui_story_5004_50040901_43_dialog_content = "だが、カナン城へ戻ってもらわないとならん。ここの人たちは…",
  ui_story_5004_50040901_44_dialog_content = "言われなくても、分かっています。",
  ui_story_5004_50040901_45_dialog_content = "でも、戻りたくありません。",
  ui_story_5004_50040901_46_dialog_content = "シェルター38号を離れたくないんです。\nここには…静かで、楽しい思い出がたくさんあります。",
  ui_story_5004_50040901_47_dialog_content = "ここなら人に囲まれることもない。\n落ち着いて自分のやりたい研究に没頭できるんです。",
  ui_story_5004_50040901_48_dialog_content = "最初に言われましたよね？ここで大いに活躍しろと…",
  ui_story_5004_50040901_49_dialog_content = "…",
  ui_story_5004_50040901_50_dialog_content = "すまん。だが、状況が変わったのだ。\n君が望まないのであっても、強制送還するしかない。",
  ui_story_5004_50040901_51_dialog_content = "戻って、何をすればいいんですか？",
  ui_story_5004_50040901_52_dialog_content = "俺を隔離するんですか？それとも科学研究部門に送るつもりですか？",
  ui_story_5004_50040901_53_dialog_content = "すまん…",
  ui_story_5004_50040901_54_dialog_content = "我々も…精一杯、手を尽くしたのだ。",
  ui_story_5004_50040901_55_dialog_content = "でも今…俺の目の前にはチャンスがある！",
  ui_story_5004_50040901_56_dialog_content = "フェラール、ホテル「フルート・プラチナ」へようこそ。\n手紙は読んでいただけましたか？",
  ui_story_5004_50040901_57_dialog_content = "ああ。潮汐祭の開催に協力すれば…\n俺の「特殊な体質」を治してくれるんだな？",
  ui_story_5004_50040901_58_dialog_content = "ご心配はいりませんよ。\n遺跡を発掘していた時に集めた情報によれば、「あの伝説」は本当なのですから！",
  ui_story_5004_50040901_59_dialog_content = "おや…この若者がフェラール君かね？\nフロントマネージャーと潮汐祭の準備については、君に任せよう。",
  ui_story_5004_50040901_59X1_dialog_content = "ああ。さっそく準備を始める。",
  ui_story_5004_50040901_59X2_dialog_content = "順調に行きそうだな。\nところで、さっき言ってた「あの伝説」とは何のことだ？",
  ui_story_5004_50040901_59X3_dialog_content = "…あれは適当に言っただけです。\nご希望の人員をそろえれば、それでいいのですよね？",
  ui_story_5004_50040901_59X4_dialog_content = "はは…それでいいとも。\nリストに挙げた人たちを集めてくれれば、手段は問わない…",
  ui_story_5004_50040901_59X5_dialog_content = "潮汐祭…必ずこのチャンスをつかんでみせる。",
  ui_story_5004_50040901_60_dialog_content = "準備はできた…",
  ui_story_5004_50040901_61_dialog_content = "よし、行くか！！",
  ui_story_5004_50040901_62_dialog_content = "フェラール！",
  ui_story_5004_50040901_63_dialog_content = "<size=45>フェラールさん！</size>",
  ui_story_5004_50040901_64_dialog_content = "みんな、おはよう。",
  ui_story_5004_50040901_65_dialog_content = "フェラールさん、素敵な香りがするわ～！",
  ui_story_5004_50040901_66_dialog_content = "さっきシャワー浴びてました？水の音が聞こえましたけど！",
  ui_story_5004_50040901_67_dialog_content = "ええと、そ、それは…ごめん、ちょっとそこ、どいてくれる？",
  ui_story_5004_50040901_68_dialog_content = "部屋を見せてくれるんですか！？",
  ui_story_5004_50040901_69_dialog_content = "部屋の部品を荒らされちゃ困るな…",
  ui_story_5004_50040901_70_dialog_content = "ラルラル！ヨガのインストラクターが、\nクラスに参加すればあなたと一緒にヨガができるって言ってた。本当なの？",
  ui_story_5004_50040901_71_dialog_content = "えっ？何のこと？騙されてるんじゃないかな…",
  ui_story_5004_50040901_72_dialog_content = "みんな、落ち着いて。悪いね。\n俺はこれから約束があるんだ。道を空けてくれないか？",
  ui_story_5004_50040901_73_dialog_content = "<anim type=Shake><size=45>ええっ――！？！？</size></anim>",
  ui_story_5004_50040901_74_dialog_content = "抜け駆けしたのは誰だ！？",
  ui_story_5004_50040901_75_dialog_content = "フェラールさん、それより私と出かけませんか？",
  ui_story_5004_50040901_76_dialog_content = "（やれやれ、これじゃPlayerNameを待たせることになりそうだ…）",
  ui_story_5004_50041001_1_dialog_content = "そうだ、思い付いたぞ！",
  ui_story_5004_50041001_2_dialog_content = "根気強く説明してくれてありがとう。\nそれに遅刻のことも大目に見てくれて、本当に感謝するよ！",
  ui_story_5004_50041001_3_dialog_content = "お礼なんていらないよ。そんなに待ってないしね。\nそれより、本気でロボットを作る気なの？",
  ui_story_5004_50041001_4_dialog_content = "もちろん。それこそ俺の願いなんだ。",
  ui_story_5004_50041001_5_dialog_content = "<color=#e8d9bb>トントントン</color>",
  ui_story_5004_50041001_6_dialog_content = "PlayerNameさん、お邪魔してもよろしいでしょうか？",
  ui_story_5004_50041001_7_dialog_content = "どうぞ。",
  ui_story_5004_50041001_8_dialog_content = "フェラール、どうしてここに？",
  ui_story_5004_50041001_9_dialog_content = "潮汐祭開催チームのリーダーでしょう？\nサボりはいけませんよ。",
  ui_story_5004_50041001_10_dialog_content = "サボりじゃない。PlayerNameに機械設計のことで質問しに来ただけだ。",
  ui_story_5004_50041001_11_dialog_content = "それじゃ、俺は戻って実際に試してみるよ。じゃあな。",
  ui_story_5004_50041001_12_dialog_content = "PlayerName、いかがでしょう、潮汐祭には参加されますか？\n今回の賞品はなんと…",
  ui_story_5004_50041001_13_dialog_content = "参加するよ。",
  ui_story_5004_50041001_14_dialog_content = "えっ？",
  ui_story_5004_50041001_15_dialog_content = "何か問題でもあるの？もうみんなと話し合って決めたんだ。",
  ui_story_5004_50041001_16_dialog_content = "あっさり了承してくださるとは、意外でした！",
  ui_story_5004_50041001_17_dialog_content = "そもそも、ごく普通のお祭りに参加するんだよね。\nためらう必要なんてあるの？",
  ui_story_5004_50041001_18_dialog_content = "うふふ。何か陰謀でもあるんじゃないかって、思ったりはしないのですか？",
  ui_story_5004_50041001_19_dialog_content = "陰謀！？やっぱり参加しないでおくよ！",
  ui_story_5004_50041001_20_dialog_content = "ふふふ。実にかわいらしい反応ですね。\nいくら私が真理結社のメンバーでも、陰謀なんてうかつに口にしたりしませんよ。",
  ui_story_5004_50041001_21_dialog_content = "今のは冗談です。素晴らしいご決断に敬意を表したまでです。",
  ui_story_5004_50041001_22_dialog_content = "（真理結社は変わった人ばっかりだ…）",
  ui_story_5004_50041001_23_dialog_content = "参加を決めたということでしたら、こちらの書類にサインをお願いしますね。",
  ui_story_5004_50041001_24_dialog_content = "このペンをお使いください。",
  ui_story_5004_50041001_25_dialog_content = "ん…？このペン、すごく手の込んだ作りだね。",
  ui_story_5004_50041001_26_dialog_content = "それに氷みたいに冷たくて、ちょっとべたつくような…",
  ui_story_5004_50041001_27_dialog_content = "とても高価なものですよ。きわめて希少な結晶石を使っているんです。",
  ui_story_5004_50041001_28_dialog_content = "見た目は小さなペンにすぎませんが、\nホテルを半分買い取れるくらいの価値があります。",
  ui_story_5004_50041001_29_dialog_content = "お気に召されたようでしたら、差し上げましょうか。",
  ui_story_5004_50041001_30_dialog_content = "えっ！？そんな貴重な物、受け取れないよ。",
  ui_story_5004_50041001_31_dialog_content = "いいのですよ。遺跡から発掘されたものですから。",
  ui_story_5004_50041001_32_dialog_content = "さすがは真理結社…どこでも遺跡を発掘してるって言われてるだけあるね。",
  ui_story_5004_50041001_33_dialog_content = "お褒めに預かり光栄です。\nそうだ、巨像を操作する装置は…見た目がピアノのようだと耳にしたのですが？",
  ui_story_5004_50041001_34_dialog_content = "音楽家として、とても興味があります。\nひと目でも拝見できればありがたいところです。",
  ui_story_5004_50041001_35_dialog_content = "見学するのは問題ないよ。\n…じゃあ、これがサインだよ。ペンと書類は返すね！",
  ui_story_5004_50041001_36_dialog_content = "そうですか…確認しました。\nこれで今から、あなたは正式な参加者となります。",
  ui_story_5004_50041001_37_dialog_content = "今しばらくは休息をおとりください。\n午後から1戦目の試合があります。",
  ui_story_5004_50041001_38_dialog_content = "ご活躍に期待していますよ。",
  ui_story_5004_50041001_39_dialog_content = "ふぅ…実に…順調ですね。",
  ui_story_5004_50041001_40_dialog_content = "私まで罪悪感を覚えるほどに…",
  ui_story_5004_50041001_X40_dialog_content = "なんて、ありえませんね。",
  ui_story_5004_50041001_X40X1_dialog_content = "これで空の末裔も含め…全員が集まりましたね。",
  ui_story_5004_50041001_X40X2_dialog_content = "彼があんなにも易々と「この」筆を使ってサインするとは…",
  ui_story_5004_50041001_X40X3_dialog_content = "いったいどんな狙いがあるのやら…\nいずれにせよ、所詮は暗鬼、利用した所で大ごとにはならないでしょう。",
  ui_story_5004_50041001_41_dialog_content = "こんなに簡単に<color=#FFB400>「楽章」</color>の前半が手に入るだなんて…",
  ui_story_5004_50041001_42_dialog_content = "PlayerName…実に面白い人ですね。",
  ui_story_5004_50041101_1_dialog_content = "<color=#e8d9bb>その頃</color>",
  ui_story_5004_50041101_2_dialog_content = "いいぞ…お前はすでに鍵を手にしている…",
  ui_story_5004_50041101_3_dialog_content = "彼の力を利用して…神鳴りに近づくのだ。",
  ui_story_5004_50041101_4_dialog_content = "お前を導いてやろう…「果実」をもぎ取るのだ。",
  ui_story_5004_50041101_5_dialog_content = "もう凡人に追従することはない…真の音楽の極致へと進むのだ…",
  ui_story_5004_50041101_6_dialog_content = "はい…それこそ…私が長年望んできたことです…！",
  ui_story_5004_50041101_7_dialog_content = "チッ。お前の独り言は何度聞いても気色が悪い。\n頭の中の声は何と言ってるんだ？",
  ui_story_5004_50041101_8_dialog_content = "約束通り、リスト上のメンバーを集めれば楽章の前半部を渡す。",
  ui_story_5004_50041101_9_dialog_content = "その声とやらが楽章の後半部も早く見つけろと急かしているのか？",
  ui_story_5004_50041101_10_dialog_content = "すでに大勢の暗鬼を発掘に出している。\nだが、手に入れたところで無意味だぞ。",
  ui_story_5004_50041101_11_dialog_content = "空の末裔の力がなければ、呼び覚ますことはできん。",
  ui_story_5004_50041101_12_dialog_content = "…あなたには関係のないことです。",
  ui_story_5004_50041101_13_dialog_content = "はっきり言っておきます。私の望みは完璧な「神鳴りの楽章」を手に入れること。\nあなた方「暗鬼」と肩を並べることではありません。",
  ui_story_5004_50041101_14_dialog_content = "楽章の前半部分を既に受け取り、後半も渡すという約束があるからこそ\n手を組んでいるだけです。",
  ui_story_5004_50041101_15_dialog_content = "これは一時的な「協力関係」にすぎません。\n長期的な「共犯」になるつもりはありません。お分かりですか？",
  ui_story_5004_50041101_15X_dialog_content = "それから、あなたたちが送り出した暗鬼は、\nPlayerNameたちに倒されたようです。",
  ui_story_5004_50041101_16_dialog_content = "使えない子ネズミたちですね。",
  ui_story_5004_50041101_17_dialog_content = "この、小汚い上に憎たらしい光霊め――！！",
  ui_story_5004_50041101_18_dialog_content = "まあ、落ち着いて。",
  ui_story_5004_50041101_19_dialog_content = "あなただって、子ネズミたちのことを気づかれて、\n全滅させられては困りますよね。",
  ui_story_5004_50041101_20_dialog_content = "全くこっけいな計画じゃないですか？\n潮汐祭を利用して観光客を集め、水着の写真集を売って軍資金にするんだとか？",
  ui_story_5004_50041101_21_dialog_content = "ヨガ教室まで開いて、どうしようもない手段で\n旅行客のお金を搾り取ろうともしているそうじゃないですか…",
  ui_story_5004_50041101_22_dialog_content = "ああ、でも、お金の大半は黒幕のボスに献上しないといけないんでしたっけ。",
  ui_story_5004_50041101_23_dialog_content = "しょせんは社長「代理」、単なる道具にすぎませんね。",
  ui_story_5004_50041101_24_dialog_content = "暗鬼が光霊に雇われているだなんて、\nお仲間に知られたらひどく馬鹿にされることでしょう。",
  ui_story_5004_50041101_25_dialog_content = "お、お前に何が分かる！我々は…",
  ui_story_5004_50041101_26_dialog_content = "ポリンゴ様！",
  ui_story_5004_50041101_27_dialog_content = "憎たらしい女だ…いずれ痛い目に遭わせてやる！",
  ui_story_5004_50041101_28_dialog_content = "マスター・タブッテン、客人のお帰りだ。",
  ui_story_5004_50041101_29_dialog_content = "ボナーズ様、お見送りいたしましょう。",
  ui_story_5004_50041101_30_dialog_content = "道すがら、新たに企画したヨガレッスンについてお話しさせてください。",
  ui_story_5004_50041101_31_dialog_content = "「物事への向き合い方が結果を左右し、日々の暮らしぶりが品格を定め、\n心がけが寛容さを育む。美しい人生はヨガから始まります。」",
  ui_story_5004_50041101_32_dialog_content = "「ヨガを通じて、平凡なサナギから美しい蝶へと生まれ変わるお手伝いをいたします。」",
  ui_story_5004_50041101_33_dialog_content = "「ヨガは俗世を超越する魂の芸術なのです。」",
  ui_story_5004_50041101_34_dialog_content = "…",
  ui_story_5004_50041201_1_dialog_content = "着いた。ここが試合会場だよね？",
  ui_story_5004_50041201_2_dialog_content = "…審判台もネットも、ソラヴァンのデータベースで見たのと基本的には同じだ。",
  ui_story_5004_50041201_2X1_dialog_content = "あれ？何か変わったものがある？",
  ui_story_5004_50041201_2X2_dialog_content = "お気になさらず。これは「抑制装置」ですよ。",
  ui_story_5004_50041201_2X3_dialog_content = "試合に夢中になりすぎて、\n周囲の設備を壊してしまわないようにするためのものです。",
  ui_story_5004_50041201_2X4_dialog_content = "（え？普通のビーチバレーの試合じゃないの…？）",
  ui_story_5004_50041201_2X5_dialog_content = "ふぅ…これでよしと。",
  ui_story_5004_50041201_3_dialog_content = "審判も位置についたみたいだ。",
  ui_story_5004_50041201_4_dialog_content = "潮汐祭の第1試合へようこそお越しくださいました。\n力と恐れを知らない心を象徴するビーチバレー、試合の始まりです――",
  ui_story_5004_50041201_5_dialog_content = "私の右手におりますのは、PlayerNameチーム。",
  ui_story_5004_50041201_6_dialog_content = "おや、フェラールもPlayerNameチームですよ。\n早く位置についてください。",
  ui_story_5004_50041201_7_dialog_content = "え？フェラールも来たの？",
  ui_story_5004_50041201_8_dialog_content = "ボナーズが参加を勧めてくれたし、\nヘールとバレーをするのも久々だと思ってな。",
  ui_story_5004_50041201_9_dialog_content = "やれやれ。こいつが来たってことは、場が荒れるぞ…",
  ui_story_5004_50041201_10_dialog_content = "フェラール――！",
  ui_story_5004_50041201_11_dialog_content = "ラルラル！！",
  ui_story_5004_50041201_12_dialog_content = "僕もそう思う…",
  ui_story_5004_50041201_13_dialog_content = "はぁ、やっぱりスポーツは自信ないなあ…",
  ui_story_5004_50041201_14_dialog_content = "心配いらないわよ。私、バレーは大の得意なの！",
  ui_story_5004_50041201_15_dialog_content = "バイスは学生時代から体育の成績が優秀だったわ。",
  ui_story_5004_50041201_16_dialog_content = "<color=#FFB400>「無敵の鉄腕少女」</color>と呼ばれていたくらいよ。",
  ui_story_5004_50041201_17_dialog_content = "PlayerNameは大船に乗ったつもりでいればいいわ。",
  ui_story_5004_50041201_18_dialog_content = "（白夜城の学校で付けられるあだ名って、なんか変わってるところがあるね…）",
  ui_story_5004_50041201_19_dialog_content = "そ、そっか。ならよかった。頼んだよ、バイス！",
  ui_story_5004_50041201_20_dialog_content = "チッ。アンタらと同じチームに入れられるなんて。",
  ui_story_5004_50041201_21_dialog_content = "君は昨日の…潮汐祭の試合に出るんだね？",
  ui_story_5004_50041201_22_dialog_content = "昨日、ベリエちゃんの砂の城を壊した人だ！",
  ui_story_5004_50041201_23_dialog_content = "何？参加しちゃダメなワケ？あたしだってボナーズに招待されてんの。",
  ui_story_5004_50041201_24_dialog_content = "それから、あたしの名前はスモーキー。\n砂の城の話は、きちんと謝ったっしょ。",
  ui_story_5004_50041201_25_dialog_content = "試合にその話を持ち込むのはナシな。チームで内輪揉めなんてやってらんねーし。\nそれより、勝つために全力を尽くすべきっしょ。",
  ui_story_5004_50041201_26_dialog_content = "あのいかにも悪そうな子が昨日言ってた人？仲良くできるか少し不安ね…",
  ui_story_5004_50041201_27_dialog_content = "そうだね…でも<color=#FFB400>もう1人</color>のほうがもっと付き合いにくそうだったよ。",
  ui_story_5004_50041201_28_dialog_content = "左手にはジュヌヴィエーヴとその親衛隊の皆さん――",
  ui_story_5004_50041201_29_dialog_content = "フンッ！",
  ui_story_5004_50041201_30_dialog_content = "あの子だ！",
  ui_story_5004_50041201_31_dialog_content = "<anim type=Shake><size=45>ワ―――！ワ―――！</size></anim>",
  ui_story_5004_50041201_32_dialog_content = "フフフ…思い知ったかしら、スモーキー！",
  ui_story_5004_50041201_33_dialog_content = "真の貴族なら、どこへ行こうと庶民から崇め奉られるものなのよ。",
  ui_story_5004_50041201_34_dialog_content = "私からあふれ出る気品を称え、強大なる力にひれ伏すの。",
  ui_story_5004_50041201_35_dialog_content = "スモーキー！あなたのような人には、永遠に理解できないでしょうね。",
  ui_story_5004_50041201_36_dialog_content = "…あー、はいはい。",
  ui_story_5004_50041201_37_dialog_content = "…ったく、誰もそんなこと理解したくないっつーの。\nアンタ、まだそんなつまんねーことにこだわってんだ？",
  ui_story_5004_50041201_38_dialog_content = "ほら、そこのアンタたちも、気合い入れなよ。もうすぐ始まるよ！",
  ui_story_5004_50041201_39_dialog_content = "あなたの負けは決まっているのに、往生際が悪いわね…\nこれでも食らいなさい！！",
  ui_story_5004_50041201_40_dialog_content = "待って、まだ試合は始まってないよ――！！",
  ui_story_5004_50041201_41_dialog_content = "チッ。",
  ui_story_5004_50041201_42_dialog_content = "うまくかわしたね！",
  ui_story_5004_50041201_43_dialog_content = "！！！",
  ui_story_5004_50041201_44_dialog_content = "（スモーキーが避けたボールがこっちに飛んできた）",
  ui_story_5004_50041201_45_dialog_content = "（バレーの試合なのに、これほど戦う力が欲しいと思ったのは生まれて初めてだ）",
  ui_story_5004_50041201_46_dialog_content = "（暗鬼よりも殺人バレーのほうがはるかに恐ろしい）",
  ui_story_5004_50041201_47_dialog_content = "（走馬灯のようにいろんなことが頭をよぎり、僕はいつの間にか目を閉じていた）",
  ui_story_5004_50041201_48_dialog_content = "（海まで吹き飛ばされた僕を、バイスができるだけ早く引き上げてくれるよう願いながら）",
  ui_story_5004_50041201_49_dialog_content = "海水って…どんな味だろう？",
  ui_story_5004_50041201_50_dialog_content = "PlayerName！！",
  ui_story_5004_50041201_51_dialog_content = "バイス！大丈夫だった？",
  ui_story_5004_50041201_52_dialog_content = "私は平気…もう少しでコートの外に飛ばされるところだったわ。",
  ui_story_5004_50041201_53_dialog_content = "ちょっと！まだ試合開始前でしょ！？ジュヌヴィエーヴ、今のは反則だよ！",
  ui_story_5004_50041201_54_dialog_content = "PlayerNameさん、私がお渡しした参加者マニュアルを\nお読みになっていないようですね。",
  ui_story_5004_50041201_55_dialog_content = "あんな分厚い広告だらけの冊子、読み切れる人なんていないよ！",
  ui_story_5004_50041201_56_dialog_content = "それは私のせいではありません。",
  ui_story_5004_50041201_57_dialog_content = "さあ、いよいよです。\n戦いの最後の一瞬まで、皆さんの勇姿を神に見せつけてください――！",
  ui_story_5004_50041201_58_dialog_content = "（僕が知ってるバレーの知識は通用しないということに、この時ようやく気づいた）",
  ui_story_5004_50041201_59_dialog_content = "（それはビーチを舞台とした、ボールを使った血生臭い戦いだったのだ）",
  ui_story_5004_50041202_1_dialog_content = "はぁ…はぁ…私…まだいけるわ…",
  ui_story_5004_50041202_2_dialog_content = "あら、どうかした？その程度の実力だったのかしら？",
  ui_story_5004_50041202_3_dialog_content = "PlayerName、申し訳ないわ。\nこうなると分かっていれば月繭を持って来たのに…",
  ui_story_5004_50041202_4_dialog_content = "いいんだ、月繭があってもボールに穴が開くだけだよ…\nまだヘールたちがいるから、体力を温存して。",
  ui_story_5004_50041202_5_dialog_content = "おいおい――もっと本気だせっての――！",
  ui_story_5004_50041202_6_dialog_content = "君こそ、よそ見しないで！",
  ui_story_5004_50041202_7_dialog_content = "おい！ボールを見ろ、来るぞ！",
  ui_story_5004_50041202_8_dialog_content = "サンキュ！ヘール！",
  ui_story_5004_50041202_9_dialog_content = "陣形を組み直してジュヌヴィエーヴ様をお支えするのだ！",
  ui_story_5004_50041202_10_dialog_content = "<size=45>おう――！</size>",
  ui_story_5004_50041202_11_dialog_content = "うーん…ジュヌヴィエーヴは僕のことなんて眼中にないみたいだ。\n脅威だと思われてないみたいだね…",
  ui_story_5004_50041202_12_dialog_content = "このままじゃマズい…<color=#FFB400>あれ</color>を出すしかない！",
  ui_story_5004_50041202_13_dialog_content = "待てよ！急に何付けてんだ！？",
  ui_story_5004_50041202_14_dialog_content = "それって、<color=#FFB400>ロボットアーム</color>か！？",
  ui_story_5004_50041202_15_dialog_content = "あはは、何を言ってるんだ。これは<color=#FFB400>俺の腕</color>さ。",
  ui_story_5004_50041202_16_dialog_content = "災難RX100型って言うんだ。\nタイニーとの合作で、俺のパワーを3倍にアップできるんだぜ！",
  ui_story_5004_50041202_17_dialog_content = "「災難」って、ジョナのロボットアームのことじゃなかったか！？",
  ui_story_5004_50041202_18_dialog_content = "それに拳のところに赤いでっぱりが増えてるだけだろ、何が3倍だよ！",
  ui_story_5004_50041202_19_dialog_content = "俺の右手がめらめら燃える！勝利を掴めと…",
  ui_story_5004_50041202_20_dialog_content = "妙なキメ台詞はやめろ！とにかく、ロボットアームはダメだ。",
  ui_story_5004_50041202_21_dialog_content = "こいつがあれば正確さとパワーでは誰にも負けないぜ？",
  ui_story_5004_50041202_22_dialog_content = "当たり前だろ、ロボットアームなんだから。",
  ui_story_5004_50041202_23_dialog_content = "すごいんだぞ、ボールなんてなくても何メートルも先まで人をぶっ飛ばせる。",
  ui_story_5004_50041202_24_dialog_content = "むしろパワーがありすぎるんじゃないかって心配だぜ…",
  ui_story_5004_50041202_25_dialog_content = "ロボットアームは今すぐ取り外せ！反則取られるだろうが！",
  ui_story_5004_50041202_26_dialog_content = "やっぱりダメか…ヘールは分からず屋だな。",
  ui_story_5004_50041202_27_dialog_content = "危ない！",
  ui_story_5004_50041202_28_dialog_content = "隙あり――！！",
  ui_story_5004_50041202_29_dialog_content = "<color=#e8d9bb>バンッ！バンッ！</color>",
  ui_story_5004_50041202_30_dialog_content = "うっ！…ぐはぁっ！！…",
  ui_story_5004_50041202_31_dialog_content = "ああ…ここで終わりか…なんて美しい空なんだ…",
  ui_story_5004_50041202_32_dialog_content = "ヘールが吹っ飛ばされて砂の中に埋もれちゃった…\nこれのどこがバレーなの！？",
  ui_story_5004_50041202_33_dialog_content = "1回戦終了！休憩時間に入ります――",
  ui_story_5004_50041202_34_dialog_content = "休憩の間にスポンサーのPRをご覧ください――",
  ui_story_5004_50041202_X33_dialog_content = "3",
  ui_story_5004_50041202_X34_dialog_content = "2",
  ui_story_5004_50041202_X35_dialog_content = "1",
  ui_story_5004_50041202_35_dialog_content = "今回ご紹介するのはこちら、\n浮遊商会で今シーズン最も人気のギフトパックシリーズです。",
  ui_story_5004_50041202_36_dialog_content = "今すぐアイコンをタップいただければ、\nわたくしからご提供する特別割引に加え、召集星標10個を差し上げます。",
  ui_story_5004_50041202_37_dialog_content = "さらにビーチにぴったりの戦車型放水浮き輪もプレゼント！",
  ui_story_5004_50041202_38_dialog_content = "ギフトパックは5000個限定、おっと、たったいま残り1001個になりました！",
  ui_story_5004_50041202_39_dialog_content = "売り切れ間近、今すぐご連絡ください――！",
  ui_story_5004_50041202_40_dialog_content = "なんと、わずかな時間でギフトパックが完売いたしました！！",
  ui_story_5004_50041202_41_dialog_content = "それでは、今後ともボナーズの厳選ショッピングチャンネルにご注目くださいね！\nまた次回お会いしましょう！",
  ui_story_5004_50041202_42_dialog_content = "コマーシャルなんて流してる場合じゃないよ！！！",
  ui_story_5004_50041202_43_dialog_content = "まだ動けるのは僕と、さっきからサボってるスモーキーだけ！？",
  ui_story_5004_50041202_44_dialog_content = "ねぇ！知らんぷりしてないで、君も打開策を考えてよ！",
  ui_story_5004_50041202_45_dialog_content = "あー、ダりぃ。アンタたちが何とかしてくれると思ってたのにさ。",
  ui_story_5004_50041202_46_dialog_content = "誰1人使えるヤツがいないじゃん――",
  ui_story_5004_50041202_47_dialog_content = "さっきまで君をボールから守ってくれてたでしょ！？",
  ui_story_5004_50041202_48_dialog_content = "みんなが捨て身で助けてくれてなければ、君もとっくに退場してるよ！",
  ui_story_5004_50041202_49_dialog_content = "このままじゃ試合に勝てない。みんなの犠牲が無駄になっちゃうよ！！",
  ui_story_5004_50041202_50_dialog_content = "あー、はいはい。人聞きのいいこと言って、自分だって傍観してんじゃん？",
  ui_story_5004_50041202_51_dialog_content = "けど、アンタらに借りをつくんのも面白くねーしな。",
  ui_story_5004_50041202_52_dialog_content = "アンタはそこであたしの解説でもしてなよ。\nあたしの勝ち方、その目に焼き付けな！",
  ui_story_5004_50041202_53_dialog_content = "えっ？解説って…？まあいいや。\n君が真面目にやってくれるなら、何だって言うことを聞くよ！",
  ui_story_5004_50041202_54_dialog_content = "よ～し！",
  ui_story_5004_50041202_55_dialog_content = "おう――",
  ui_story_5004_50041202_56_dialog_content = "ジュヌヴィエーヴ――",
  ui_story_5004_50041202_57_dialog_content = "何よ？もう怖くなったの？命乞いでもする気？",
  ui_story_5004_50041202_58_dialog_content = "アンタって、他人に先を行かれることがそんなに気に障るワケ？",
  ui_story_5004_50041202_59_dialog_content = "何か文句でも？…私にとっては大事なことよ。\n我が一族の家訓やプライドは何者にも傷つけさせないわ。特にあなたには！",
  ui_story_5004_50041202_60_dialog_content = "私の栄誉があなたに奪い去られてからこの数年間というもの、\nあなたを追いかけて探し回り続けていたの。",
  ui_story_5004_50041202_61_dialog_content = "あなたを徹底的に打ち負かし、\n挫折の苦しみと後悔に悶える姿をこの目で見るためにね！",
  ui_story_5004_50041202_62_dialog_content = "…そりゃザンネンだったね。",
  ui_story_5004_50041202_63_dialog_content = "何ですって！？",
  ui_story_5004_50041202_64_dialog_content = "だってあたし…負けるってーのが何よりも嫌いだから！！",
  ui_story_5004_50041202_65_dialog_content = "この一球で確かめてやろうじゃん！",
  ui_story_5004_50041202_66_dialog_content = "アンタとアンタの決心があたしに勝てるかどうかをね！！",
  ui_story_5004_50041202_67_dialog_content = "<anim type=Shake><size=45>「爆炎☆スーパースマッシュ」！！</size></anim>",
  ui_story_5004_50041202_68_dialog_content = "！！！",
  ui_story_5004_50041202_69_dialog_content = "これは！まるで地獄の業火をまとったかのような剛速球が\nジュヌヴィエーヴめがけて猛然と突き進んで行く！",
  ui_story_5004_50041202_70_dialog_content = "（あっ、気付いたら本当に解説しちゃってる…恥ずかしい！）",
  ui_story_5004_50041202_71_dialog_content = "ジュヌヴィエーヴ様！！",
  ui_story_5004_50041202_72_dialog_content = "ここで親衛隊のお出ましだ！\nジュヌヴィエーヴを取り囲んで守るつもりみたいだけど、果たして効果は！？",
  ui_story_5004_50041202_73_dialog_content = "ああっと！火の玉が人だかりのどまん中で大爆発！\n燃える隕石のごとく地面に直撃した！！",
  ui_story_5004_50041202_74_dialog_content = "哀れ、ジュヌヴィエーヴと親衛隊たちは今の1球で退場！\nコートの真ん中には爆発によって大きな穴だけが残された！",
  ui_story_5004_50041202_75_dialog_content = "勝者は――PlayerNameチーム！",
  ui_story_5004_50041202_76_dialog_content = "鋭い1球を繰り出したスモーキー、人差し指を空高く掲げ、\n勝利のポーズを見せつける！実に見事なスマッシュだった！",
  ui_story_5004_50041202_77_dialog_content = "ふん。なかなか手慣れた解説じゃん。\nあたしのスゴさを半分くらいは伝えられたんじゃない？",
  ui_story_5004_50041202_78_dialog_content = "褒めてくれてありがとう…じゃなくって！\n解説って出場者がするものじゃないでしょ！",
  ui_story_5004_50041202_79_dialog_content = "まあそれにしても…本当に強いね…一瞬で全滅しちゃった…",
  ui_story_5004_50041202_80_dialog_content = "（こんな人を相手にしなきゃならないのか…\n急にジュヌヴィエーヴのことがかわいそうになってきた…）",
  ui_story_5004_50041301_1_dialog_content = "ふぅ――もうくたくただよ！",
  ui_story_5004_50041301_2_dialog_content = "何も役に立てなかったけど、\n走り回ってボールを避けてるだけでも疲れたよ…",
  ui_story_5004_50041301_3_dialog_content = "1日目からこんなに激しい試合になるなんて…",
  ui_story_5004_50041301_4_dialog_content = "ジュヌヴィエーヴも強かったけど、スモーキーはケタ違いだ…",
  ui_story_5004_50041301_5_dialog_content = "いったい2人の間に何があったんだろう…？",
  ui_story_5004_50041301_6_dialog_content = "あの後、ベリエとラファエルはまた釣りに行ったみたいだ…\nしっかり楽しんでるみたいだね。",
  ui_story_5004_50041301_7_dialog_content = "昨夜のベリエは疲れてそうだったけど、ラファエルがいれば問題ないよね。",
  ui_story_5004_50041301_8_dialog_content = "そうだ！僕をかばってくれたバイスにお礼を言わないと…",
  ui_story_5004_50041301_9_dialog_content = "バイスがいなければ、今ごろ僕は救急治療を受けていたはずだし…",
  ui_story_5004_50041301_10_dialog_content = "<color=#e8d9bb>トントントン</color>",
  ui_story_5004_50041301_11_dialog_content = "PlayerName、いる？",
  ui_story_5004_50041301_12_dialog_content = "ちょっと待ってて。",
  ui_story_5004_50041301_13_dialog_content = "カレン？どうかしたの？",
  ui_story_5004_50041301_14_dialog_content = "ええと…PlayerNameがまだ起きてるかどうか、確かめに来ただけよ。",
  ui_story_5004_50041301_15_dialog_content = "せっかく海に来たのだから…\n夜に部屋にこもっているのも、勿体ない気がしたの。",
  ui_story_5004_50041301_16_dialog_content = "海辺の散歩でもどうかしら？",
  ui_story_5004_50041301_17_dialog_content = "もちろんいいよ！",
  ui_story_5004_50041301_19_dialog_content = "それなら、行きましょうか。",
  ui_story_5004_50041301_20_dialog_content = "うーん…",
  ui_story_5004_50041301_21_dialog_content = "なんだか気まずい感じがする…",
  ui_story_5004_50041301_22_dialog_content = "PlayerName。",
  ui_story_5004_50041301_23_dialog_content = "え？あ、うん！",
  ui_story_5004_50041301_24_dialog_content = "グリードとスーモアの件…あなたにきちんとお礼をしたいと、\nずっと思っていたの。",
  ui_story_5004_50041301_25_dialog_content = "とんでもない、大したことはしてないよ。",
  ui_story_5004_50041301_26_dialog_content = "僕の方こそ、カレンやバイスにたくさん助けられているんだ。",
  ui_story_5004_50041301_27_dialog_content = "う～ん、あの出来事をこんなきれいなビーチで思い出しても…",
  ui_story_5004_50041301_28_dialog_content = "夢を見ているかのようで、実感がわかない。そうでしょう？",
  ui_story_5004_50041301_29_dialog_content = "今この瞬間さえ、夢の中にいるのかもしれないと思っているわ…",
  ui_story_5004_50041301_30_dialog_content = "初めてあなたに出会った時には、\nたった1人で十何年も生きてきただなんて、信じられなかったわ…",
  ui_story_5004_50041301_31_dialog_content = "空の末裔はあの時まで見たこともなかったし…\n光の軌跡が見えるというのも、奇想天外な話に聞こえていたわ。",
  ui_story_5004_50041301_32_dialog_content = "でも、あなたはどんな危機の中でも落ち着いて素晴らしい活躍を見せた。\n確かに普通の人にはない指揮の才能がある。",
  ui_story_5004_50041301_33_dialog_content = "暗鬼に自力で対抗する能力はなくとも、\n奴らを目の前にして、たじろいだりもしない。",
  ui_story_5004_50041301_34_dialog_content = "…",
  ui_story_5004_50041301_35_dialog_content = "みんなのために自分を危険にさらすほどの度胸もある。",
  ui_story_5004_50041301_36_dialog_content = "他人のための自己犠牲の精神は、並大抵の人間には持ちえない。\n命まで差し出す勇気となれば、言わずもがな。",
  ui_story_5004_50041301_37_dialog_content = "災難が起きる前から、利己的でいい加減に生きてきた貴族たちに比べれば、\nあなたが見せた勇気はよほど尊敬に値するわ。",
  ui_story_5004_50041301_38_dialog_content = "…",
  ui_story_5004_50041301_39_dialog_content = "PlayerName？聞いているの？",
  ui_story_5004_50041301_40_dialog_content = "私、語りすぎてしまったかしら…",
  ui_story_5004_50041301_41_dialog_content = "聞いてるよ。カレンが言ったことについて考えてたんだ…\nこんな風に、潮風に吹かれながらおしゃべりできて、最高の気分だよ。",
  ui_story_5004_50041301_42_dialog_content = "それに、ここはすべてが…",
  ui_story_5004_50041301_43_dialog_content = "海も…星空も…",
  ui_story_5004_50041301_44_dialog_content = "いや、何もかもが…",
  ui_story_5004_50041301_45_dialog_content = "…",
  ui_story_5004_50041301_46_dialog_content = "きれいだね。",
  ui_story_5004_50041301_47_dialog_content = "…",
  ui_story_5004_50041301_48_dialog_content = "…",
  ui_story_5004_50041301_49_dialog_content = "（何かマズいこと言っちゃったかな…）",
  ui_story_5004_50041301_50_dialog_content = "…確かにそうね！白夜城では絶対に見られない景色だもの。",
  ui_story_5004_50041301_51_dialog_content = "見慣れた星空も、穏やかな海に引き立てられて\n普段とは違った壮大な美しさを感じさせるわ。",
  ui_story_5004_50041301_52_dialog_content = "（気のせいだったかな…？）",
  ui_story_5004_50041301_53_dialog_content = "海がこんなにきれいなら、魚もとびっきりおいしそうだよね！",
  ui_story_5004_50041301_54_dialog_content = "捕まえて焼いてみようか？",
  ui_story_5004_50041301_55_dialog_content = "いいわね。けれど私、料理は学んだことがないの。",
  ui_story_5004_50041301_56_dialog_content = "魚を獲ってホテルに持ち帰れば、\nあの風変わりなシェフに頼んで調理してもらえるわね。",
  ui_story_5004_50041301_57_dialog_content = "もしくは、白夜城に持って帰ってもよさそうね。\n味も雰囲気も文句のつけようがない、小さいけれどいい店があるのよ。",
  ui_story_5004_50041301_58_dialog_content = "いいね！じゃあそうしよう。",
  ui_story_5004_50041301_59_dialog_content = "でも、捕まえるのはまた今度にしておこう。\n時間も遅いし、夜の海に入るのは危なそうだし…",
  ui_story_5004_50041301_60_dialog_content = "それに、今日の試合でカレンも疲れてるでしょ？",
  ui_story_5004_50041301_61_dialog_content = "そうね。また今度にしておきましょう。",
  ui_story_5004_50041301_62_dialog_content = "あれ…？",
  ui_story_5004_50041301_63_dialog_content = "どうかした？",
  ui_story_5004_50041301_64_dialog_content = "さっき、遠くにある何かの像が光ったような？",
  ui_story_5004_50041301_65_dialog_content = "私には何も…疲れのせいではないかしら？",
  ui_story_5004_50041301_66_dialog_content = "あるいは、スモーキーの「爆炎☆スーパースマッシュ」の印象が\nまだ頭に残っているのかもしれないわ。",
  ui_story_5004_50041301_67_dialog_content = "その名前、まだ覚えてたんだ。",
  ui_story_5004_50041301_68_dialog_content = "そういうわけじゃないと思うけど…\nまあいいや、たぶん僕の見間違えだろう…",
  ui_story_5004_50041301_69_dialog_content = "帰ろう。",
  ui_story_5004_50041301_70_dialog_content = "空の末裔の子…晶石の力…「仕掛け」も動いている…",
  ui_story_5004_50041301_71_dialog_content = "光力を自ら差し出す愚かな光霊たち…",
  ui_story_5004_50041301_72_dialog_content = "そして…",
  ui_story_5004_50041301_73_dialog_content = "ベリエ。",
  ui_story_5004_50041301_74_dialog_content = "駒は揃った…そろそろ私の手番のようね。",
  ui_story_5004_50041501_1_dialog_content = "<color=#e8d9bb>数日前</color>",
  ui_story_5004_50041501_2_dialog_content = "ざっけんな…！",
  ui_story_5004_50041501_3_dialog_content = "<color=#e8d9bb>スモーキーは怒り心頭の様子で、手紙をビリビリに破り捨てた。</color>",
  ui_story_5004_50041501_4_dialog_content = "あいつに遊ばれたか…？",
  ui_story_5004_50041501_5_dialog_content = "や、やめてくれ。カネならいくらでもやる！",
  ui_story_5004_50041501_6_dialog_content = "はぁ？それがさっきまで女の子相手にイキッて\nカネを巻き上げようとしてたヤツのセリフなワケ？",
  ui_story_5004_50041501_7_dialog_content = "どした？さっきのキショい顔であたしにもタカってみなよ。",
  ui_story_5004_50041501_8_dialog_content = "はぁ、2日間チンピラどもを放っておいただけでこのザマだよ。\nここが誰のシマか知らないとか？",
  ui_story_5004_50041501_9_dialog_content = "ここには「レディにちょっかいをかけない」ってルールがあんの、\n<size=45>あたしに楯突こうってか？</size>",
  ui_story_5004_50041501_10_dialog_content = "お、俺はよそから来たんだ。どうか大目に見てくれ。\nもう二度と問題は起こさないから！",
  ui_story_5004_50041501_11_dialog_content = "はーん？よそ者？面白い言い訳じゃんか――",
  ui_story_5004_50041501_12_dialog_content = "どこから来た？目的は？ボスは誰？30秒以内にきっちり吐きな。",
  ui_story_5004_50041501_13_dialog_content = "納得のいく答えなら、この場は見逃してやる。",
  ui_story_5004_50041501_14_dialog_content = "納得できなければ…",
  ui_story_5004_50041501_15_dialog_content = "30秒ごとに1本ずつ指を折る。分かった？",
  ui_story_5004_50041501_16_dialog_content = "じゃ、1本目。30、29…",
  ui_story_5004_50041501_17_dialog_content = "か、勘弁してくれ！頼まれごとがあったんだ。届け物をしに来ただけさ！",
  ui_story_5004_50041501_18_dialog_content = "悪事を働こうなんて考えはなかったんだ！\nあの女が夜にあんな露出の激しい服を着てるのが悪い！俺は悪くない！",
  ui_story_5004_50041501_19_dialog_content = "頼まれて荷物を届けてるだけなんだよ、ボスなんていない！",
  ui_story_5004_50041501_20_dialog_content = "10、9、8…",
  ui_story_5004_50041501_21_dialog_content = "もう全部話したぜ、他に何を話せっていうんだ！？",
  ui_story_5004_50041501_22_dialog_content = "バキッ、ボキッ…",
  ui_story_5004_50041501_23_dialog_content = "<size=45><anim type=Shake>あああ！！！俺の指が！！指があぁぁ！！</anim></size>",
  ui_story_5004_50041501_24_dialog_content = "何てことしやがる！！しかもなんで2本もやりやがった！？",
  ui_story_5004_50041501_25_dialog_content = "こんなのイカれちまってる！！おかしいだろ！！",
  ui_story_5004_50041501_26_dialog_content = "1本は時間切れ。もう1本はアンタの態度が気に入らねーから。",
  ui_story_5004_50041501_27_dialog_content = "クソガキが…俺は…届け物をしにきただけなのに…",
  ui_story_5004_50041501_28_dialog_content = "出しなよ。",
  ui_story_5004_50041501_29_dialog_content = "ダメだ！！",
  ui_story_5004_50041501_30_dialog_content = "あっそ。じゃ、3本目行くよ。5、4…",
  ui_story_5004_50041501_31_dialog_content = "本当にできないんだ！！殺されちまう！！！",
  ui_story_5004_50041501_32_dialog_content = "0。",
  ui_story_5004_50041501_33_dialog_content = "<size=45><anim type=Shake>あああ！！！</anim></size>…うぐっ、ひぃ…",
  ui_story_5004_50041501_34_dialog_content = "あたしにゃ殺されないとでも思ってるワケ？",
  ui_story_5004_50041501_35_dialog_content = "今死ぬか後で死ぬか、よく考えなよ。",
  ui_story_5004_50041501_36_dialog_content = "分かった！分かったから！！放してくれ！！",
  ui_story_5004_50041501_37_dialog_content = "これだ、見ろ！ちくしょう、こんな…",
  ui_story_5004_50041501_38_dialog_content = "はぁ？ただの手紙？何が書いてあんの？",
  ui_story_5004_50041501_39_dialog_content = "は、早く返してくれ…重要人物に渡せって言われてるんだ。\n封を開けたら、俺もお前もただじゃすまされないぞ！！",
  ui_story_5004_50041501_40_dialog_content = "もうおせーよ。",
  ui_story_5004_50041501_41_dialog_content = "そのエラい人ってのがどんなイイもんもらうのか、\n確認するっきゃないっしょ。",
  ui_story_5004_50041501_42_dialog_content = "なにこれ…「ルシェル・ド・アンジュビーチ」…？",
  ui_story_5004_50041501_43_dialog_content = "宝の地図か？",
  ui_story_5004_50041501_44_dialog_content = "やりやがった！！もうおしまいだ！！",
  ui_story_5004_50041501_45_dialog_content = "<size=45>何だよコレ――？</size>",
  ui_story_5004_50041501_46_dialog_content = "お、俺だって知らねえ。知ってるのは連中がヤバイ奴らだってことだけだ！",
  ui_story_5004_50041501_47_dialog_content = "何か儀式みたいなのを準備してるらしいんだ。\n世界を滅ぼす災禍を呼び覚ます、とか…！",
  ui_story_5004_50041501_48_dialog_content = "さっさと返してくれ。面倒に巻き込まれたくないんだ！！",
  ui_story_5004_50041501_49_dialog_content = "あ？さっきのでまだ懲りてねーの？",
  ui_story_5004_50041501_50_dialog_content = "でまかせ並べやがって。",
  ui_story_5004_50041501_51_dialog_content = "そんな話で騙されるとかありえないっしょ。",
  ui_story_5004_50041501_52_dialog_content = "でも、面白そうじゃん。確認しに行ってやるか！",
  ui_story_5004_50041501_53_dialog_content = "<color=#e8d9bb>手紙に書かれている通り――</color>",
  ui_story_5004_50041501_54_dialog_content = "<color=#e8d9bb>私が追い求めているもの。それは3つの嘆きの壁</color>",
  ui_story_5004_50041501_55_dialog_content = "<color=#e8d9bb>私が探しているもの。それは灰燼からの復活</color>",
  ui_story_5004_50041501_56_dialog_content = "<color=#e8d9bb>朝日の中で降り注ぐ血の雨</color>",
  ui_story_5004_50041501_57_dialog_content = "<color=#e8d9bb>夕日に染まる慟哭</color>",
  ui_story_5004_50041501_58_dialog_content = "<color=#e8d9bb>審判と終焉の果てが訪れる</color>",
  ui_story_5004_50041501_59_dialog_content = "<color=#e8d9bb>その時、王が目を覚ます</color>",
  ui_story_5004_50041501_60_dialog_content = "ワケわかんねーな…なぞなぞかよ…？",
  ui_story_5004_50041501_61_dialog_content = "無駄足だったか…",
  ui_story_5004_50041501_62_dialog_content = "<color=#e8d9bb>トントントン</color>",
  ui_story_5004_50041501_63_dialog_content = "何？",
  ui_story_5004_50041501_64_dialog_content = "失礼します。あなた、影ノ街のスモーキー・マンティコアさんですね？",
  ui_story_5004_50041501_65_dialog_content = "…あたしのこと知ってんの？",
  ui_story_5004_50041501_66_dialog_content = "もちろんです。あなたがここへ来た理由と、\nあなたのものではない手紙を受け取っていることも知っていますよ。",
  ui_story_5004_50041501_67_dialog_content = "サッサと何企んでるのか話しなよ。",
  ui_story_5004_50041501_68_dialog_content = "ふふふ…。",
  ui_story_5004_50041501_69_dialog_content = "…？",
  ui_story_5004_50041501_70_dialog_content = "失礼しました…あなたの発言があまりにおかしいものですから。",
  ui_story_5004_50041501_71_dialog_content = "企みなんてものはありません。私は主催者として\nこの度の「潮汐祭」へお誘いしにきただけです。",
  ui_story_5004_50041501_72_dialog_content = "それだけ？",
  ui_story_5004_50041501_73_dialog_content = "それだけですよ。",
  ui_story_5004_50041501_74_dialog_content = "アンタ、真理結社だよね。アンタらは信用できない。",
  ui_story_5004_50041501_75_dialog_content = "真理結社の者が趣味で式典やイベントの主催者をやっても、\nいいではありませんか。",
  ui_story_5004_50041501_76_dialog_content = "それに、真理を求めるにも先立つものがないと始まりません。\nこの仕事はけっこう稼げるのです。",
  ui_story_5004_50041501_77_dialog_content = "ということで、参加されますか？…あなたが追い求めているものも、\nもしかすると勝者に贈られる賞品の中に含まれているかもしれませんよ。",
  ui_story_5004_50041501_78_dialog_content = "たとえ負けても…",
  ui_story_5004_50041501_79_dialog_content = "それ以上は言わなくていい。あたしは負けねーから。\n負けたらどうなるかなんて興味ない。",
  ui_story_5004_50041501_80_dialog_content = "あのパシり野郎はアンタらの仲間？",
  ui_story_5004_50041501_81_dialog_content = "それは私の知るところではありませんね。",
  ui_story_5004_50041501_82_dialog_content = "フン。ここまで来ちゃってんだし、逃げる必要もないか。",
  ui_story_5004_50041501_83_dialog_content = "あたしの目の前でどんな悪だくみしようってんのか、\n見せてもらおうじゃん？",
  ui_story_5004_50041601_1_dialog_content = "それってつまり…ベリエの不調は、\n体内の光力が不安定になってるせいだってこと？",
  ui_story_5004_50041601_2_dialog_content = "そうだよ。ここ数日、助手と連絡を取ってたんだけど、\n似たような症状を調べてくれたの。",
  ui_story_5004_50041601_3_dialog_content = "それから、「ゴーティエ」家に関する公文書もあるらしいんだけど…",
  ui_story_5004_50041601_4_dialog_content = "でも機密庁の管理が厳しくて、\n閲覧できるのは城主様と限られた人たちだけなの。",
  ui_story_5004_50041601_5_dialog_content = "「ゴーティエ」…って、ベリエの名字？",
  ui_story_5004_50041601_6_dialog_content = "うん！夜におしゃべりしてる時、一族について話してくれたんだ。\nそれから他にも、何かの一族の話をしたんだけど…",
  ui_story_5004_50041601_7_dialog_content = "うーんと…ピュロスだったかなぁ…すぐには思い出せないや。",
  ui_story_5004_50041601_8_dialog_content = "そうなんだ…無理して思い出さなくてもいいよ。\nそれにしても、かなり仲良くなったんだね。",
  ui_story_5004_50041601_9_dialog_content = "当たり前でしょ。女の子同士だもん、お話は尽きないよ～。\nそれにベリエちゃん、あなたが思うよりずっと話し上手だよ？",
  ui_story_5004_50041601_10_dialog_content = "そうなんだ…とにかく、ベリエのことはよろしく頼んだよ。",
  ui_story_5004_50041601_11_dialog_content = "任せて～！カレンちゃんにも相談してみて、進捗があれば報告するね！",
  ui_story_5004_50041601_12_dialog_content = "それじゃ、ベリエちゃんの所へ戻るよ！後で試合会場で会おうね！",
  ui_story_5004_50041601_13_dialog_content = "うん、気をつけてね。",
  ui_story_5004_50041601_14_dialog_content = "う～～！",
  ui_story_5004_50041601_15_dialog_content = "何？大丈夫？",
  ui_story_5004_50041601_16_dialog_content = "へ、平気だよ！ごめんごめん！",
  ui_story_5004_50041601_17_dialog_content = "あれ？スモーキー、どうしてここに？",
  ui_story_5004_50041601_18_dialog_content = "アンタ、PlayerNameだっけ？改めて自己紹介しとくか。",
  ui_story_5004_50041601_19_dialog_content = "あたし、スモーキー。影ノ街から来たんだ。",
  ui_story_5004_50041601_20_dialog_content = "…",
  ui_story_5004_50041601_21_dialog_content = "…",
  ui_story_5004_50041601_22_dialog_content = "それだけ？",
  ui_story_5004_50041601_23_dialog_content = "他になんかいる？",
  ui_story_5004_50041601_24_dialog_content = "えっと…それで、何の用？",
  ui_story_5004_50041601_25_dialog_content = "いちお、同じチームの仲間になったわけだし、\nちゃんと挨拶しとかなきゃなんねーかなって思ったワケ。",
  ui_story_5004_50041601_26_dialog_content = "前の試合のコト考えると、自分1人の力だけじゃ、\n今後は厳しくなるかもしんないし。",
  ui_story_5004_50041601_27_dialog_content = "（本当にそんなことになるかな…？）",
  ui_story_5004_50041601_28_dialog_content = "それで、アンタたちと仲良くしときたいってハナシ。",
  ui_story_5004_50041601_29_dialog_content = "とにかく、一緒に頑張ろ。じゃ、あとで。",
  ui_story_5004_50041601_30_dialog_content = "待って。",
  ui_story_5004_50041601_31_dialog_content = "ん？何か言いたいコトあんの？",
  ui_story_5004_50041601_32_dialog_content = "一つ聞きたいんだけど…君とジュヌヴィエーヴってどういう関係なの？",
  ui_story_5004_50041601_33_dialog_content = "それな…聞かれると思った。",
  ui_story_5004_50041601_34_dialog_content = "あたしの答えなんか、聞いたところで満足できないと思うけど、まいっか。",
  ui_story_5004_50041601_35_dialog_content = "あたしたちは2人ともペドロ要塞の出身なんだ。\nあたしはマンティコア家、アイツはヴロンスキー家の生まれでさ。",
  ui_story_5004_50041601_36_dialog_content = "何て言うかな、お互いの家がずっといがみ合ってんの。\nあたしたち2人は、子供の頃仲良かったんだけどさ。",
  ui_story_5004_50041601_37_dialog_content = "あの頃のあいつ、超かわいくてさ、あたしにべったりだったんだ。\n今よりもっと人懐こかったしね。",
  ui_story_5004_50041601_38_dialog_content = "でもまぁ、それから少し経って、あたしもまだガキだったから、\nとにかく反抗的になって、刺激が欲しくてさ。",
  ui_story_5004_50041601_39_dialog_content = "で、ジュヌヴィエーヴが受けてた試験でちょっとハデにやったの。",
  ui_story_5004_50041601_X39_dialog_content = "そしたらそれが試験官に気に入られちゃったみたいでさ。\nあいつは白夜城の貴族の仲間入りするチャンスを逃したってわけ。",
  ui_story_5004_50041601_40_dialog_content = "あいつとあいつの家族はそれを恥だと思ったんだろうね。",
  ui_story_5004_50041601_41_dialog_content = "けど、あたしは刺激が欲しかっただけで、\nあの人たちがあそこまで弱いとは思ってもなかった。",
  ui_story_5004_50041601_42_dialog_content = "貴族とか何とかって面倒なんだよ。その後、あたしは家を出たってワケ。",
  ui_story_5004_50041601_43_dialog_content = "そんなことが…",
  ui_story_5004_50041601_44_dialog_content = "もういいっしょ。行くね。午後の試合も気合い入れてこ。",
  ui_story_5004_50041701_1_dialog_content = "ふぅ…",
  ui_story_5004_50041701_2_dialog_content = "PlayerName、緊張してる？",
  ui_story_5004_50041701_3_dialog_content = "ちょっとね…",
  ui_story_5004_50041701_4_dialog_content = "肩の力を抜いたほうがいいわ。ヒイロ長官も言ってたの。\n<color=#FFB400>車来たりて将迎え撃ち、水来たりて土で覆う</color>ってね。",
  ui_story_5004_50041701_5_dialog_content = "<color=#FFB400>「将来たりて兵迎え撃つ、水来たりて土を覆う」</color>じゃなかった？\n何が起こってもうまくやる方法はある、って事だよね。",
  ui_story_5004_50041701_6_dialog_content = "それそれ！ヒイロ長官がR・Wの車でもひっくり返したのかと思って、\nモヤモヤしてたのよ。",
  ui_story_5004_50041701_7_dialog_content = "（ヒイロさんが聞いてたら、書き写し100回ぐらいさせられそう…）",
  ui_story_5004_50041701_8_dialog_content = "今日は月繭を持って来たわ。先陣は私に任せて。",
  ui_story_5004_50041701_9_dialog_content = "それじゃ、私は場外からミサイルを撃って援護するよ～！",
  ui_story_5004_50041701_10_dialog_content = "ダメだよ！ほとんど戦い同然の試合って言っても、\n基本的なルールは守らないと。",
  ui_story_5004_50041701_11_dialog_content = "ラファエルのミサイルは…暗鬼退治のために取っておいたほうがいいと思うわ。",
  ui_story_5004_50041701_12_dialog_content = "あなたは白夜城の…天使なんでしょう？",
  ui_story_5004_50041701_13_dialog_content = "う～ん、それもそっか！ベリエちゃんを守るために取っておくね。",
  ui_story_5004_50041701_14_dialog_content = "じゃあ、ベリエちゃんと一緒に応援してるね！",
  ui_story_5004_50041701_15_dialog_content = "そういえば…バイスは守りのポジションだから、弓矢を使っては戦えないよね。",
  ui_story_5004_50041701_16_dialog_content = "そうなのよ。対策として、ベリエに頼んで\n弓に装着できる結晶製の双剣を作ってもらったの。",
  ui_story_5004_50041701_17_dialog_content = "試作に時間がかかって、今朝ようやく満足のいくものができたわ…",
  ui_story_5004_50041701_18_dialog_content = "助けになるといいけど…",
  ui_story_5004_50041701_19_dialog_content = "すごく丈夫で切れ味がよさそうよ。\nベリエが心を込めて作ってくれたんだって伝わるわ。",
  ui_story_5004_50041701_20_dialog_content = "（ベリエは素直だなぁ…）",
  ui_story_5004_50041701_21_dialog_content = "ありがとう！あとは私たちの勝利を見届けて！",
  ui_story_5004_50041701_22_dialog_content = "うん、なんだかバイスがとびきり頼もしく見えるよ。\n元気もいっぱいだし！",
  ui_story_5004_50041701_23_dialog_content = "（けど、そもそも弓とか双剣とか、何かおかしくない…？大丈夫？）",
  ui_story_5004_50041701_24_dialog_content = "激しい戦いになるかもしれないね、ただのチェスのはずだけど。",
  ui_story_5004_50041701_25_dialog_content = "…本当にそれだけで済めばいいけれど。\nスモーキーもジュヌヴィエーヴも、そう簡単に負けを認めないタイプよ。",
  ui_story_5004_50041701_26_dialog_content = "準備を万全に整えてかかる必要があるわ。",
  ui_story_5004_50041701_27_dialog_content = "は～い、皆さん位置につきましたね。",
  ui_story_5004_50041701_28_dialog_content = "どうぞお静かに――",
  ui_story_5004_50041701_29_dialog_content = "一説によると、大陸で広く親しまれているチェスは、\nこの地が起源であると言われています。",
  ui_story_5004_50041701_30_dialog_content = "かつてこの地に君臨していた賢明で慈愛に満ちた王は、\n民にも聡明で思慮深くあってほしいと願ったのです。",
  ui_story_5004_50041701_31_dialog_content = "そこでこのようなゲームを生み出し、\n民の思考能力と戦術を鍛えようとしたのだそうです。",
  ui_story_5004_50041701_32_dialog_content = "そうして王は、暗鬼が聞いただけで恐れおののく無敵の軍隊を手に入れ、\n国を侵略から守り、人々は平和に暮らすことができました。",
  ui_story_5004_50041701_33_dialog_content = "しかし、それも昔々のお話です。",
  ui_story_5004_50041701_34_dialog_content = "今日はその王を記念し、第2回戦、人間チェスを行います！",
  ui_story_5004_50041701_35_dialog_content = "知恵と決意を象徴するチェスの一戦――ただ今より、開始いたします！",
  ui_story_5004_50041701_36_dialog_content = "PlayerName！",
  ui_story_5004_50041701_37_dialog_content = "ここだよ！",
  ui_story_5004_50041701_38_dialog_content = "しっかりやってよ、指揮は任せるから。全力で勝ちに行ってやろうじゃん？",
  ui_story_5004_50041701_39_dialog_content = "（気合いだ、気合い…大丈夫、チェスならバートンとやったことはある）",
  ui_story_5004_50041701_40_dialog_content = "（思い出すんだ…バートンと戦った時…）",
  ui_story_5004_50041701_41_dialog_content = "俺たちが勝ったのは<color=#FFB400>「前もってナイトたちが道を切り拓いたから」</color>だ。",
  ui_story_5004_50041701_42_dialog_content = "そうだ…！！",
  ui_story_5004_50041701_43_dialog_content = "バートン、見てて…主将として、僕が先頭に立たないと！",
  ui_story_5004_50041701_44_dialog_content = "僕の番だ！",
  ui_story_5004_50041701_45_dialog_content = "キングを1マス前に！",
  ui_story_5004_50041701_46_dialog_content = "…",
  ui_story_5004_50041701_47_dialog_content = "PlayerNameよぉ…俺はチェスなんて全然分からねーが…",
  ui_story_5004_50041701_48_dialog_content = "お前が前に出ちゃならないことぐらいは分かるぜ。\n突っ込んで俺に乗っかかりたくない限りはな。",
  ui_story_5004_50041701_49_dialog_content = "ふふふ――",
  ui_story_5004_50041701_50_dialog_content = "空の末裔だったわね。\nあなたやあなたの一族が戦術や指揮に長けていることは知ってるわ。",
  ui_story_5004_50041701_51_dialog_content = "けれど、チェスの戦い方は、あなたにとって格式が高すぎたようね。",
  ui_story_5004_50041701_52_dialog_content = "あなたのお仲間たちに戦力で引けを取らないよう、\nこちらも強力な<color=#FFB400>勇者</color>たちを召集しているのよ――！",
  ui_story_5004_50041701_53_dialog_content = "チッ、この女、無駄話が多いぜ…正体は明かさない約束だからな。",
  ui_story_5004_50041701_54_dialog_content = "ボス！そんなことしたら契約の第3条第9項に違反しますよ。",
  ui_story_5004_50041701_55_dialog_content = "契約によれば報酬の135パーセントの違約金が発生します。",
  ui_story_5004_50041701_56_dialog_content = "うるさいわね。お金ならきっちり払うわよ…行きなさい！",
  ui_story_5004_50041701_57_dialog_content = "PlayerName！私と感知をつないで。指揮を手伝うから。",
  ui_story_5004_50041701_58_dialog_content = "分かった、お願いするよ！",
  ui_story_5004_50041701_59_dialog_content = "ハァッ――！",
  ui_story_5004_50041701_60_dialog_content = "うっ！！この人の剣術…ヒイロ長官に匹敵するわ…！",
  ui_story_5004_50041701_61_dialog_content = "それにこの戦い方…あなた、もしかして…！？",
  ui_story_5004_50041701_62_dialog_content = "はは…バレちまったもんはしゃーねぇな。もう隠す必要もねぇか。",
  ui_story_5004_50041701_63_dialog_content = "タキさん！！",
  ui_story_5004_50041701_64_dialog_content = "タキ！？",
  ui_story_5004_50041701_65_dialog_content = "どうしてここに？",
  ui_story_5004_50041701_66_dialog_content = "悪いな…何でも屋の仕事ってやつだ。\nカネが出て、道義に反する依頼でなければ、何でも受けるのさ！",
  ui_story_5004_50041701_67_dialog_content = "当然、こうやって試合に出ることだってある。手加減はしねぇぜ！？",
  ui_story_5004_50041701_68_dialog_content = "PlayerName、さっさと降参するのが身のためだ。\n丸腰のお前にケガはさせたくないからな！",
  ui_story_5004_50041701_69_dialog_content = "た、タキさん、バレてしまったら今後の商売に支障が出ますよ！",
  ui_story_5004_50041701_70_dialog_content = "隙あり！",
  ui_story_5004_50041701_71_dialog_content = "うわぁっ！",
  ui_story_5004_50041701_72_dialog_content = "カレン、加減して！ココナッツミルクがこぼれそう！",
  ui_story_5004_50041701_72X1_dialog_content = "何言ってんの？あれはカツラ、本物のココナッツなワケないっしょ。",
  ui_story_5004_50041701_72X2_dialog_content = "そ…そっか…あんまり出来がいいから…",
  ui_story_5004_50041701_73_dialog_content = "ジョム…だよね。",
  ui_story_5004_50041701_74_dialog_content = "ボス、聞いてください、これには訳が…\n<color=#FFB400>あなたのため</color>にこの依頼を受けたんですよ。",
  ui_story_5004_50041701_75_dialog_content = "えっ？僕のため？",
  ui_story_5004_50041701_76_dialog_content = "そうです！ジュヌヴィエーヴさんから賞金がもらえれば、\n経営規模を拡大できるんです。",
  ui_story_5004_50041701_77_dialog_content = "うまくいけば今後、<color=#FFB400>クリスタル</color>なんかも\n白夜コインと引き換えに俺から購入できるようになるかもしれませんよ。",
  ui_story_5004_50041701_78_dialog_content = "そしたら1割…いや、0.5割引きにして差し上げます。\nそれからその月限定の<color=#FFB400>かわいい小箱</color>もプレゼントしますよ。",
  ui_story_5004_50041701_79_dialog_content = "PlayerName、他の<color=#FFFFFF>カツラ</color>を被ってる人たちも怪しいわ…！",
  ui_story_5004_50041701_80_dialog_content = "まずはカツラを外しちゃえ～！",
  ui_story_5004_50041701_81_dialog_content = "分かったよ！バイス、カレン、お願い！",
  ui_story_5004_50041701_82_dialog_content = "な、なに！？チェーンソーがオイル切れだ！僕は帰るぞ！",
  ui_story_5004_50041701_83_dialog_content = "も、もうやめだ。ズラかるぜ！",
  ui_story_5004_50041701_84_dialog_content = "ピィ！",
  ui_story_5004_50041701_85_dialog_content = "フン、やっぱり当てにならない連中だったわね。",
  ui_story_5004_50041701_86_dialog_content = "おやおや、戦いはこう着状態に陥ったようですね。",
  ui_story_5004_50041701_87_dialog_content = "一方は駒が逃げ去り、もう一方はチェック寸前です。",
  ui_story_5004_50041701_88_dialog_content = "おい、早くあたしを動かせっつーの！",
  ui_story_5004_50041701_89_dialog_content = "プロモーションとかまっすぐ進むとか何でもいいからさ、\nあたしをジュヌヴィエーヴに近づけてくれれば倒せる！",
  ui_story_5004_50041701_90_dialog_content = "えっ？そういう訳にはいかないよ。この状況ならカレンにバイスを守ってもらって、\n形勢を整えてから攻めたほうが良いよ！",
  ui_story_5004_50041701_91_dialog_content = "そんな時間ないっしょ。向こうの士気が下がってる今こそチャンスなの。\nアンタのカノジョを助けに戻ってる余裕なんてないよ。",
  ui_story_5004_50041701_92_dialog_content = "え？僕たちはそんな関係じゃ…",
  ui_story_5004_50041701_93_dialog_content = "とにかく、あたしの言う通りにすれば勝てる！",
  ui_story_5004_50041701_94_dialog_content = "わ、分かったよ！",
  ui_story_5004_50041701_95_dialog_content = "ジュヌヴィエーヴ！",
  ui_story_5004_50041701_96_dialog_content = "スモーキー！かかってきなさい！",
  ui_story_5004_50041701_97_dialog_content = "オラァッ！",
  ui_story_5004_50041701_98_dialog_content = "いきなり最強技を！？",
  ui_story_5004_50041701_99_dialog_content = "ふんっ――",
  ui_story_5004_50041701_100_dialog_content = "受け止められた！？ジュヌヴィエーヴも格闘戦が上手い！？",
  ui_story_5004_50041701_101_dialog_content = "前回は油断していただけ。毎回勝てると思ったら大間違いよ！",
  ui_story_5004_50041701_102_dialog_content = "確かに前よりは強くなってるじゃん。\nでも、あたしを超えるなんてまだまだ早ぇよ！！",
  ui_story_5004_50041701_103_dialog_content = "ダメだ…拮抗してて勝負がつかない。このままじゃ会場に飛び火しちゃう！",
  ui_story_5004_50041701_104_dialog_content = "このまま勝負がつかなければ、制限時間を超過してしまいすね。",
  ui_story_5004_50041701_105_dialog_content = "止むを得ません――ルールを追加するとしましょう。",
  ui_story_5004_50041701_106_dialog_content = "サドンデスを行います！",
  ui_story_5004_50041701_107_dialog_content = "場内の中央には事前に「水晶の王」の駒が埋められています。",
  ui_story_5004_50041701_108_dialog_content = "両チームのうち、先に埋められた「王」を手にしたほうが勝ちとします！",
  ui_story_5004_50041701_109_dialog_content = "仕方ないわね…！親衛隊たち、出番よ！",
  ui_story_5004_50041701_110_dialog_content = "出陣！攻撃します！",
  ui_story_5004_50041701_111_dialog_content = "ジュヌヴィエーヴ様のために――！",
  ui_story_5004_50041701_112_dialog_content = "チッ。そいつら、どっかに消えたのかと思ってたけど、まーだいたんだな。",
  ui_story_5004_50041701_113_dialog_content = "ま、待って、一体どういうこと？水鉄砲なんて何に使うの？\nそもそも親衛隊の人たちが乱入していいの！？",
  ui_story_5004_50041701_114_dialog_content = "私が新たにお送りした冊子もお読みいただけていないようですね――",
  ui_story_5004_50041701_115_dialog_content = "新しいのは広告が2倍に増えてたよ！！",
  ui_story_5004_50041701_116_dialog_content = "先ほどの試合が注目されたので、急きょスポンサー様が増えたのです。",
  ui_story_5004_50041701_117_dialog_content = "ちなみに、先ほどの戦いはジュヌヴィエーヴが長時間動かなかったため、\n引き分けと見なされました。",
  ui_story_5004_50041701_118_dialog_content = "さておき、そういう訳ですから、\n予定に追加されていた水鉄砲バトルを開始します。使えるのは水鉄砲だけですよ！",
  ui_story_5004_50041701_119_dialog_content = "いずれにせよ、PlayerNameさん。\n始まる前に自分で「マニュアル」を読まなければ、いつまでも成長できませんよ――",
  ui_story_5004_50041701_120_dialog_content = "ガチガチの戦いから突然夏らしい感じの試合に変更されても、\n僕にはついていけないよ！",
  ui_story_5004_50041701_121_dialog_content = "しかも僕たち、水鉄砲なんて用意してないし…",
  ui_story_5004_50041701_122_dialog_content = "えっ？なんでみんな持ってるの！？",
  ui_story_5004_50041701_123_dialog_content = "バイス、援護するわ。反撃を！",
  ui_story_5004_50041701_124_dialog_content = "分かったわ！PlayerNameも早く隠れて！",
  ui_story_5004_50041701_125_dialog_content = "武器なんて何も持ってないよ！",
  ui_story_5004_50041701_126_dialog_content = "PlayerName！受け取って！",
  ui_story_5004_50041701_127_dialog_content = "ベリエ！助かるよ！！",
  ui_story_5004_50041701_128_dialog_content = "甘いわね！！",
  ui_story_5004_50041701_129_dialog_content = "うっ！！",
  ui_story_5004_50041701_130_dialog_content = "み、みんなすごいや！じゃない、スモーキー、なんとか打開策を――",
  ui_story_5004_50041701_131_dialog_content = "しゃーない、あたしの戦い方ってのを見せてやっか…！",
  ui_story_5004_50041701_132_dialog_content = "そんな<color=#FFB400>超大型の水鉄砲</color>、どこから持ってきたの！？",
  ui_story_5004_50041701_133_dialog_content = "頭数だけ増やせば勝てるなんて大間違いなんだよ！！",
  ui_story_5004_50041701_134_dialog_content = "まずい！ジュヌヴィエーヴ様をお守りするんだ！",
  ui_story_5004_50041701_135_dialog_content = "も、もうダメだ、隊長――",
  ui_story_5004_50041701_136_dialog_content = "うわぁ――！！！",
  ui_story_5004_50041701_136X1_dialog_content = "私の手下に手を出すなんて、ずいぶんと度胸があるじゃない。",
  ui_story_5004_50041701_136X2_dialog_content = "こっちも容赦しないわよ！",
  ui_story_5004_50041701_136X3_dialog_content = "うっ！目が開けられない！",
  ui_story_5004_50041701_136X4_dialog_content = "バイス、急いで後退！援護するわ。",
  ui_story_5004_50041701_136X5_dialog_content = "「ローズ・ハンター」の威力を思い知らせてあげる。",
  ui_story_5004_50041701_136X6_dialog_content = "ハァァッ――！！",
  ui_story_5004_50041701_136X7_dialog_content = "くっ！わ、私も…何も見えない…",
  ui_story_5004_50041701_136X8_dialog_content = "カレン、ここは別に海底じゃない、何とかなるよ！",
  ui_story_5004_50041701_136X9_dialog_content = "それに2人とも水属性の光力術が得意でしょ！？\n水鉄砲なんかに圧されてどうするの！？",
  ui_story_5004_50041701_136X10_dialog_content = "お～～～っほっほっほ！\n濡れねずみになりたくなければ、さっさと降参しなさい！",
  ui_story_5004_50041701_136X11_dialog_content = "アンタ、笑い声デカすぎ！",
  ui_story_5004_50041701_136X12_dialog_content = "スモーキー！？やはり、親衛隊が何人か集まった程度じゃ\n阻止できないってわけね…",
  ui_story_5004_50041701_136X13_dialog_content = "みんな、スモーキーに集中攻撃よ！あの2人から先に片付けておやり！",
  ui_story_5004_50041701_138_dialog_content = "はい！集中攻撃開始！",
  ui_story_5004_50041701_139_dialog_content = "ていっ――！やあっ――！はぁっ――！！",
  ui_story_5004_50041701_140_dialog_content = "うっざ…！これじゃ狙いが定めらんない！！",
  ui_story_5004_50041701_141_dialog_content = "スモーキーが圧されてる！ヘール！なんとかできない！？",
  ui_story_5004_50041701_142_dialog_content = "バカ言え、俺様に考えさせる気か！？\nお前が読まなかったルールなんか、俺様が読んでる訳ないだろ！",
  ui_story_5004_50041701_143_dialog_content = "準備なんか何もねぇ！こうなったら拳で向かってくしかねえな！",
  ui_story_5004_50041701_144_dialog_content = "待て、ヘール、PlayerName！俺のポケットに何が入ってたと思う？",
  ui_story_5004_50041701_145_dialog_content = "防水防塵、保温機能まで付いた<color=#FFB400>キャンプ用テント</color>だ！\nこれを張ってひとまず休もう。",
  ui_story_5004_50041701_146_dialog_content = "お前とテント！？勘弁してくれ！",
  ui_story_5004_50041701_147_dialog_content = "水鉄砲でテントが打たれる音がまるで雨音みたいだぜ。\nいい気分になると思わないか？",
  ui_story_5004_50041701_148_dialog_content = "それに<color=#FFB400>キャンプチェア</color>もあるぞ。\nしばらく腰を落ち着ければ――",
  ui_story_5004_50041701_149_dialog_content = "断る！！",
  ui_story_5004_50041701_150_dialog_content = "アンタら、キャンプなんかしてる場合じゃないっつーの！",
  ui_story_5004_50041701_151_dialog_content = "ヘールだっけ！？",
  ui_story_5004_50041701_152_dialog_content = "そうだぜ！何だ？",
  ui_story_5004_50041701_153_dialog_content = "あたしが時間を稼ぐ！\nその間にPlayerNameを真ん中へ連れてって、駒を掘らせな！",
  ui_story_5004_50041701_154_dialog_content = "？？？",
  ui_story_5004_50041701_155_dialog_content = "はぁ？何で俺様がお前に従わなきゃなんねぇんだ？",
  ui_story_5004_50041701_156_dialog_content = "その程度のこともできねーなら、テントで大人しく星でも数えてな！",
  ui_story_5004_50041701_157_dialog_content = "チッ…！！PlayerName、ちょっとの辛抱だ！",
  ui_story_5004_50041701_158_dialog_content = "や、やめておこうよ！他にも方法があるはず！",
  ui_story_5004_50041701_159_dialog_content = "3、2――",
  ui_story_5004_50041701_160_dialog_content = "ヘール、落ち着いて！僕を放して！",
  ui_story_5004_50041701_161_dialog_content = "1！",
  ui_story_5004_50041701_162_dialog_content = "せめて狙いは外さないで――！！",
  ui_story_5004_50041701_163_dialog_content = "…",
  ui_story_5004_50041701_164_dialog_content = "…",
  ui_story_5004_50041701_165_dialog_content = "PlayerName…",
  ui_story_5004_50041701_166_dialog_content = "目を覚まして…",
  ui_story_5004_50041701_167_dialog_content = "お母さん…？",
  ui_story_5004_50041701_168_dialog_content = "PlayerName、目を覚ませ…",
  ui_story_5004_50041701_169_dialog_content = "…ヘール！？",
  ui_story_5004_50041701_170_dialog_content = "私たちの勝ちよ…あなたはヘールに放り投げられて、\n親衛隊が張っていた水の弾幕を破り、駒を地面から打ち出した…",
  ui_story_5004_50041701_171_dialog_content = "その後、慌てた親衛隊が失神したあなたを撃ち始めたのよ。\nジュヌヴィエーヴが止めてくれたからよかったものの…",
  ui_story_5004_50041701_172_dialog_content = "ごめんなさい…溺れた人の救助訓練を受けてるのは、\n保安官のヘールだけだったから…",
  ui_story_5004_50041701_173_dialog_content = "そ、そうなんだ…とりあえず、もう少し休ませてもらえるかな…",
  ui_story_5004_50041901_1_dialog_content = "…",
  ui_story_5004_50041901_2_dialog_content = "ジュヌヴィエーヴ。",
  ui_story_5004_50041901_3_dialog_content = "お前は将来、ヴロンスキー家再興の重責を負うことになる。",
  ui_story_5004_50041901_4_dialog_content = "…",
  ui_story_5004_50041901_5_dialog_content = "あなたはまだ幼いけれど、厳しい訓練を乗り越えないとならないの。",
  ui_story_5004_50041901_6_dialog_content = "これもあなたのためよ。",
  ui_story_5004_50041901_7_dialog_content = "はい…分かっております、お父様、お母様。",
  ui_story_5004_50041901_8_dialog_content = "こちらは光力術の先生だ。礼儀作法も教えてくださる。\nかつて白夜城の貴族の一員だったお方だ。",
  ui_story_5004_50041901_9_dialog_content = "ヴロンスキー家のために、先生のご指導をしっかりと受けてちょうだいね。",
  ui_story_5004_50041901_10_dialog_content = "分かりました。",
  ui_story_5004_50041901_11_dialog_content = "お前ならしっかり勉強すれば、マンティコア家の娘に勝つことができるさ。",
  ui_story_5004_50041901_12_dialog_content = "ジュヌヴィエーヴ、ジュヌヴィエーヴ？",
  ui_story_5004_50041901_13_dialog_content = "先生、すみません。",
  ui_story_5004_50041901_14_dialog_content = "ぼんやりするなんて、あなたらしくありませんね。",
  ui_story_5004_50041901_15_dialog_content = "宿題を早く終わらせたくて、昨日夜遅くまで起きていたんです。",
  ui_story_5004_50041901_16_dialog_content = "あれは1週間分ですよ。そこまで頑張る必要はありません。",
  ui_story_5004_50041901_17_dialog_content = "…",
  ui_story_5004_50041901_18_dialog_content = "ジュヌヴィエーヴ、大きくなったら何がしたいですか？",
  ui_story_5004_50041901_19_dialog_content = "家族のために栄誉を勝ち取る…？",
  ui_story_5004_50041901_20_dialog_content = "あなた自身の望みは？",
  ui_story_5004_50041901_21_dialog_content = "分かりません…自分が何をしたいのか…何もないのかもしれません。",
  ui_story_5004_50041901_22_dialog_content = "やれやれ…この話はやめにしましょう。",
  ui_story_5004_50041901_23_dialog_content = "ジュヌヴィエーヴ、先週もマンティコア家の娘に会いにいきましたね？",
  ui_story_5004_50041901_24_dialog_content = "先生、どうしてそれを！？",
  ui_story_5004_50041901_25_dialog_content = "お静かに。心配せずとも、この事を知るのは私だけです。\n誰にも話していませんよ。",
  ui_story_5004_50041901_26_dialog_content = "ありがとうございます。",
  ui_story_5004_50041901_27_dialog_content = "ですが、なぜ…",
  ui_story_5004_50041901_28_dialog_content = "…いえ、聞かないでおきましょう。余計な質問でした。",
  ui_story_5004_50041901_29_dialog_content = "…",
  ui_story_5004_50041901_30_dialog_content = "ですが、ジュヌヴィエーヴ。一族の栄誉を勝ち取ることに、\n固執するべきではないのかもしれませんね。",
  ui_story_5004_50041901_31_dialog_content = "どうしてですか！？",
  ui_story_5004_50041901_32_dialog_content = "私がどうして今は貴族でないのか、分かりますか？",
  ui_story_5004_50041901_33_dialog_content = "先生、ここ数年間の熱心なご指導に感謝いたします。",
  ui_story_5004_50041901_34_dialog_content = "とんでもない。\nジュヌヴィエーヴには才能がありますし、とても努力家です。",
  ui_story_5004_50041901_35_dialog_content = "儀式魔術に関する知識は、すでに大多数の貴族を超えています。",
  ui_story_5004_50041901_36_dialog_content = "それゆえ、もはや私に教えられることは何もないのです。",
  ui_story_5004_50041901_37_dialog_content = "先生、これからどこへ行くんですか？",
  ui_story_5004_50041901_38_dialog_content = "あなたと同じです。私にも分かりません。\n何かを、あるいは誰かを探しにいくのかもしれませんね。",
  ui_story_5004_50041901_39_dialog_content = "それに、探し求めることそのものに、意義があるでしょうから。",
  ui_story_5004_50041901_40_dialog_content = "ジュヌヴィエーヴ、お元気で。",
  ui_story_5004_50041901_41_dialog_content = "何だって？暗鬼がもうそこまで迫っているだと！？",
  ui_story_5004_50041901_42_dialog_content = "私たちだけではペドロ要塞を守れないわ。\n白夜城に助けを求めなければ。",
  ui_story_5004_50041901_43_dialog_content = "白夜城のサラール家が援軍を派遣してくれると…ただし、条件があるそうよ。",
  ui_story_5004_50041901_44_dialog_content = "我が家の跡継ぎがどれほど儀式魔術を心得ているか、試験したいそうよ。\n結果によっては彼らの一族に加えたいとも言っているわ。",
  ui_story_5004_50041901_45_dialog_content = "あれほどの大貴族と縁を結ぶことができるなら、悪い話ではないな。\nヴロンスキー家にとっても大いに利益がある。",
  ui_story_5004_50041901_46_dialog_content = "ジュヌヴィエーヴ。",
  ui_story_5004_50041901_47_dialog_content = "分かっています、お父様。",
  ui_story_5004_50041901_48_dialog_content = "ジュヌヴィエーヴ・ヴロンスキーさん。やはりお強い。",
  ui_story_5004_50041901_49_dialog_content = "今回の試験が終われば、当主にお目に掛かれるでしょう。",
  ui_story_5004_50041901_50_dialog_content = "ありがとうございます。",
  ui_story_5004_50041901_51_dialog_content = "やっほ！",
  ui_story_5004_50041901_52_dialog_content = "スモーキー！？どうしてここに？",
  ui_story_5004_50041901_53_dialog_content = "試験があるって聞いたから、腕試しに来たんだ。",
  ui_story_5004_50041901_54_dialog_content = "光力術を使ってあの的を攻撃すればいいんだよね？",
  ui_story_5004_50041901_55_dialog_content = "あ、ちょっと！それは…！",
  ui_story_5004_50041901_56_dialog_content = "なんてパワーだ！こんな小さな娘のどこにそんな力が！",
  ui_story_5004_50041901_57_dialog_content = "き、君の名前は？どこの一族だ？",
  ui_story_5004_50041901_58_dialog_content = "ん？景品でもくれるワケ？つまんないものは受け取らないよ。",
  ui_story_5004_50041901_59_dialog_content = "よく覚えときな！あたしはマンティコア家のスモーキー！",
  ui_story_5004_50041901_60_dialog_content = "マンティコア家の…スモーキー…",
  ui_story_5004_50041901_61_dialog_content = "他に試験はないの？これだけ？",
  ui_story_5004_50041901_62_dialog_content = "そうだ！少々お待ちを！当主から君にお話がある…",
  ui_story_5004_50041901_63_dialog_content = "待ってろって？ムリムリ、今から服買いに行くから。",
  ui_story_5004_50041901_64_dialog_content = "ジュヌヴィエーヴ、行こ。街で遊ぼうよ。",
  ui_story_5004_50041901_65_dialog_content = "よくも…",
  ui_story_5004_50041901_66_dialog_content = "なんということだ、ジュヌヴィエーヴ…",
  ui_story_5004_50041901_67_dialog_content = "お前は千載一遇の機会を逃したのだ。",
  ui_story_5004_50041901_68_dialog_content = "それでもサラール家がペドロ要塞への援軍派遣を\n快諾してくれたからよかったものの…",
  ui_story_5004_50041901_69_dialog_content = "同盟を結ぶチャンスは逃してしまった。",
  ui_story_5004_50041901_70_dialog_content = "下がりなさい。",
  ui_story_5004_50041901_71_dialog_content = "申し訳ございません…お父様…",
  ui_story_5004_50041901_72_dialog_content = "（スモーキー…どうしてあんな所に現れたの…）",
  ui_story_5004_50041901_73_dialog_content = "（ただ単に試験に参加して…私に勝ちたかっただけ？…それとも…）",
  ui_story_5004_50041901_74_dialog_content = "ジュヌヴィエーヴ！",
  ui_story_5004_50041901_75_dialog_content = "お母様、どうかしたのですか？そんなに慌てて、まずは落ち着いて…",
  ui_story_5004_50041901_76_dialog_content = "聞きましたか！？",
  ui_story_5004_50041901_77_dialog_content = "サラール家がマンティコアを訪れて、取り決めを果たそうとしていると…",
  ui_story_5004_50041901_78_dialog_content = "もう向かっていたのですか？…知っています。婚姻のことですよね。",
  ui_story_5004_50041901_79_dialog_content = "それなのにあのスモーキーとかいう小娘とやら、姿を消したそうよ！",
  ui_story_5004_50041901_80_dialog_content = "えっ…",
  ui_story_5004_50041901_81_dialog_content = "スモーキーが逃げた！？",
  ui_story_5004_50041901_82_dialog_content = "何ということだ！ペドロ要塞の田舎者ごときが！鼻持ちならん！",
  ui_story_5004_50041901_83_dialog_content = "もういい、とんだ無駄足だった。\nだがこれで、こんな貧しい辺境に来る必要も二度とないだろう。",
  ui_story_5004_50041901_84_dialog_content = "聞け！当主より命令が下った。ペドロ要塞は「白夜城の庇護を必要としていない」！\n直ちに城へ撤収する！",
  ui_story_5004_50041901_85_dialog_content = "すでに落ち目だったペドロ要塞の没落は、決定的となった。",
  ui_story_5004_50041901_86_dialog_content = "お母様はショックで亡くなり、お父様も病に倒れた。",
  ui_story_5004_50041901_87_dialog_content = "ジュヌヴィエーヴ…",
  ui_story_5004_50041901_88_dialog_content = "ここにおります、お父様。",
  ui_story_5004_50041901_89_dialog_content = "お前が守るべき一族には、もはや先がない…",
  ui_story_5004_50041901_90_dialog_content = "お前は…苦しんでいるか…それとも肩の荷が下りたか？\nこれからの…目標は見つかったか…？",
  ui_story_5004_50041901_91_dialog_content = "それは…分かりません、お父様…\nすべてがあまりに突然すぎて、考える余裕もないのです。",
  ui_story_5004_50041901_92_dialog_content = "哀れな娘よ…",
  ui_story_5004_50041901_93_dialog_content = "…",
  ui_story_5004_50041901_94_dialog_content = "アンナ…あなたまで私のそばを離れていくなんて…",
  ui_story_5004_50041901_95_dialog_content = "ヒヒン…",
  ui_story_5004_50041901_96_dialog_content = "お嬢ちゃん、この馬はあなたのお友達？",
  ui_story_5004_50041901_97_dialog_content = "はい…",
  ui_story_5004_50041901_98_dialog_content = "このコを助けてあげてもいいわ。ただし、あなたも代償を…",
  ui_story_5004_50041901_99_dialog_content = "この子のためなら何でもします！私にはアンナが必要なんです！\n一緒にあいつを探さなきゃいけないんです！",
  ui_story_5004_50041901_100_dialog_content = "スモーキー…",
  ui_story_5004_50041901_100X1_dialog_content = "あなたがジュヌヴィエーヴさんですね？",
  ui_story_5004_50041901_100X2_dialog_content = "なぜそれを？用件があるなら単刀直入に言って。\n世間話には興味がないの。",
  ui_story_5004_50041901_100X3_dialog_content = "今日お持ちした世間話に、きっとご興味があるはずです。\nスモーキーに関することで…",
  ui_story_5004_50041901_100X4_dialog_content = "！！",
  ui_story_5004_50041901_100X5_dialog_content = "スモーキーを知っているの？",
  ui_story_5004_50041901_100X6_dialog_content = "もちろんです。彼女がルシェル・ド・アンジュビーチにいることも…",
  ui_story_5004_50041901_100X7_dialog_content = "えっ！？もしもし、まだ話は終わっていませんよ！？",
  ui_story_5004_50041901_102_dialog_content = "ジュヌヴィエーヴ様。",
  ui_story_5004_50041901_103_dialog_content = "ジュヌヴィエーヴ様！",
  ui_story_5004_50041901_104_dialog_content = "何？",
  ui_story_5004_50041901_105_dialog_content = "あなたのご指示通り、親衛隊が場を温めておきました。",
  ui_story_5004_50041901_106_dialog_content = "いいわ…次は私が直接、あいつの相手をする番ね。",
  ui_story_5004_50041901_107_dialog_content = "私の歌声でスモーキーを打ち負かして…いいえ、屈服させてみせる！",
  ui_story_5004_50042001_1_dialog_content = "きれいなステージね。フェラールがデザインしたの？",
  ui_story_5004_50042001_2_dialog_content = "R・W風の飾りがついてるし、違いないね～。",
  ui_story_5004_50042001_3_dialog_content = "フェラール、本当に何でもできるんだね…",
  ui_story_5004_50042001_4_dialog_content = "PlayerNameたちは参加しないの？",
  ui_story_5004_50042001_5_dialog_content = "僕はやめとくよ。歌うのはあんまり得意じゃないんだ…",
  ui_story_5004_50042001_6_dialog_content = "わ…私も…人が多いと、ダメ…",
  ui_story_5004_50042001_7_dialog_content = "私はベリエちゃんに付き添わなきゃだからパス～。",
  ui_story_5004_50042001_8_dialog_content = "ええ…！私とラファエルで…一生懸命みんなを応援するわ…！",
  ui_story_5004_50042001_9_dialog_content = "応援は私たちに任せて！いちばん盛り上がるところでミサイルを飛ばすから！",
  ui_story_5004_50042001_10_dialog_content = "絶対やめてよ！？",
  ui_story_5004_50042001_11_dialog_content = "分かった！よろしく頼んだわよ！",
  ui_story_5004_50042001_12_dialog_content = "あたしたちの歌、しっかり楽しんで、思いっきり応援しててよな！",
  ui_story_5004_50042001_13_dialog_content = "いつの間にか潮汐祭も最後のプログラムとなりました。\n知恵と美を象徴する――ビーチライブによる決戦です！――",
  ui_story_5004_50042001_14_dialog_content = "スポンサー様が続々と増えたおかげで、\n今回は大物ゲスト審査員をお呼びすることができました――",
  ui_story_5004_50042001_15_dialog_content = "白夜城からお越しの、匿名希望Sさん！",
  ui_story_5004_50042001_16_dialog_content = "ウォッホン！",
  ui_story_5004_50042001_17_dialog_content = "影ノ街からお越しの、匿名希望Yさん！",
  ui_story_5004_50042001_18_dialog_content = "やぁ。",
  ui_story_5004_50042001_19_dialog_content = "ボナーズ、審査員まで呼んだんだ…ん？2人ともどこかで見たことあるような？",
  ui_story_5004_50042001_20_dialog_content = "試合の勝者は審査員と会場の観客の皆様にお選びいただきます！",
  ui_story_5004_50042001_21_dialog_content = "それでは1人目――",
  ui_story_5004_50042001_22_dialog_content = "地獄から来た覆面メタルシンガー！――",
  ui_story_5004_50042001_23_dialog_content = "俺の名はセレレ。影ノ街からやってきた謎の歌手！本名は秘密だ！",
  ui_story_5004_50042001_24_dialog_content = "…セレウコスだよね？…名前と兜でバレバレだよ！",
  ui_story_5004_50042001_25_dialog_content = "魂の奥底から響く叫びをみんなに捧げるぜ――",
  ui_story_5004_50042001_26_dialog_content = "ワイルドなボイスで奏でる最強のヘビメタを味わってくれ！！",
  ui_story_5004_50042001_27_dialog_content = "やめろ！！",
  ui_story_5004_50042001_28_dialog_content = "ステージから降りろ！！",
  ui_story_5004_50042001_29_dialog_content = "水着ライブじゃなかったのか！？",
  ui_story_5004_50042001_30_dialog_content = "こんなんで盛り上がれるかっての！！",
  ui_story_5004_50042001_31_dialog_content = "広告と違うぞ！！",
  ui_story_5004_50042001_32_dialog_content = "女の子の水着を見に来たのに！金返せ！",
  ui_story_5004_50042001_33_dialog_content = "おいおい、こりゃ何てザマだ！本名を伏せておいてよかったぜ。",
  ui_story_5004_50042001_34_dialog_content = "それじゃあな、みんな、いつかまた会おう！",
  ui_story_5004_50042001_35_dialog_content = "えっ？これで1人目が終わり？あっという間だね～。",
  ui_story_5004_50042001_36_dialog_content = "残念…今の猫の被り物をした人、歌が上手そうだったのに…",
  ui_story_5004_50042001_37_dialog_content = "見た目に惑わされちゃダメだよ、ベリエ！",
  ui_story_5004_50042001_38_dialog_content = "とはいえセレウコス、これはうまくやってくれたね。",
  ui_story_5004_50042001_39_dialog_content = "おかげでみんなの期待値が見事に下がってる。\nこれでバイスたちは高得点間違いなしだ！",
  ui_story_5004_50042001_40_dialog_content = "お次は…え、フェラールとヘール？",
  ui_story_5004_50042001_41_dialog_content = "<color=#e8d9bb>ヘールはステージに上がり観客に向けてお辞儀をすると、後ろへ手を伸ばした…</color>",
  ui_story_5004_50042001_42_dialog_content = "やあ――",
  ui_story_5004_50042001_43_dialog_content = "うおぉぉ――！！！",
  ui_story_5004_50042001_44_dialog_content = "フェラールが微笑みかけてくれた！今の見た！？",
  ui_story_5004_50042001_45_dialog_content = "ラルラル、あなたのウインク1つでこの熱い心が射抜かれちゃうわ！",
  ui_story_5004_50042001_46_dialog_content = "キィ――キィ――",
  ui_story_5004_50042001_47_dialog_content = "カモメまで飛んできた！魚もほっぽり出して大丈夫なの！？",
  ui_story_5004_50042001_48_dialog_content = "本当にあれをやるのか？",
  ui_story_5004_50042001_49_dialog_content = "もちろんだ！わが友よ！",
  ui_story_5004_50042001_50_dialog_content = "ヘールが鉄筋をひっこ抜いた！？",
  ui_story_5004_50042001_51_dialog_content = "待った！まさかマジックをやるつもりじゃ！？",
  ui_story_5004_50042001_52_dialog_content = "あんな大がかりなマジック、\nR・Wの中でさえ賢くないことで評判のヘールにできるの！？",
  ui_story_5004_50042001_53_dialog_content = "きゃあ～――！！！",
  ui_story_5004_50042001_54_dialog_content = "<color=#e8d9bb>鉄筋が勢いよく白い布を突き破ってケースに刺さり、\n反対側から先端が突き出た。</color>",
  ui_story_5004_50042001_55_dialog_content = "フェラール様――！！！",
  ui_story_5004_50042001_56_dialog_content = "ケースがずっと揺れてるわ…",
  ui_story_5004_50042001_57_dialog_content = "フェラール、無事よね？…嫌な予感がするけど…",
  ui_story_5004_50042001_58_dialog_content = "心配しないで！救助する準備はできてるから！",
  ui_story_5004_50042001_59_dialog_content = "いや、命の危険はないよね…？",
  ui_story_5004_50042001_60_dialog_content = "（ヘールが何かつぶやいてる…まさか呪文のつもりとか…？）",
  ui_story_5004_50042001_61_dialog_content = "ケースが動かなくなったわ…ラファエル！",
  ui_story_5004_50042001_62_dialog_content = "よしきた！発射準備！",
  ui_story_5004_50042001_63_dialog_content = "待って！",
  ui_story_5004_50042001_64_dialog_content = "開け――！",
  ui_story_5004_50042001_65_dialog_content = "すごい！ホントにできた！",
  ui_story_5004_50042001_66_dialog_content = "よかった…",
  ui_story_5004_50042001_67_dialog_content = "な～んだ～、出番なしか。これじゃエネルギーの無駄使いだよ～。\nミサイル、ロックオン解除！",
  ui_story_5004_50042001_68_dialog_content = "ミサイル！？いつの間に！？何の救助にもならないよね！？",
  ui_story_5004_50042001_69_dialog_content = "…まぁいいや…とりあえず観客は今のパフォーマンスを楽しんだみたいだ。\n拍手と歓声が盛大に上がってる。",
  ui_story_5004_50042001_70_dialog_content = "フェラールが無事生きていたことに拍手ね…",
  ui_story_5004_50042001_71_dialog_content = "お待ちください！この試合は歌で競い合うものですよ！",
  ui_story_5004_50042001_72_dialog_content = "フェラール、ヘール！お2人とも、ルールをきちんと把握してください！\n分かってやっているなら許しませんよ！",
  ui_story_5004_50042001_73_dialog_content = "あはは、ごめんごめん。俺もみんなを楽しませて、\n試合を盛り上げたいと思ってさ。",
  ui_story_5004_50042001_74_dialog_content = "でも歌は苦手だから、他にはこの方法しか思いつかなかったんだ。",
  ui_story_5004_50042001_75_dialog_content = "あの女は誰！？フェラールにケチをつける気！？",
  ui_story_5004_50042001_76_dialog_content = "フェラールさん、あなたのパフォーマンスが必要なんです！",
  ui_story_5004_50042001_77_dialog_content = "（いっそ隠し芸大会みたいにしても悪くないんじゃ？）",
  ui_story_5004_50042001_78_dialog_content = "（それならセレウコスも退場しなくてすんだだろうし…）",
  ui_story_5004_50042001_79_dialog_content = "（いやいや、海に来て水着も着ずに猫の被り物をしてたんだ。\n覆面歌合戦とか、そういうのに参加したほうがいいね…有れば…）",
  ui_story_5004_50042001_80_dialog_content = "ダメなものはダメです。フェラールの参加資格を取り消します。",
  ui_story_5004_50042001_81_dialog_content = "歌じゃなくたっていい！",
  ui_story_5004_50042001_82_dialog_content = "フェラールさん、ホテルに戻って、\nマジックの続きを見せてください！",
  ui_story_5004_50042001_83_dialog_content = "ワンワン！ワンワンワン！",
  ui_story_5004_50042001_84_dialog_content = "ミャオー！",
  ui_story_5004_50042001_85_dialog_content = "人間以外の動物まで…フェラールの「特殊な体質」って恐ろしいなぁ…",
  ui_story_5004_50042001_86_dialog_content = "8人目の参加者は――",
  ui_story_5004_50042001_87_dialog_content = "ジュヌヴィエーヴ・ヴロンスキー！",
  ui_story_5004_50042001_88_dialog_content = "フフフ、まさかここまで誰も相手にならないとは思っていなかったわ。",
  ui_story_5004_50042001_89_dialog_content = "今なら審査員と観客を完璧に魅了して、一気に最高点を叩き出せる！",
  ui_story_5004_50042001_90_dialog_content = "（イロモノばっかりだ…）",
  ui_story_5004_50042001_91_dialog_content = "（バイスたちはまだかな？）",
  ui_story_5004_50042001_92_dialog_content = "PlayerName、ジュヌヴィエーヴの出番よ。",
  ui_story_5004_50042001_93_dialog_content = "そうだね。一番の強敵はやっぱり彼女みたいだ――",
  ui_story_5004_50042001_94_dialog_content = "雷雨に紛れ降り注げ♪",
  ui_story_5004_50042001_95_dialog_content = "――！！",
  ui_story_5004_50042001_96_dialog_content = "♪それは無情な神様の罰？それとも鎖を解く救い？",
  ui_story_5004_50042001_97_dialog_content = "遥かなる地平線の上♪",
  ui_story_5004_50042001_98_dialog_content = "そこには目まぐるしく変化するあなたの影♪",
  ui_story_5004_50042001_99_dialog_content = "捨てきれない恋心が嵐を呼ぶ♪",
  ui_story_5004_50042001_100_dialog_content = "ありきたりはごめんなの♪",
  ui_story_5004_50042001_101_dialog_content = "未来を切り開くパッション♪",
  ui_story_5004_50042001_102_dialog_content = "いがみあいにはクールな視線♪",
  ui_story_5004_50042001_103_dialog_content = "す…すごい。",
  ui_story_5004_50042001_104_dialog_content = "…",
  ui_story_5004_50042001_105_dialog_content = "うおおお！！ジュヌヴィエーヴ様ぁ！！！！",
  ui_story_5004_50042001_106_dialog_content = "うむ。情感豊かに歌い上げておる。\n観客にも伝わっているようだな。",
  ui_story_5004_50042001_107_dialog_content = "ジュヌヴィエーヴの歌声が心に染みわたってきた。\n機会があれば、ぜひ影ノ街でもコンサートを開いてほしいものだ。",
  ui_story_5004_50042001_108_dialog_content = "結果が出ました。ジュヌヴィエーヴの得点は――9.6点！",
  ui_story_5004_50042001_109_dialog_content = "おめでとうございます！高得点ですね。",
  ui_story_5004_50042001_110_dialog_content = "それでは、彼女にはステージ裏で休憩していただきましょう――",
  ui_story_5004_50042001_111_dialog_content = "どう？スモーキー…私の実力を思い知ったかしら！？",
  ui_story_5004_50042001_112_dialog_content = "いや～すごかった～…",
  ui_story_5004_50042001_113_dialog_content = "そうね…心にじんとくる歌声だったわ。",
  ui_story_5004_50042001_114_dialog_content = "（ジュヌヴィエーヴの歌は思った以上に素晴らしかった。\n親衛隊以外にも大勢の心を奪った）",
  ui_story_5004_50042001_115_dialog_content = "（バイスたちのことが少し心配になってきた…）",
  ui_story_5004_50042001_116_dialog_content = "お次は少女の3人組――マンティコア・キッス！",
  ui_story_5004_50042001_117_dialog_content = "バイスたちだ！",
  ui_story_5004_50042001_118_dialog_content = "とうとう来た…ああ…なんだか僕まで緊張してきちゃったよ。",
  ui_story_5004_50042001_119_dialog_content = "わ、私も…！",
  ui_story_5004_50042001_120_dialog_content = "♪――",
  ui_story_5004_50042001_121_dialog_content = "♪ ♩ ♫ ♬",
  ui_story_5004_50042001_122_dialog_content = "あてもなくさまよう 今日はどこへ向かうの♪",
  ui_story_5004_50042001_123_dialog_content = "灯台の明かりが灯れば、揺れる海岸線♪",
  ui_story_5004_50042001_124_dialog_content = "うおおお！！！",
  ui_story_5004_50042001_125_dialog_content = "ヒュ～ヒュ～ヒュ～！！",
  ui_story_5004_50042001_126_dialog_content = "（すごい…親衛隊の人たちからも津波みたいに拍手と歓声が上がってる）",
  ui_story_5004_50042001_127_dialog_content = "星降る海から 潮風の香り♪",
  ui_story_5004_50042001_128_dialog_content = "言葉は要らない 勇気を出して 鮮やかな花を咲かせるの♪",
  ui_story_5004_50042001_129_dialog_content = "覚悟を決めて 大波を超えれば 向こうには未来♪",
  ui_story_5004_50042001_130_dialog_content = "カレンちゃん！バイスちゃん！スモーキーちゃん！すご～い！！",
  ui_story_5004_50042001_131_dialog_content = "ほら、ベリエちゃんも私の手を握って！3人に手を振ろうよ！",
  ui_story_5004_50042001_132_dialog_content = "うん…！",
  ui_story_5004_50042001_133_dialog_content = "くじけない心を胸に あの光をつかみに行こう♪",
  ui_story_5004_50042001_134_dialog_content = "高鳴る鼓動を感じよう、今にも弾けそうな心♪",
  ui_story_5004_50042001_135_dialog_content = "力強くジャンプして♪",
  ui_story_5004_50042001_136_dialog_content = "想像も越えて あの場所へ♪",
  ui_story_5004_50042001_137_dialog_content = "まっすぐ進め♪",
  ui_story_5004_50042001_138_dialog_content = "頂へと――♪",
  ui_story_5004_50042001_139_dialog_content = "<color=#e8d9bb>スモーキーはマイクを片手に、もう片方の手でジュヌヴィエーヴに向けて\n射撃するポーズをとり、軽くウインクした。あっという間に1曲が終わった</color>",
  ui_story_5004_50042001_140_dialog_content = "<color=#e8d9bb>マンティコア・キッスのパフォーマンスは最高のクライマックスとなった…</color>",
  ui_story_5004_50042001_141_dialog_content = "…",
  ui_story_5004_50042001_142_dialog_content = "（ん？いつの間に来たんだろう？）",
  ui_story_5004_50042001_143_dialog_content = "すばらしかったわ。でも、昔は2人組だった。",
  ui_story_5004_50042001_144_dialog_content = "えっ？？",
  ui_story_5004_50042001_145_dialog_content = "（いなくなった？さっき、彼女は笑ってたよね？\nあれはどういう意味？なぞなぞ？）",
  ui_story_5004_50042001_146_dialog_content = "マンティコア・キッス！マンティコア・キッス！マンティコア・キッス！",
  ui_story_5004_50042001_147_dialog_content = "マンティコア・キッス！最高だ！",
  ui_story_5004_50042001_148_dialog_content = "よかった。みんなとっても満足してくれてる。\nベリエまで感動しちゃったみたいだ。",
  ui_story_5004_50042001_149_dialog_content = "全て間違いなく録画できておるのだろうな！",
  ui_story_5004_50042001_150_dialog_content = "は、はい、ソ…いえ、御主人様！",
  ui_story_5004_50042001_151_dialog_content = "このユニット…意外と面白い。",
  ui_story_5004_50042001_154_dialog_content = "マンティコア・キッス――",
  ui_story_5004_50042001_155_dialog_content = "文句のつけようもありません――10点満点です――！",
  ui_story_5004_50042201_1_dialog_content = "かんぱーい！",
  ui_story_5004_50042201_2_dialog_content = "はぁ――",
  ui_story_5004_50042201_3_dialog_content = "なんだよ、ジュースで乾杯なんて子供かよ！",
  ui_story_5004_50042201_4_dialog_content = "お前だって同じものを飲んでるじゃないか。",
  ui_story_5004_50042201_5_dialog_content = "それを言うな！",
  ui_story_5004_50042201_6_dialog_content = "あははは――",
  ui_story_5004_50042201_7_dialog_content = "カレンちゃん、バイスちゃん、スモーキーちゃん！\nさっきの歌、とってもすごかった！",
  ui_story_5004_50042201_8_dialog_content = "ステージ上の3人は夜空の星みたいに輝いてて、すっかり見とれちゃったよ。",
  ui_story_5004_50042201_9_dialog_content = "ベリエちゃんも感動で泣いちゃったぐらいだもんね！",
  ui_story_5004_50042201_10_dialog_content = "えっと…私…確かにとても感動的な歌声だったわ…",
  ui_story_5004_50042201_11_dialog_content = "ステージのみんなの歌と姿に…すっかり見とれて…",
  ui_story_5004_50042201_12_dialog_content = "ベリエもそう言うくらいだし、間違いなく素晴らしかったよ。",
  ui_story_5004_50042201_13_dialog_content = "お楽しみの賞品って一体何なのかしら！",
  ui_story_5004_50042201_14_dialog_content = "賞品のことはあたしも超気になってる。",
  ui_story_5004_50042201_15_dialog_content = "ボナーズに聞いても含み笑いするだけで答えてくれないんだ。\n明日受け取る時のお楽しみだね。",
  ui_story_5004_50042201_16_dialog_content = "何なのかしらね。私まですこし楽しみになってきたわ。",
  ui_story_5004_50042201_17_dialog_content = "かき氷屋が繁盛するようなおいしいシロップとか！",
  ui_story_5004_50042201_18_dialog_content = "そうすれば白夜城にもチェーン展開できるかもしれないわ！",
  ui_story_5004_50042201_19_dialog_content = "そんなことしたら…ラファエルたちに無許可営業で取り締まられるんじゃ…",
  ui_story_5004_50042201_20_dialog_content = "う～ん、バイスちゃんなら捕まえる前に1分間ぐらい待ってあげてもいいよ。",
  ui_story_5004_50042201_21_dialog_content = "ここにいたのね、おめでとう。",
  ui_story_5004_50042201_22_dialog_content = "ジュヌヴィエーヴ。\nありがとう、わざわざ…お祝いを言いに来てくれたの？",
  ui_story_5004_50042201_23_dialog_content = "フン。私は貴族だもの、それくらい当然よ。",
  ui_story_5004_50042201_24_dialog_content = "それとも、私が小さい子みたいに隠れて泣いているとでも思った？",
  ui_story_5004_50042201_25_dialog_content = "泣いてないの？あのジュヌヴィエーヴちゃんも大きくなったもんだね。\n昔は泣き虫だったじゃん。",
  ui_story_5004_50042201_26_dialog_content = "今ここで息の根を止めてやるわ！",
  ui_story_5004_50042201_27_dialog_content = "はいはい。そんなことより、こっち付き合いなよ？\n過去のイザコザなんてさ、飲んで洗い流せばいいっしょ？",
  ui_story_5004_50042201_28_dialog_content = "（スモーキーはジュヌヴィエーヴを掴んで、そばにあった椅子に座らせた。）",
  ui_story_5004_50042201_29X1_dialog_content = "ほら！",
  ui_story_5004_50042201_29X2_dialog_content = "チッ…うっとうしいわね。",
  ui_story_5004_50042201_29X3_dialog_content = "…これは…",
  ui_story_5004_50042201_29X4_dialog_content = "そ、ペドロ要塞でよく一緒に飲んだのに似てるっしょ？昔よく行ったじゃん。",
  ui_story_5004_50042201_29X5_dialog_content = "そ、そこまで似てなんかいないわ。\nだいたい、そんなものとっくに忘れたわよ！",
  ui_story_5004_50042201_29X6_dialog_content = "それに、マンティコア・キッスって…あの名前、どういうつもり？",
  ui_story_5004_50042201_29X7_dialog_content = "分かるっしょ。これとおんなじ。\nあの頃のこと、アンタが忘れてるワケないじゃん。",
  ui_story_5004_50042201_29X8_dialog_content = "…",
  ui_story_5004_50042201_30_dialog_content = "（この2人の関係、複雑なんだな…）",
  ui_story_5004_50042201_31_dialog_content = "フェラールのマジック…できればまた見たいわ。",
  ui_story_5004_50042201_32_dialog_content = "どうやったのか全然分からないの…",
  ui_story_5004_50042201_33_dialog_content = "もちろんさ！喜んでやるぜ。",
  ui_story_5004_50042201_34_dialog_content = "だったら次は人が少ない場所を選べよな！",
  ui_story_5004_50042201_35_dialog_content = "会場からお前を守って逃げるために、\nこっちは人の山に押されたり追いかけられたりして大変だったんだ。",
  ui_story_5004_50042201_36_dialog_content = "ヘールのお陰で助かったよ。あとで傷口を消毒してやろう。",
  ui_story_5004_50042201_37_dialog_content = "ちょうど、俺のロボット作りも終盤に差し掛かってる。\nついでに手を貸してほしいんだ。",
  ui_story_5004_50042201_38_dialog_content = "別に構わねぇけど、その話は後だ。今は楽しもうぜ。",
  ui_story_5004_50042201_39_dialog_content = "ロボットって、そんなに簡単にできるものなの？",
  ui_story_5004_50042201_40_dialog_content = "啓光の科学研究部門でも1体作るのに数か月はかかるわよ。",
  ui_story_5004_50042201_41_dialog_content = "ボナーズのお陰さ。頼まれた仕事をしてる間に、\n役に立つ装置や資料をたくさん手に入れてくれたんだよ。",
  ui_story_5004_50042201_42_dialog_content = "俺の心の中にずっとあった、完璧な、R・W最強の戦闘ロボット！",
  ui_story_5004_50042201_43_dialog_content = "それが今夜、いよいよ誕生するんだ！！",
  ui_story_5004_50042201_44_dialog_content = "（フェラール、すごく真剣だ…）",
  ui_story_5004_50042201_45_dialog_content = "（機械やロボットのこと、心底好きみたいだね…）",
  ui_story_5004_50042201_46_dialog_content = "今のは…？",
  ui_story_5004_50042201_47_dialog_content = "うっ…",
  ui_story_5004_50042201_48_dialog_content = "ベリエちゃん？ひどい汗！",
  ui_story_5004_50042201_49_dialog_content = "ラファエル…部屋まで連れて行ってくれる…？",
  ui_story_5004_50042201_50_dialog_content = "PlayerName、ベリエちゃんの具合が悪そうだから、先に帰るね。",
  ui_story_5004_50042201_51_dialog_content = "まだ回復してなかったってこと？\n力をたくさん使ったとはいえ、もう何日か経ってるはず…",
  ui_story_5004_50042201_52_dialog_content = "でも、確かに具合は良くないみたいね。",
  ui_story_5004_50042201_53_dialog_content = "単純な問題じゃないのかも…\nそうだ、ピュロスって家の資料のこと、ラファエルから聞いてるよね？",
  ui_story_5004_50042201_54_dialog_content = "ええ。ベルタ…ラファエルの助手がすべての資料を閲覧できるよう申請してあるわ。",
  ui_story_5004_50042201_55_dialog_content = "めぼしい情報が見つけられるかどうかは、あの子たち次第ね。",
  ui_story_5004_50042301_1_dialog_content = "儀式はもうすぐ成功する…",
  ui_story_5004_50042301_2_dialog_content = "「楽章」にかけられた空の末裔の封印を解かねばならないわ…\nそして演奏するのよ。",
  ui_story_5004_50042301_3_dialog_content = "そうすれば王の栄光が再びこの砂浜に輝き…\n傲慢な光霊どもに制裁が下ることになる…",
  ui_story_5004_50042301_4_dialog_content = "心得ております…！どうかご安心を、必ずや力を尽くして見せます。",
  ui_story_5004_50042301_5_dialog_content = "ごきげんよう。",
  ui_story_5004_50042301_6_dialog_content = "ボナーズ！！光霊はノックの1つもできないのか？",
  ui_story_5004_50042301_7_dialog_content = "くだらない話は抜きにしましょう。それより、私に何のご用ですか？",
  ui_story_5004_50042301_8_dialog_content = "まもなく楽章が掘り出される。その封印を…",
  ui_story_5004_50042301_9_dialog_content = "分かっていますよ。空の末裔の力が必要、そうですね。",
  ui_story_5004_50042301_10_dialog_content = "PlayerNameに何とかさせましょう。",
  ui_story_5004_50042301_11_dialog_content = "…お前、我々の企みが気になったりはしないのか？",
  ui_story_5004_50042301_12_dialog_content = "ええ、まったく。\nどんな陰謀か知りませんが、楽章さえあればあとはどうとでも。",
  ui_story_5004_50042301_13_dialog_content = "それに、そもそも成功できるのですか…？\nあの光霊たちの誰にしても、あなたたちをこてんぱんに打ちのめす力はありますよ。",
  ui_story_5004_50042301_14_dialog_content = "本気で何かしでかそうというのなら…\nまぁ、私にできることは、あなたたちがバラバラにならないことを祈るぐらいですね。",
  ui_story_5004_50042301_15_dialog_content = "詐欺商法に至っては笑うしかありません。",
  ui_story_5004_50042301_16_dialog_content = "ぐっ…！この光霊め、やはりお前は腹立たしいヤツだ！！",
  ui_story_5004_50042301_17_dialog_content = "事が終わったら始末してやる…",
  ui_story_5004_50042301_18_dialog_content = "ポリンゴ様！怒りをお鎮めください！",
  ui_story_5004_50042301_19_dialog_content = "あら？あなたもいたのですね。ヨガのレッスンに行かなくていいのですか？",
  ui_story_5004_50042301_20_dialog_content = "さて、私はPlayerNameたちに用がありますので、あとはご勝手に。",
  ui_story_5004_50042301_21_dialog_content = "お待ちを、ボナーズ様。",
  ui_story_5004_50042301_22_dialog_content = "新しく考えた宣伝文句がありまして。ご意見を伺いたいのですが…",
  ui_story_5004_50042301_23_dialog_content = "…",
  ui_story_5004_50042301_24_dialog_content = "利用している側のこちらが、なぜ腹を立てねばならんのだ！",
  ui_story_5004_50042301_25_dialog_content = "それに手下も役に立たん…ヨガの宣伝がそこまで大事か！？",
  ui_story_5004_50042301_26_dialog_content = "はぁ…",
  ui_story_5004_50042301_35_dialog_content = "よいしょ！ベリエちゃん、まずはベッドで横になってね～",
  ui_story_5004_50042301_36_dialog_content = "うーん…額と体がすごく熱い…汗も止まらないし…辛いよね？",
  ui_story_5004_50042301_37_dialog_content = "私は…大丈夫…",
  ui_story_5004_50042301_38_dialog_content = "タオルを持ってきて汗を拭いてあげるね！",
  ui_story_5004_50042301_39_dialog_content = "いらないわ…それより…",
  ui_story_5004_50042301_40_dialog_content = "添い寝していてくれる…？",
  ui_story_5004_50042301_41_dialog_content = "もちろんだよ～！",
  ui_story_5004_50042301_42_dialog_content = "熱が引かないなぁ…タオルを濡らして額に乗せたりとか…\n本当にしなくていいの？",
  ui_story_5004_50042301_43_dialog_content = "いいの…このままで…",
  ui_story_5004_50042301_44_dialog_content = "明日の授賞式が終わったら、\nPlayerNameに頼んでソラヴァンで白夜城に送ってもらうね。",
  ui_story_5004_50042301_45_dialog_content = "あそこの病院の方がきちんと看病できるから。",
  ui_story_5004_50042301_46_dialog_content = "それに白夜城にも面白い人がたくさんいるんだよ。\n他の天使も紹介してあげるね。",
  ui_story_5004_50042301_47_dialog_content = "みんな、ベリエちゃんのことが好きになるよ。",
  ui_story_5004_50042301_48_dialog_content = "そうだ、ウリエルって天使がいるんだけど、\nベリエちゃんみたいにいつも元気がなさそうなんだよね～。",
  ui_story_5004_50042301_49_dialog_content = "でも、あなたと同じで、頼もしいし、信頼できる仲間だよ。",
  ui_story_5004_50042301_50_dialog_content = "私も信頼できる仲間なの…？",
  ui_story_5004_50042301_51_dialog_content = "そうだよ！それからきれいなお店もたくさんあって～、レストランも色々あるよ。",
  ui_story_5004_50042301_52_dialog_content = "いつも行ってるお店に案内してあげるね。",
  ui_story_5004_50042301_53_dialog_content = "パンは好き？行きつけのパン屋さんがあるんだ～。一緒に行こうね！",
  ui_story_5004_50042301_54_dialog_content = "店長さんがすっごくいい人なの。\nいろんなパンやお菓子の作り方を教わったんだ！",
  ui_story_5004_50042301_55_dialog_content = "それから白夜城のコンサートホールもね。\nよくすごい人たちが演奏しに来てるよ。チケットは取りづらいけど～。",
  ui_story_5004_50042301_56_dialog_content = "そうなんだ…",
  ui_story_5004_50042301_57_dialog_content = "ベリエちゃん…？",
  ui_story_5004_50042301_58_dialog_content = "実は…ずっと話すべきか、悩んでいたことがあるの…",
  ui_story_5004_50042301_59_dialog_content = "なになに？話してよ。",
  ui_story_5004_50042301_60_dialog_content = "私…とても怖いの…",
  ui_story_5004_50042301_61_dialog_content = "ここを離れられなくなるんじゃないかって…不安なの…",
  ui_story_5004_50042301_62_dialog_content = "えっ？どうして？",
  ui_story_5004_50042301_63_dialog_content = "最近…毎日同じ夢を見るの…",
  ui_story_5004_50042301_64_dialog_content = "同じ夢を繰り返し…それもだんだん怖くなってきてるの…",
  ui_story_5004_50042301_65_dialog_content = "最初は、夢の中でうっすらと声がしただけだった…",
  ui_story_5004_50042301_66_dialog_content = "何かを訴えかけてきて…忘れていた昔のことを思い出してしまったの…",
  ui_story_5004_50042301_67_dialog_content = "（昔のこと…ゴーティエ家とピュロス家のこと…？）",
  ui_story_5004_50042301_68_dialog_content = "私が覚えていないことや、思い出したくないことまで聞かされるから…\nすごく怖くなっちゃって…",
  ui_story_5004_50042301_69_dialog_content = "最後には、その声が私に言うの…",
  ui_story_5004_50042301_70_dialog_content = "「お前の身体は崩れて制御を失い、すべての人間を死なせ、\n精神は深淵へと落ちていくだろう」って…",
  ui_story_5004_50042301_71_dialog_content = "！！",
  ui_story_5004_50042301_72_dialog_content = "夢のことを忘れようとしたんだけど…どうしても頭から離れなくて…",
  ui_story_5004_50042301_73_dialog_content = "それに確かに感じるの…体の調子がますます悪くなってるわ…",
  ui_story_5004_50042301_74_dialog_content = "ベリエちゃん…",
  ui_story_5004_50042301_75_dialog_content = "そんな夢の中の話、信じちゃダメだよ！",
  ui_story_5004_50042301_76_dialog_content = "えっ…",
  ui_story_5004_50042301_77_dialog_content = "ベリエちゃん。夢は夢だよ。それ以外の何でもないよ。",
  ui_story_5004_50042301_78_dialog_content = "具合が悪いのは、この2日間、ずっとみんなを手伝ってたからだよ。\nあと、遊びすぎたでしょ！",
  ui_story_5004_50042301_79_dialog_content = "夢の事は…PlayerNameに相談してみるね。\n感知能力が役に立つかもしれないし。",
  ui_story_5004_50042301_80_dialog_content = "ベリエちゃんは休んでて。話してくるね！",
  ui_story_5004_50042301_81_dialog_content = "私の言うことを聞いて、ちゃんと休んでてね。\n明日には白夜城に帰れるよ～！",
  ui_story_5004_50042301_82_dialog_content = "…うん。",
  ui_story_5004_50042301_83_dialog_content = "すぐに帰ってくるからね。待ってて！",
  ui_story_5004_50042301_84_dialog_content = "マズい…",
  ui_story_5004_50042301_85_dialog_content = "すぐに戻らないと…大変なことになる。",
  ui_story_5004_50042301_86_dialog_content = "何だと！それは本当か！？",
  ui_story_5004_50042301_87_dialog_content = "もう少しで…彼女にぶつかるところだった…",
  ui_story_5004_50042301_88_dialog_content = "本当だとしたら…ただちに「クイーン」に報告しなければ。",
  ui_story_5004_50042301_89_dialog_content = "重要な情報をお伝えしましたよね…今月のボーナスは…？",
  ui_story_5004_50042301_90_dialog_content = "…いいから、今は戻れ。",
  ui_story_5004_50042301_91_dialog_content = "役立たずめ！",
  ui_story_5004_50042301_92_dialog_content = "ど、どうかお許しください！",
  ui_story_5004_50042301_93_dialog_content = "私が手間をかけて駒を集めたというのに。お前たちが無能なせいで…",
  ui_story_5004_50042301_94_dialog_content = "やつらを逃がすことになるとは！！",
  ui_story_5004_50042301_95_dialog_content = "大変申し訳ございません！",
  ui_story_5004_50042301_96_dialog_content = "使えないわね。私が直々に手を打つ必要がありそうだわ…",
  ui_story_5004_50042301_97_dialog_content = "でも、残念ね…あの駒は一番のお気に入りだったのに…",
  ui_story_5004_50042301_98_dialog_content = "ヒッヒッヒッヒ…",
  ui_story_5004_50042401_1_dialog_content = "PlayerName！一緒に来て！",
  ui_story_5004_50042401_2_dialog_content = "引っ張らないでよ。\n今、バイスとかき氷屋の営業について話し合ってるところなんだけど。",
  ui_story_5004_50042401_3_dialog_content = "明日になれば賞金で店をグレードアップできるわ。\nそうなれば後は繁盛あるのみよ！",
  ui_story_5004_50042401_4_dialog_content = "そんなことはあと！ベリエちゃんの様子がおかしいの！",
  ui_story_5004_50042401_5_dialog_content = "ベリエが？どうしたの？",
  ui_story_5004_50042401_6_dialog_content = "今の様子だと、すぐにでも白夜城に戻って\n治療を受けてもらわないといけなくなりそうなの！",
  ui_story_5004_50042401_7_dialog_content = "PlayerName、今すぐ戻るべきよ。",
  ui_story_5004_50042401_8_dialog_content = "ここへ来た目的はベリエの心を休ませるため。\n忘れてはいないでしょうね。",
  ui_story_5004_50042401_9_dialog_content = "ここに滞在してべリエの症状が悪化するようなら、本末転倒よ。",
  ui_story_5004_50042401_10_dialog_content = "確かにそうだね！ひとまず、ベリエの様子を見に行こう！",
  ui_story_5004_50042401_11_dialog_content = "ああっ！痛い…目の前が真っ暗です…",
  ui_story_5004_50042401_12_dialog_content = "ごめん！ボナーズ、大丈夫？",
  ui_story_5004_50042401_13_dialog_content = "そうだ、用事ができて、すぐに白夜城へ戻らないといけないんだ。\n賞品はいらないよ！",
  ui_story_5004_50042401_14_dialog_content = "えっ？いらない？どういうことですか！？ちょっと！？",
  ui_story_5004_50042401_15_dialog_content = "ああ…実に頭が痛いですね！どうしてこんな時に限って問題が重なるのでしょう！？",
  ui_story_5004_50042401_16_dialog_content = "みんなを連れてきたよ…",
  ui_story_5004_50042401_17_dialog_content = "あれ…ベリエちゃん…？",
  ui_story_5004_50042401_18_dialog_content = "ベリエちゃん！？どこ行っちゃったの！？",
  ui_story_5004_50042401_19_dialog_content = "ゆ、揺すらないで…僕が誘拐したわけじゃあるまいし。",
  ui_story_5004_50042401_20_dialog_content = "ちゃんと休んでてって言ったのに！",
  ui_story_5004_50042401_21_dialog_content = "早く何とかしないと！あんな状態で歩き回ったら危ないよ！",
  ui_story_5004_50042401_22_dialog_content = "PlayerName！PlayerName！",
  ui_story_5004_50042401_23_dialog_content = "ねぇ、感知能力で助けてあげられるんじゃないかしら？",
  ui_story_5004_50042401_24_dialog_content = "分かってるよ！でも揺らされ続けてちゃ、感知できないよ！",
  ui_story_5004_50042401_25_dialog_content = "ラファエル、落ち着いて。PlayerNameを放してあげて。",
  ui_story_5004_50042401_26_dialog_content = "ふぅ…",
  ui_story_5004_50042401_27_dialog_content = "ホテルにはいないね。",
  ui_story_5004_50042401_28_dialog_content = "でも痕跡をたどることはできる…",
  ui_story_5004_50042401_29_dialog_content = "石像のある崖に向かったみたいだ。",
  ui_story_5004_50042401_30_dialog_content = "PlayerName、早く他の人も呼んで、\nベリエちゃんの捜索を手伝ってもらおうよ。",
  ui_story_5004_50042401_31_dialog_content = "えっ？みんなを呼ぶ？そこまでする必要あるかな？",
  ui_story_5004_50042401_32_dialog_content = "PlayerName、バカンスですっかり能天気になっているようね。",
  ui_story_5004_50042401_33_dialog_content = "ホテルの周辺は確かにしっかり安全が確保されているわ。",
  ui_story_5004_50042401_34_dialog_content = "けれど、来る途中に暗鬼の大群に遭ったのを忘れた？",
  ui_story_5004_50042401_35_dialog_content = "ベリエが暗鬼の集落に迷いこむようなことでもあれば…",
  ui_story_5004_50042401_36_dialog_content = "確かにそうだ…",
  ui_story_5004_50042401_37_dialog_content = "分かったよ！今すぐみんなを呼んで一緒に捜そう！",
  ui_story_5004_50042401_38_dialog_content = "みんな、来てくれてありがとう。\nジュヌヴィエーヴまで手伝ってくれるなんて、意外だったよ。",
  ui_story_5004_50042401_39_dialog_content = "水くせーよ。友達じゃんか。助け合うのは当たり前！",
  ui_story_5004_50042401_40_dialog_content = "こいつも、心は温かいんだ。性格はちょっと悪いけどさ。",
  ui_story_5004_50042401_41_dialog_content = "何ですって？私はあなたがしくじる瞬間を見逃したくないだけよ！",
  ui_story_5004_50042401_42_dialog_content = "あはは…せっかくの2人の時間を邪魔してなければいいんだけど。\nとにかく、今は急いでベリエを捜そう！",
  ui_story_5004_50042401_43_dialog_content = "PlayerName、こっちの方向で合ってる？\nこの森、なんだか怪しい雰囲気がするけど…",
  ui_story_5004_50042401_44_dialog_content = "合ってるよ。ベリエは確かにこの道を通ってる。",
  ui_story_5004_50042401_45_dialog_content = "けど…この辺を行ったり来たりしてるような気がする。\nそれにここ、昼間とは雰囲気が全く違うね。",
  ui_story_5004_50042401_46_dialog_content = "（この道、どこまで続いているのか先が見えない。\n辺りから動物の怯えた叫び声まで聞こえてくる。少し驚かされた…）",
  ui_story_5004_50042401_47_dialog_content = "待って、何か聞こえた気が…",
  ui_story_5004_50042401_48_dialog_content = "グアアァ――",
  ui_story_5004_50042401_49_dialog_content = "わぁ！！",
  ui_story_5004_50042401_50_dialog_content = "ボナーズ？どうしてここに？",
  ui_story_5004_50042401_51_dialog_content = "みなさんが急に帰るだなんて言うものですから、\n<color=#FFB400>「優勝賞品」</color>をお持ちしたんですよ！",
  ui_story_5004_50042401_52_dialog_content = "あなたたちこそ、どうしてここへ？",
  ui_story_5004_50042401_53_dialog_content = "まさか…帰る前に肝試し大会でも？",
  ui_story_5004_50042401_54_dialog_content = "でしたら、私も混ぜてくださいよ。",
  ui_story_5004_50042401_55_dialog_content = "肝試し大会なんかじゃないよ～！",
  ui_story_5004_50042401_56_dialog_content = "実は、ベリエがいなくなったんだ。\n帰るって言ったのも、彼女の体調が悪化したからだよ。",
  ui_story_5004_50042401_57_dialog_content = "病気がこれ以上悪くなったり、暗鬼なんかに出くわすんじゃないかって、\nラファエルが心配してるんだ。",
  ui_story_5004_50042401_58_dialog_content = "ああ…ベリエのことでしたか。\nそれなら同じ真理結社の人間として、放っておくわけにはいきませんね。",
  ui_story_5004_50042401_59_dialog_content = "ですが、ここは実に危険です。\n暗鬼以外にももっと恐ろしいものがいます！さらに邪悪な存在が！",
  ui_story_5004_50042401_60_dialog_content = "肝試しじゃないってば！怖い話は要らないよ！",
  ui_story_5004_50042401_61_dialog_content = "感知した限り、ベリエは崖を登って…今は移動してない。",
  ui_story_5004_50042401_62_dialog_content = "けど、さっきから森の中を行ったり来たりするだけで、全然出られなくて…",
  ui_story_5004_50042401_63_dialog_content = "仕方がありませんね、ベリエのためです。道案内をして差し上げましょう。\nみなさん、付いてきてください。",
  ui_story_5004_50042401_64_dialog_content = "ベリエちゃん！！",
  ui_story_5004_50042401_65_dialog_content = "来ないで…！",
  ui_story_5004_50042401_66_dialog_content = "そっちは危ないよ！それ以上進んじゃダメ！",
  ui_story_5004_50042401_67_dialog_content = "危ないのは分かってるの…だからこっちに来ないで…",
  ui_story_5004_50042401_68_dialog_content = "まずは落ち着いて…ベリエ、どうしてここに？",
  ui_story_5004_50042401_69_dialog_content = "私も…私にも分からない…",
  ui_story_5004_50042401_70_dialog_content = "ラファエルがいなくなったあと…やっぱり力が出なくて、ベッドに横になってたの…",
  ui_story_5004_50042401_71_dialog_content = "でも、突然体が動かせなくなって…",
  ui_story_5004_50042401_72_dialog_content = "そしたら黒い腕が…私の首に巻き付いて、目隠しされて…",
  ui_story_5004_50042401_73_dialog_content = "次に聞こえたのは恐ろしい笑い声…そこで気を失ったの…",
  ui_story_5004_50042401_74_dialog_content = "笑い声って、前に言ってた夢の中の人の声？",
  ui_story_5004_50042401_75_dialog_content = "うん…",
  ui_story_5004_50042401_76_dialog_content = "どうしてここにいるのか、自分でも分からないの…",
  ui_story_5004_50042401_77_dialog_content = "自分がどうしてこんなことになってしまったのかも…",
  ui_story_5004_50042401_78_dialog_content = "あの声の言う通りなら…私は大切な人たちをこの手で死なせることになる…",
  ui_story_5004_50042401_79_dialog_content = "そんなの、単なる悪い夢だよ！",
  ui_story_5004_50042401_80_dialog_content = "悪夢だとしても！その悪夢に操られて、今ここにいるの！",
  ui_story_5004_50042401_81_dialog_content = "目の前で大切な人が死ぬところなんて、もう二度と見たくない！！",
  ui_story_5004_50042401_82_dialog_content = "そんな話はやめて！",
  ui_story_5004_50042401_83_dialog_content = "…",
  ui_story_5004_50042401_84_dialog_content = "ぜったい大丈夫だから！みんなと一緒に、砂浜の勇者になれたでしょ！",
  ui_story_5004_50042401_85_dialog_content = "（そんな話で、効果はあるのかな…？）",
  ui_story_5004_50042401_86_dialog_content = "ラファエル…",
  ui_story_5004_50042401_87_dialog_content = "一緒に白夜城へ帰るって約束したでしょ…",
  ui_story_5004_50042401_88_dialog_content = "ラファエル…",
  ui_story_5004_50042401_89_dialog_content = "戻っておいで、そっちは危険だよ。",
  ui_story_5004_50042401_90_dialog_content = "おいおい、あの晶石、このままじゃヤバそうじゃん？",
  ui_story_5004_50042401_91_dialog_content = "晶石が爆発するよ！",
  ui_story_5004_50042401_92_dialog_content = "PlayerName、危ない！",
  ui_story_5004_50042401_93_dialog_content = "ベリエちゃん！！",
  ui_story_5004_50042401_95_dialog_content = "…！！",
  ui_story_5004_50042401_96_dialog_content = "ベリエちゃん！！",
  ui_story_5004_50042401_97_dialog_content = "ラファエル！？",
  ui_story_5004_50042401_98_dialog_content = "早く私の手をつかんで！",
  ui_story_5004_50042401_99_dialog_content = "うん…！",
  ui_story_5004_50042401_100_dialog_content = "ごめんなさい…私のせいで…",
  ui_story_5004_50042401_101_dialog_content = "ラファエルが護衛隊の天使でも…この高さから落ちれば無傷とはいかないわ。",
  ui_story_5004_50042401_102_dialog_content = "あなたと一緒に…白夜城へ行きたかった…",
  ui_story_5004_50042401_103_dialog_content = "<size=45>ね、何て言った？</size>",
  ui_story_5004_50042401_104_dialog_content = "い…一緒に街で遊ぶ？",
  ui_story_5004_50042401_105_dialog_content = "<size=45>その前！</size>",
  ui_story_5004_50042401_106_dialog_content = "ラファエルが天使でも…？",
  ui_story_5004_50042401_107_dialog_content = "全ミサイル発射…荷重解除…祝福の十字架準備…最大出力！！",
  ui_story_5004_50042401_108_dialog_content = "<size=45>ベリエちゃん、天使ってね――飛べるんだよ――！</size>",
  ui_story_5004_50042401_109_dialog_content = "ベリエちゃん、しっかり掴まってて！そんなに長持ちしないの！",
  ui_story_5004_50042401_110_dialog_content = "放して！ラファエル！2人分の重さには耐えきれないわ。\nこのままじゃ、2人とも…",
  ui_story_5004_50042401_111_dialog_content = "いいから！",
  ui_story_5004_50042401_112_dialog_content = "私は絶対、絶～っ対に放さないから！",
  ui_story_5004_50042401_113_dialog_content = "<color=#e8d9bb>ガラガラガラガラ――</color>",
  ui_story_5004_50042401_114_dialog_content = "（もう限界？）",
  ui_story_5004_50042401_115_dialog_content = "<size=50><color=#e8d9bb>バン――</color></size>",
  ui_story_5004_50042401_116_dialog_content = "ラファエル、ラファエル、目を覚まして…",
  ui_story_5004_50042401_117_dialog_content = "ベリエちゃん…",
  ui_story_5004_50042401_118_dialog_content = "ベリエちゃん、ケガはない？",
  ui_story_5004_50042401_119_dialog_content = "私は…大丈夫…",
  ui_story_5004_50042401_120_dialog_content = "ありがとう…",
  ui_story_5004_50042401_121_dialog_content = "無事ならよかった～。ベリエちゃんもよく頑張ったね。",
  ui_story_5004_50042401_123_dialog_content = "あとはPlayerNameたちが迎えに来るのを待つだけだよ。",
  ui_story_5004_50042401_124_dialog_content = "待って…ラファエル、あれは…！？",
  ui_story_5004_50042401_125_dialog_content = "グォォ！",
  ui_story_5004_50042401_126_dialog_content = "グ…ガァ…！！",
  ui_story_5004_50042401_127_dialog_content = "暗鬼…どうしてこんなにたくさん…",
  ui_story_5004_50042401_128_dialog_content = "ベリエちゃん！まだ戦える？",
  ui_story_5004_50042401_129_dialog_content = "うん！",
  ui_story_5004_50042401_130_dialog_content = "（PlayerName…急いで！）",
  ui_story_5004_50042501_1_dialog_content = "ボナーズ、崖の下までの近道を案内して！",
  ui_story_5004_50042501_2_dialog_content = "分かりました。こちらです。\nオバケに連れていかれないよう、ちゃんとついてきてくださいね。",
  ui_story_5004_50042501_2X1_dialog_content = "じきに楽章が手に入る。それからボナーズに送り届けるのだ。",
  ui_story_5004_50042501_2X2_dialog_content = "あの女が空の末裔に封印を解かせ、演奏する。\nそうしてようやく「静かなる王」は蘇るのだ。",
  ui_story_5004_50042501_2X3_dialog_content = "ポリンゴ様、我々は大いに苦労してホテルに潜入し、\n潮汐祭を開いて光霊たちのエネルギーを集めてきました。",
  ui_story_5004_50042501_2X4_dialog_content = "今度はどうにかして空の末裔に封印を解かせ、\nボナーズに楽章を演奏させるとおっしゃいますが…",
  ui_story_5004_50042501_2X5_dialog_content = "それで本当に王が蘇るというのですか？\nそうしたところで、我々にどんなメリットが？",
  ui_story_5004_50042501_2X6_dialog_content = "これは8大ファントムのお1人からのご命令だ…\n王は強大な力を持った暗鬼だそうだ。",
  ui_story_5004_50042501_2X7_dialog_content = "蘇らせることができれば、あの頑迷無知な光霊どもを一度に始末できるとな。",
  ui_story_5004_50042501_2X8_dialog_content = "そうだと良いですが…分かりかねますな。\nおっと、どうして急に止まられたのです？",
  ui_story_5004_50042501_2X9_dialog_content = "外で戦いの音だ…隠れろ！",
  ui_story_5004_50042501_3_dialog_content = "ここに隠れておけば、ひとまず見つからないでしょ。",
  ui_story_5004_50042501_4_dialog_content = "こんなところに洞穴があるなんて…でも、真っ暗よ…",
  ui_story_5004_50042501_5_dialog_content = "ガォ！！",
  ui_story_5004_50042501_6_dialog_content = "う～！暗鬼がうっとうしいよ～！もう懲りてよ！",
  ui_story_5004_50042501_7_dialog_content = "ベリエちゃん、あとどれくらいがんばれそう？",
  ui_story_5004_50042501_8_dialog_content = "ふぅ…ふぅ…わ、私は平気…まだ戦えるわ…",
  ui_story_5004_50042501_10_dialog_content = "グアア！！！",
  ui_story_5004_50042501_11_dialog_content = "グォォ！！！",
  ui_story_5004_50042501_12_dialog_content = "いけない！来た道が塞がれちゃった！",
  ui_story_5004_50042501_13_dialog_content = "もう、ムカつく～！！",
  ui_story_5004_50042501_14_dialog_content = "ラファエルさん、ベリエ！",
  ui_story_5004_50042501_15_dialog_content = "大丈夫！？",
  ui_story_5004_50042501_16_dialog_content = "PlayerName、遅すぎ～！",
  ui_story_5004_50042501_17_dialog_content = "レディをこんなに待たせちゃダメだよ！",
  ui_story_5004_50042501_18_dialog_content = "ごめん！暗鬼たちにやり返してやろう！",
  ui_story_5004_50042601_1_dialog_content = "ふぅ、ようやく片づいた…",
  ui_story_5004_50042601_2_dialog_content = "ラファエル、ベリエ、2人とも無事？ひどいケガはない？",
  ui_story_5004_50042601_3_dialog_content = "と～ぜん無事だよ！\n私がいる限り、ベリエちゃんにケガはさせないもん！",
  ui_story_5004_50042601_4_dialog_content = "ええ…ラファエルが守ってくれたの…",
  ui_story_5004_50042601_5_dialog_content = "無事でよかったわ。ひとまずホテルへ戻りましょう。",
  ui_story_5004_50042601_6_dialog_content = "ベリエの夢のことは、私やラファエル、\nそれから巨像にいる他の光霊たちと、何とかして一緒に解決しましょ。",
  ui_story_5004_50042601_7_dialog_content = "そうそう。ジュヌヴィエーヴなら何か知ってるっしょ。\n助けてくれるよ。",
  ui_story_5004_50042601_8_dialog_content = "何よ？急に私を巻き込まないでくれる？\n今回は知り合いのよしみで力を貸しただけよ。",
  ui_story_5004_50042601_9_dialog_content = "まったく…知人に鉱物の研究者がいるわ。\n戻ったら彼に聞いてあげる。",
  ui_story_5004_50042601_10_dialog_content = "それじゃ、急いでホテルに戻ろう。それからすぐ白夜城へ帰るんだ。",
  ui_story_5004_50042601_11_dialog_content = "ボナーズ、帰りも道案内をお願いできる？",
  ui_story_5004_50042601_12_dialog_content = "ボナーズ？",
  ui_story_5004_50042601_13_dialog_content = "少々お待ちを。こんなところにボタンがありますよ。",
  ui_story_5004_50042601_14_dialog_content = "えいっ。",
  ui_story_5004_50042601_15_dialog_content = "まぶしい…！ここは？",
  ui_story_5004_50042601_16_dialog_content = "（周囲のすべてに見覚えがあるような気がする。これは…錯覚？）",
  ui_story_5004_50042601_17_dialog_content = "PlayerName、大変よ。来た道が塞がれたわ。",
  ui_story_5004_50042601_18_dialog_content = "えっ？",
  ui_story_5004_50042601_19_dialog_content = "ダメね、押しても開かない。",
  ui_story_5004_50042601_20_dialog_content = "施設を…封鎖…<size=33>システムを…</size><size=35>再起動してください…</size>",
  ui_story_5004_50042601_21_dialog_content = "…？",
  ui_story_5004_50042601_22_dialog_content = "みんな、この扉を開けるわ、手伝って！",
  ui_story_5004_50042601_23_dialog_content = "…やっぱりダメね。びくともしない。攻撃も弾かれるわ。",
  ui_story_5004_50042601_24_dialog_content = "ねぇ、PlayerName。ここって巨像の中に似てると思わない…？",
  ui_story_5004_50042601_25_dialog_content = "確かにちょっと似てる。でも、そんなはずは…\nそうだ、ボナーズは？どこ行ったの？",
  ui_story_5004_50042601_26_dialog_content = "どこ？どこ？どこかしら～♪",
  ui_story_5004_50042601_27_dialog_content = "私の心、愛、すべて、そして夢～♪",
  ui_story_5004_50042601_28_dialog_content = "忌まわしい暗鬼たちよ、一体どこへ隠したの～♪",
  ui_story_5004_50042601_29_dialog_content = "おや、<size=45>お宝</size>ですね！",
  ui_story_5004_50042601_29X1_dialog_content = "…あら？お2人とも、どうしてこんなところに？",
  ui_story_5004_50042601_29X2_dialog_content = "しっ…！外にいる光霊に聞こえるだろう。",
  ui_story_5004_50042601_29X3_dialog_content = "楽章を手に入れて、あなたに届けようとしていたところです。",
  ui_story_5004_50042601_29X4_dialog_content = "えっ？ということは、この中に楽章が？",
  ui_story_5004_50042601_29X5_dialog_content = "そうだ。必ず空の末裔に…",
  ui_story_5004_50042601_29X6_dialog_content = "分かっていますよ。空の末裔に封印を解かせるんですよね。\nちゃんと覚えています。",
  ui_story_5004_50042601_29X7_dialog_content = "これで楽章の後半も手に入りました…\nあなたたちはゆっくりお休みになってくださいな…",
  ui_story_5004_50042601_29X8_dialog_content = "！危ない！ポリンゴ様！！",
  ui_story_5004_50042601_29X9_dialog_content = "<color=#e8d9bb>ドーン――ドッカーン――</color>",
  ui_story_5004_50042601_29X10_dialog_content = "見えないよう隅っこに寄せておきましょう…よいしょっと…！これで完璧です！",
  ui_story_5004_50042601_30_dialog_content = "<size=45>PlayerName？まだそこにいらっしゃいますか？</size>",
  ui_story_5004_50042601_31_dialog_content = "扉に鍵がかかってて閉じ込められてるんだ！どこに行ってたの？",
  ui_story_5004_50042601_32_dialog_content = "ひとまずこちらへいらしてください。\n<color=#FFB400>面白いもの</color>をお見せしますよ――",
  ui_story_5004_50042601_33_dialog_content = "それは？",
  ui_story_5004_50042601_34_dialog_content = "これ…<color=#FFB400>空の末裔が作ったもの</color>？",
  ui_story_5004_50042601_35_dialog_content = "やはり、そうですよね。あなたならこれが何だか分かると思ったのです。",
  ui_story_5004_50042601_36_dialog_content = "空の末裔の作ったものがあって、建物も巨像の内部に似ている…\nまさか、ここは巨像の内部そのものなの？",
  ui_story_5004_50042601_37_dialog_content = "そんなこと、私には分かりませんよ。\n私はしがない音楽家、イベントの主催者でしかないのですから。",
  ui_story_5004_50042601_38_dialog_content = "待ち…跡を…継ぐ者…",
  ui_story_5004_50042601_39_dialog_content = "（まただ…）",
  ui_story_5004_50042601_40_dialog_content = "PlayerNameさん、試しに感知してみたらどうでしょう？",
  ui_story_5004_50042601_41_dialog_content = "PlayerName、嫌な予感がするわ。",
  ui_story_5004_50042601_42_dialog_content = "でも、ここに閉じ込められちゃってるし…試してみるしかないよね？",
  ui_story_5004_50042601_43_dialog_content = "そうね…十分警戒して。",
  ui_story_5004_50042601_44_dialog_content = "待ちわびた…跡を継ぐ者…",
  ui_story_5004_50042601_45_dialog_content = "…<color=#FFB400>「楽章」</color>を持ち去るというなら…必ずや…それ…",
  ui_story_5004_50042601_46_dialog_content = "呼び覚ましてはならない…",
  ui_story_5004_50042601_47_dialog_content = "二度と…大地を沈めては…",
  ui_story_5004_50042601_48_dialog_content = "ねえ！扉が開くよ！",
  ui_story_5004_50042701_49_dialog_content = "アンタたちのおかげ？トビラ蹴りすぎて足が筋肉痛だよ。",
  ui_story_5004_50042701_50_dialog_content = "ボナーズ、今、箱から何を取り出したの？",
  ui_story_5004_50042701_51_dialog_content = "もしかして、君が持ってるのが「楽章」？",
  ui_story_5004_50042701_52_dialog_content = "おや？PlayerNameさんはご存じでしたか。\nこれこそ、私が長い間探し求めてきた「神鳴りの楽章」の一部です。",
  ui_story_5004_50042701_53_dialog_content = "（さっき聞こえた声が言ってたのは…これのことだ！）",
  ui_story_5004_50042701_54_dialog_content = "どうしてここに「楽章」があると知ってたの？\nそれに、さっきの暗鬼たちはどこから？",
  ui_story_5004_50042701_55_dialog_content = "…暗鬼はどう考えても「楽章」を守っていたんだよね。",
  ui_story_5004_50042701_56_dialog_content = "おやおや。さすがは空の末裔です、勘が鋭いようで。",
  ui_story_5004_50042701_57_dialog_content = "お察しの通りですよ。\n私と暗鬼はちょっとした取引をしていたのです。",
  ui_story_5004_50042701_58_dialog_content = "なんですって…！？",
  ui_story_5004_50042701_59_dialog_content = "大したことではありませんよ？\n私が利用しただけで、暗鬼どものために悪事を働いていたわけではありません。",
  ui_story_5004_50042701_60_dialog_content = "私は楽譜を受け取る。\n代わりに、私は潮汐祭の試合開催を手伝う。それだけです。",
  ui_story_5004_50042701_61_dialog_content = "潮汐祭…？つまり、潮汐祭には暗鬼の陰謀が？",
  ui_story_5004_50042701_62_dialog_content = "知りませんよ。私にとって何よりも大事なのは頭の中の声に従うこと、\nそして楽章を手に入れる事ですから。",
  ui_story_5004_50042701_63_dialog_content = "…音楽のため？そんなのおかしくない？いや、絶対におかしい！",
  ui_story_5004_50042701_64_dialog_content = "欲しいものは手に入れたのなら、これからどうするの？\n暗鬼と共謀を続けるつもり？",
  ui_story_5004_50042701_65_dialog_content = "共謀ではありません！利用しているだけだと言っています。\nそれに、楽章はPlayerNameに差し上げるつもりです。",
  ui_story_5004_50042701_66_dialog_content = "僕にくれる？苦労して手に入れたものを、そのまま？",
  ui_story_5004_50042701_67_dialog_content = "もともと、これが潮汐祭の<color=#FFB400>「優勝賞品」</color>でしたから。",
  ui_story_5004_50042701_68_dialog_content = "それと、あなた方に隠し事をしていたのも確かですから、そのお詫びでもあります。\nただ、お渡しする前に演奏して頂きます。",
  ui_story_5004_50042701_69_dialog_content = "それって…僕らが一生懸命に摘んだ果物を、\n君が最初に食べるみたいだね。",
  ui_story_5004_50042701_70_dialog_content = "まぁまぁ。私たち、仲間じゃありませんか。\nほら、ご覧ください――",
  ui_story_5004_50042701_71_dialog_content = "え？まったく同じものがもう1つある！？",
  ui_story_5004_50042701_72_dialog_content = "当然です。この2つが合わさって、初めて楽章は完成するのです。",
  ui_story_5004_50042701_73_dialog_content = "おや…？",
  ui_story_5004_50042701_74_dialog_content = "これ…だけですか？一瞬光って終わりでしょうか？",
  ui_story_5004_50042701_75_dialog_content = "どういうこと…？",
  ui_story_5004_50042701_76_dialog_content = "…この中からエネルギーを感じる…でも、何かに抑えられてる。",
  ui_story_5004_50042701_77_dialog_content = "（やはり、ダメでしたか…あの<color=#FFB400>ネズミ</color>が言っていたことを試すしかありませんね）",
  ui_story_5004_50042701_78_dialog_content = "PlayerName、ひとつ試してみましょう。\nこれを感知してください！",
  ui_story_5004_50042701_79_option_content = "イヤだ",
  ui_story_5004_50042701_80_dialog_content = "暗鬼と取引して手に入れたものなんて、触りたくもないよ！",
  ui_story_5004_50042701_81_dialog_content = "今回だけです！もう二度と暗鬼とは取引しないと、誓いますから！",
  ui_story_5004_50042701_82_option_content = "頼まれたからには…",
  ui_story_5004_50042701_83_dialog_content = "…やっぱりダメ！",
  ui_story_5004_50042701_84_dialog_content = "危険なものにしか見えないよ！",
  ui_story_5004_50042701_85_dialog_content = "皆さんここにいるんですから、心配はありませんよ。お願いします！",
  ui_story_5004_50042701_86_option_content = "仕方ない、試してみよう",
  ui_story_5004_50042701_87_dialog_content = "でもさっき、声が聞こえて、\nうかつに封印を解いちゃいけないって言ってたよ。",
  ui_story_5004_50042701_88_dialog_content = "聞き間違いでしょう。どうかお願いします！",
  ui_story_5004_50042701_89_dialog_content = "それじゃ、もう二度と暗鬼と取引しないって約束してくれる？",
  ui_story_5004_50042701_90_dialog_content = "ええ、もちろんですとも。二度といたしません！",
  ui_story_5004_50042701_91_dialog_content = "…",
  ui_story_5004_50042701_92_option_content = "（感知を始める）",
  ui_story_5004_50042701_93_dialog_content = "うまくいった…？",
  ui_story_5004_50042701_94_dialog_content = "…素晴らしい。",
  ui_story_5004_50042701_95_dialog_content = "ありがとうございます…PlayerName…",
  ui_story_5004_50042701_96_dialog_content = "ボナーズ…！何するつもり！？",
  ui_story_5004_50042701_97_dialog_content = "ああ…なんと麗しい…封印が解かれただけでも、その呼び声を感じられる…",
  ui_story_5004_50042701_98_dialog_content = "申し訳ありません…PlayerName…",
  ui_story_5004_50042701_99_dialog_content = "私は…私という存在は…今この時、神鳴りの楽章を演奏するためにあるのです！",
  ui_story_5004_50042701_100_dialog_content = "これは…とんでもない力と、イヤな気配を感じる！",
  ui_story_5004_50042701_101_dialog_content = "ボナーズ！！",
  ui_story_5004_50042701_102_dialog_content = "あっははははは！",
  ui_story_5004_50042701_103_dialog_content = "これこそが！なんと美しい旋律！美しすぎる！",
  ui_story_5004_50042701_104_dialog_content = "マズい…力が出ないわ…",
  ui_story_5004_50042701_105_dialog_content = "みんな、演奏を聞いてはだめ！",
  ui_story_5004_50042701_106_dialog_content = "やめて！ボナーズ！",
  ui_story_5004_50042701_107_dialog_content = "私の頭の中で響く声に与えられた最も崇高な使命。\nそれこそ、この楽章を集めること。",
  ui_story_5004_50042701_108_dialog_content = "この期に及んでやめろだなんて、あんまりな言い草です。",
  ui_story_5004_50042701_112_dialog_content = "これはボナーズの力？…いや、彼女の目の前にある楽章からあふれ出てる！",
  ui_story_5004_50042701_113_dialog_content = "ハァ…！？なんだ、アレ…！！",
  ui_story_5004_50042701_114_dialog_content = "あれは…？海の中から…城が現れた！？",
  ui_story_5004_50042701_115_dialog_content = "あの城は…まさか…",
  ui_story_5004_50042701_116_dialog_content = "PlayerName、聞こえていますか？\nこれこそ何にも囚われない、神をも揺るがす旋律です。",
  ui_story_5004_50042701_117_dialog_content = "空の末裔は音楽をじつに解っていたようです。\nこれほど美しく感動的な音楽を世に広めず、独り占めしようと言うのですから。",
  ui_story_5004_50042701_118_dialog_content = "なんと素晴らしいものを作り上げたのでしょう！\n空の末裔という人々のこと、ますます気に入りましたよ――",
  ui_story_5004_50042701_119_dialog_content = "これこそまさに真理の音、神鳴りの音なのです！",
  ui_story_5004_50042701_120_dialog_content = "私の頭の中に響き渡っています、PlayerName！",
  ui_story_5004_50042701_121_dialog_content = "ベリエちゃん、PlayerName、ぼーっとしないで！\nボナーズの上のほうで何かが光ってる！",
  ui_story_5004_50042701_122_dialog_content = "隕石よ！ものすごい勢いでこっちに落ちてくる！",
  ui_story_5004_50042701_123_dialog_content = "隕石！？どうやって！？",
  ui_story_5004_50042701_124_dialog_content = "時間が無い、すぐにぶつかるわ！みんな気をつけて！",
  ui_story_5004_50042701_125_dialog_content = "血染めの結晶！！",
  ui_story_5004_50042701_126_dialog_content = "うわぁっ！",
  ui_story_5004_50042701_127_dialog_content = "大丈夫！？",
  ui_story_5004_50042701_128_dialog_content = "ちょっと波に打たれたけど、大丈夫だよ。ベリエのお陰だ…",
  ui_story_5004_50042701_129_dialog_content = "もっと大きいのが降って来るわ！",
  ui_story_5004_50042701_130_dialog_content = "私…私が全力で止めてみせる。",
  ui_story_5004_50042701_131_dialog_content = "（まずい…こんな巨大な隕石、僕たちが力を合わせても対処しきれない…）",
  ui_story_5004_50042701_132_dialog_content = "このままじゃ…",
  ui_story_5004_50042701_133_dialog_content = "諦めるのはまだ早いぜ、PlayerName――",
  ui_story_5004_50042701_134_dialog_content = "この声は！",
  ui_story_5004_50042701_135_dialog_content = "その通り！機械の真実の友ことフェラールと、その親友、ヘールが帰ってきたぞ！",
  ui_story_5004_50042701_136_dialog_content = "PlayerName、\n俺のレディーゼルエンジン・メカレンチVゼロ号機の力、しかと見届けてくれ！！",
  ui_story_5004_50042701_137_dialog_content = "いっけえぇぇぇぇ！",
  ui_story_5004_50042701_138_dialog_content = "大声で叫ぶなよ、うるさいぞ！\nいつも機械をいじってる時の100倍は楽しんでやがるな！？",
  ui_story_5004_50042701_139_dialog_content = "出力アップだ！こいつならまだまだいける！！",
  ui_story_5004_50042701_140_dialog_content = "あ？？上げるってどれだ？ええい、全部やっちまえ！！",
  ui_story_5004_50042701_141_dialog_content = "そうだ、その調子だ！俺の命を真っ赤に燃やせ！！！",
  ui_story_5004_50042701_142_dialog_content = "おい、ランプがずっと点きっぱなしだぞ！どういうことだ！？",
  ui_story_5004_50042701_143_dialog_content = "オーバーヒートのアラームだ！",
  ui_story_5004_50042701_144_dialog_content = "何だよソレ！？",
  ui_story_5004_50042701_145_dialog_content = "30秒後に爆発する！",
  ui_story_5004_50042701_146_dialog_content = "俺のレディーゼルエンジン・メカレンチVゼロ号機！\n俺たちと共に、魂を燃やし尽くそう！！",
  ui_story_5004_50042701_147_dialog_content = "フェラール、隕石の軌道をずらせばいいだけだ！",
  ui_story_5004_50042701_148_dialog_content = "空に返す必要はないよ！！",
  ui_story_5004_50042701_149_dialog_content = "フェラール！",
  ui_story_5004_50042701_150_dialog_content = "了解！！",
  ui_story_5004_50042701_151_dialog_content = "隕石め――\n<size=45>吹っ飛べぇぇ！！！</size>",
  ui_story_5004_50042701_152_dialog_content = "（まぶしい！）",
  ui_story_5004_50042701_153_dialog_content = "PlayerName、やったわ！隕石の軌道がずれた！",
  ui_story_5004_50042701_154_dialog_content = "これって本当に大丈夫！？私が知ってるロボットの知識的に、\nオーバーヒートで今にもバラバラになりそうだよ！？",
  ui_story_5004_50042701_157_dialog_content = "PlayerName、ぼうっとしてないで、海から離れなさい！",
  ui_story_5004_50042701_158_dialog_content = "大波が来るわ！！",
  ui_story_5004_50042701_159_dialog_content = "うっ！ボナーズに足をやられて力が入らない！",
  ui_story_5004_50042701_160_dialog_content = "PlayerName、私の手をつかんで！",
  ui_story_5004_50042701_161_dialog_content = "無理だよ――間に合わない！",
  ui_story_5004_50042701_162_dialog_content = "PlayerName！大丈夫か！",
  ui_story_5004_50042701_163_dialog_content = "これが…空の末裔の技術を組み合わせたってやつ…？",
  ui_story_5004_50042701_164_dialog_content = "その通り！空の末裔の技術を取り入れて作られた、最強のロボットだ！",
  ui_story_5004_50042701_165_dialog_content = "…残念ながら、空の末裔の技術の部分は\nさっき隕石を押しのける時にほとんど壊れちまったけどな。",
  ui_story_5004_50042701_166_dialog_content = "それって、あの妙な推進装置のことね。",
  ui_story_5004_50042701_167_dialog_content = "啓光も白夜城も、今日1日で俺様に借りができたな！",
  ui_story_5004_50042701_168_dialog_content = "次にR・Wのボスを選ぶときは俺様に投票しろよ、分かったな！ワハハハハ！",
  ui_story_5004_50042701_169_dialog_content = "ヘールは相変わらずだね…それより、ボナーズは？",
  ui_story_5004_50042701_170_dialog_content = "はぁ～気分爽快！最高です！",
  ui_story_5004_50042701_171_dialog_content = "うわっ！急にどこから出てきたの！？",
  ui_story_5004_50042701_172_dialog_content = "ずっと近くにいましたよ。さっき大波が押し寄せた時にも\n皆さんと一緒に必死で逃げていました。気づかれなかっただけです。",
  ui_story_5004_50042701_173_dialog_content = "さあ、楽章をどうぞ。",
  ui_story_5004_50042701_174_dialog_content = "え？もう渡しちゃっていいの？まだ何か企んでるんじゃ…",
  ui_story_5004_50042701_175_dialog_content = "企てなどありません。最初から私の目的は楽章を演奏すること、それだけです。",
  ui_story_5004_50042701_176_dialog_content = "それに、旋律は一度演奏すれば私の魂に刻み込まれます。\nこれはもはやただの器です。用はありません。",
  ui_story_5004_50042701_177_dialog_content = "もともと空の末裔のものなのですから、あなたにお渡しするべきでしょう。",
  ui_story_5004_50042701_178_dialog_content = "ご安心ください。もう二度とそれを演奏したりはしません。\nですからどうか、お許しくださいね。",
  ui_story_5004_50042701_179_dialog_content = "（ごまかして済ませるつもり…？）",
  ui_story_5004_50042701_180_dialog_content = "こんな危険なもの、厳重に保管しておかないと…",
  ui_story_5004_50042701_181_dialog_content = "放っておいたら、悪意のある人に利用されるかもしれないわ。",
  ui_story_5004_50042701_182_dialog_content = "確かにそうだね…それじゃ、受け取るよ。\nけど、僕らを騙したことまで許した訳じゃないからね！",
  ui_story_5004_50042701_183_dialog_content = "暗鬼との取引について、洗いざらい話してもらうよ！",
  ui_story_5004_50042801_E1_dialog_content = "私の知っていることはもう全部お話ししましたよ！",
  ui_story_5004_50042801_E2_dialog_content = "…じゃあ、君は本当に楽章を手に入れることだけが目的で\n潮汐祭の実施に協力したの？",
  ui_story_5004_50042801_E3_dialog_content = "そうです！本当に本当ですよ！",
  ui_story_5004_50042801_E4_dialog_content = "はぁ、分かったよ…",
  ui_story_5004_50042801_E5_dialog_content = "ついに…我が王がお目覚めになる…",
  ui_story_5004_50042801_E6_dialog_content = "…なんと？あなたを目覚めさせた「勇者」を\nその目でご覧になりたいのですか？",
  ui_story_5004_50042801_E7_dialog_content = "待って、何か声が聞こえない…？耳元でかすかに聞こえるような…",
  ui_story_5004_50042801_E8_dialog_content = "もちろん…もちろんです…フフフ…\n彼らもあなたにお目に掛かれる時を待ちわびていることでしょう…",
  ui_story_5004_50042801_E9_dialog_content = "ですが、あなたの力はまだ完全ではございません…\n私がお力添えいたしましょう…",
  ui_story_5004_50042801_E10_dialog_content = "声？まださっきの演奏が頭に残ってるような気はするけど…\n…いえ、暗力が急に強くなったみたいね。",
  ui_story_5004_50042801_E11_dialog_content = "強烈な暗力が突然…いったいどこから？\nどうして今までまったく気が付かなかったの！？",
  ui_story_5004_50042801_E12_dialog_content = "<color=#e8d9bb>「楽章が響き渡り、探求の旅は終わりを告げ、王は蘇る。\n星々に火をともし、人々に災いと怒りをもたらすために。」</color>",
  ui_story_5004_50042801_E13_dialog_content = "…",
  ui_story_5004_50042801_184_dialog_content = "グォォ――！",
  ui_story_5004_50042801_185_dialog_content = "あれは、さっきの戦いで逃げていった暗鬼！",
  ui_story_5004_50042801_186_dialog_content = "いや、違う…あいつは…！",
  ui_story_5004_50042802_1_dialog_content = "すごく、強い…ただの暗鬼じゃないわ。",
  ui_story_5004_50042802_2_dialog_content = "どこから来たのかしら？\nあんな姿の暗鬼は、今まで見たことが無いわね。",
  ui_story_5004_50042802_3_dialog_content = "けど、倒せてよかったわ。これで悪事は果たせないわね。",
  ui_story_5004_50042802_4_dialog_content = "…いや、これはただの分身だよ。",
  ui_story_5004_50042802_5_dialog_content = "戦いの最中に感じたんだ、何か巨大な力が後ろで暗鬼を操ってる。",
  ui_story_5004_50042802_6_dialog_content = "その力の源が…「城」にある。",
  ui_story_5004_50042802_7_dialog_content = "（さっきからドタバタしていたせいで、\nあのヘンな城のことをすっかり忘れるところだった…）",
  ui_story_5004_50042802_8_dialog_content = "（でも今ははっきりと感じる…恐ろしく強大な暗力が勢いを増して放出されてる）",
  ui_story_5004_50042802_9_dialog_content = "なるほど…あの暗鬼たちの仕業でしょうね。これはしてやられました…",
  ui_story_5004_50042802_10_dialog_content = "どうりで楽章をあっさりと私に渡したわけです…\n私とPlayerNameの力を利用して、あれを呼び覚ますつもりだったのでしょう。",
  ui_story_5004_50042802_11_dialog_content = "あのネズミたち、潮汐祭の狙いがお金儲け以外にもあったなんて…",
  ui_story_5004_50042802_12_dialog_content = "次があれば奴らを叩きのめしてから、楽章だけ奪うことにしましょう。",
  ui_story_5004_50042802_13_dialog_content = "お金儲け！？暗鬼にどうしてお金が必要なの！？",
  ui_story_5004_50042802_14_dialog_content = "確か、光霊どもはお金を奪われれば貧乏になって、\n仕事に追われて反抗どころではなくなるだろうとかなんとか…",
  ui_story_5004_50042802_15_dialog_content = "私は楽章のことで頭がいっぱいだったので、\n他のことはあまり気にしていなかったのです。",
  ui_story_5004_50042802_16_dialog_content = "PlayerName、あの城へ向かって、敵の様子を探るべきね。",
  ui_story_5004_50042802_17_dialog_content = "カレンの言う通りよ。放っておけばビーチのみんなが危ないわ。\nそれだけじゃ済まないかもしれない。",
  ui_story_5004_50042802_18_dialog_content = "もうここまで来たんだし、今さらビビって逃げることでもないっしょ？",
  ui_story_5004_50042802_19_dialog_content = "ただの暗鬼でしょうけど、縛って連れて帰れば賞金にはなるかもしれないわね。",
  ui_story_5004_50042802_20_dialog_content = "あの…私もみんなと行きたいの…あの城、とても気になって…",
  ui_story_5004_50042802_21_dialog_content = "ベリエちゃんがそう言うなら、私も行く～！",
  ui_story_5004_50042802_22_dialog_content = "何見てんだよ。ビーチの安全を守るのは保安官の仕事だろ。",
  ui_story_5004_50042802_23_dialog_content = "それじゃ、俺のレディーゼルエンジン・メカレンチVゼロ号機を使って\nみんなを送って行くよ！",
  ui_story_5004_50042802_24_dialog_content = "仕方がありませんね。私にも責任がありますから、同行しましょう。\n秘蔵のパーツとエネルギー源をロボットに補給させていただきます。",
  ui_story_5004_50042802_25_dialog_content = "私を利用した図太い暗鬼を、容赦なく始末してやりましょう！",
  ui_story_5004_50042802_26_dialog_content = "よし、出発の準備をしよう！",
  ui_story_5004_50042901_1_dialog_content = "フェラール、君の…ええと、メカレンチVってまだ大丈夫なの？",
  ui_story_5004_50042901_2_dialog_content = "レディーゼルエンジン・メカレンチVゼロ号機だ！",
  ui_story_5004_50042901_3_dialog_content = "巨像のジェット技術もあるし、\nさっきボナーズからエネルギーを補給してもらった。大丈夫さ！",
  ui_story_5004_50042901_4_dialog_content = "ボナーズ、自分を利用した暗鬼に仕返しするつもりなんだね…",
  ui_story_5004_50042901_5_dialog_content = "ん？待って、巨像の技術ってことは…\nソラヴァンみたいに急に動力を失ったりするんじゃ！？",
  ui_story_5004_50042901_6_dialog_content = "フェラール！気をつけて、高く飛びすぎないようにして！",
  ui_story_5004_50042901_7_dialog_content = "えっ？なんでだ？",
  ui_story_5004_50042901_8_dialog_content = "ん！？",
  ui_story_5004_50042901_9_dialog_content = "なんだ！？どうなってる！？\n計器の数字がメチャクチャに上がったり下がったりしてるぞ！？",
  ui_story_5004_50042901_10_dialog_content = "フェラール、どうしたの！？",
  ui_story_5004_50042901_11_dialog_content = "も、問題ないさ、ははは…計器の数値に異常が出ただけだろ？",
  ui_story_5004_50042901_12_dialog_content = "本当に計器だけ！？",
  ui_story_5004_50042901_13_dialog_content = "墜落しそうだぞ！この鉄クズ、やっぱり頼りになんねえじゃねぇか！",
  ui_story_5004_50042901_14_dialog_content = "俺のレディーゼルエンジン・メカレンチVゼロ号機は決して落ちない！",
  ui_story_5004_50042901_15_dialog_content = "いや、今まさに落ちてるって！本当に！早く何とかして！！",
  ui_story_5004_50042901_16_dialog_content = "垂直飛行で城に降りる！みんな、掴まってて！",
  ui_story_5004_50042901_17_dialog_content = "垂直飛行って何だよ、どう見ても墜落じゃ…",
  ui_story_5004_50042901_18_dialog_content = "慌てるな！絶対に大丈夫だ！俺たちR・Wの科学技術を信じろ！",
  ui_story_5004_50042901_19_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5004_50042901_20_dialog_content = "PlayerName。",
  ui_story_5004_50042901_21_dialog_content = "目を覚まして、PlayerName。",
  ui_story_5004_50042901_22_dialog_content = "うっ、頭が痛い…",
  ui_story_5004_50042901_23_dialog_content = "バイス？",
  ui_story_5004_50042901_24_dialog_content = "やっと起きたわね。長いこと気を失ってたのよ。",
  ui_story_5004_50042901_25_dialog_content = "ここは…僕たち、城に墜落したんじゃなかった？",
  ui_story_5004_50042901_26_dialog_content = "分からないわ。でもここはとても…普通じゃない。\n暗力があふれてて、息苦しいの。",
  ui_story_5004_50042901_27_dialog_content = "それに、あちこちに浮いてる絵を見て。\nまるで生きてるみたいに、それぞれ違った動きをしてるの…",
  ui_story_5004_50042901_28_dialog_content = "目玉の絵を見てください。",
  ui_story_5004_50042901_29_dialog_content = "くるくる回ったかと思えば、私たちをじっと見つめてるようです…\n気味が悪いですね…",
  ui_story_5004_50042901_30_dialog_content = "ベリエちゃん、あの絵、見て！\n2本の腕がレモンでキャッチボールしてない？",
  ui_story_5004_50042901_31_dialog_content = "確かにそうね…",
  ui_story_5004_50042901_32_dialog_content = "PlayerName、向こうを見て！",
  ui_story_5004_50042901_33_dialog_content = "あれはソラヴァン！？どうしてここに？",
  ui_story_5004_50042901_34_dialog_content = "見に行かないと…",
  ui_story_5004_50042901_35_dialog_content = "何だろう？石板？何もしてないのに出て来たの？",
  ui_story_5004_50042901_36_dialog_content = "ソラヴァンがやったの？",
  ui_story_5004_50042901_37_dialog_content = "ダメだ、どれだけ進んでも近づけない…",
  ui_story_5004_50042901_38_dialog_content = "PlayerName、落ち着いて。",
  ui_story_5004_50042901_39_dialog_content = "こんなところでうかつに動いたら危ないわ。",
  ui_story_5004_50042901_40_dialog_content = "そうだね…何か考えはある？",
  ui_story_5004_50042901_41_dialog_content = "私たちは「城」に墜落して気を失ったはずよね。",
  ui_story_5004_50042901_42_dialog_content = "でも、目覚めるとここにいた。\n明らかに城の内部じゃないわ…たぶん、何か特殊な空間よ。",
  ui_story_5004_50042901_43_dialog_content = "あー、ダりい…サッサと殴って片付ければ帰れると思ってたのに。",
  ui_story_5004_50042901_44_dialog_content = "こんなところに閉じ込められて、出る方法もないなんてさ。",
  ui_story_5004_50042901_45_dialog_content = "まだ他に楽章があったというわけでもなさそうですね。",
  ui_story_5004_50042901_46_dialog_content = "…",
  ui_story_5004_50042901_47_dialog_content = "ベリエちゃん…まだがんばれる？私の肩に力を預けて。",
  ui_story_5004_50042901_48_dialog_content = "うん…平気よ、ありがとう…",
  ui_story_5004_50042901_49_dialog_content = "実は、話さないといけないことがあるの…",
  ui_story_5004_50042901_50_dialog_content = "私が砂で作ったお城のこと、覚えてる…？",
  ui_story_5004_50042901_51_dialog_content = "あっ、そうだ！あの城、こことソックリ！",
  ui_story_5004_50042901_52_dialog_content = "ベリエちゃん、まさか、何か知ってるの？",
  ui_story_5004_50042901_53_dialog_content = "いいえ、何も…でもこの建物は、ずっと私の頭の中に焼き付いてたわ。",
  ui_story_5004_50042901_54_dialog_content = "だから、私の頭の中で響く声と…何か関係があるんじゃないかと思うの。",
  ui_story_5004_50042901_55_dialog_content = "みんな用心して…ここには暗力だけじゃなくて…\n私の知ってる別の何かの力が存在してる気がするわ…",
  ui_story_5004_50042901_56_dialog_content = "心配いらないわ。私たちがあなたを守るもの。",
  ui_story_5004_50042901_57_dialog_content = "ボディーガードの報酬についてはあとで清算してもらうけどね。\nお安くしておくわ。",
  ui_story_5004_50042901_58_dialog_content = "は？口を開けばカネの話？ジュヌヴィエーヴ、アンタそれでも貴族？",
  ui_story_5004_50042901_59_dialog_content = "お黙り。雰囲気を明るくしようとしてるのよ。",
  ui_story_5004_50042901_60_dialog_content = "暗鬼を倒すには団結あるのみ。\nあなたはひねくれものだから、分からないかしら？",
  ui_story_5004_50042901_61_dialog_content = "彼女の言う通りよ。一緒にここへ乗りこんで来たのは、暗鬼たちを倒すため。",
  ui_story_5004_50042901_62_dialog_content = "変な空間に閉じ込められてはいるけど、迷ってる場合じゃないわ！",
  ui_story_5004_50042901_63_dialog_content = "ええ…！",
  ui_story_5004_50042901_64_dialog_content = "周囲を探索してみよう…なんだか、どこもぼんやりしてるけど。",
  ui_story_5004_50042901_65_dialog_content = "とりあえず、どこか1つの方向に向かって進んでみようか。",
  ui_story_5004_50042901_66_dialog_content = "ええ、慎重にね。",
  ui_story_5004_50042901_67_dialog_content = "あたりの景色に変化はないわね…",
  ui_story_5004_50042901_68_dialog_content = "それにソラヴァン以外にも、ここの絵にはどれも見覚えがあるような気がする。",
  ui_story_5004_50042901_69_dialog_content = "あれは白夜城の尖塔に似ているわね…",
  ui_story_5004_50042901_70_dialog_content = "あの女性の絵…！まさか！？",
  ui_story_5004_50042901_71_dialog_content = "暗鬼め、汚らわしい！お母様の姿で私を動揺させるつもり！？",
  ui_story_5004_50042901_72_dialog_content = "落ち着いて、カレン。敵の思惑通りになっちゃダメよ。",
  ui_story_5004_50042901_73_dialog_content = "この場所、僕らの心の中を映し出してるのかな…？",
  ui_story_5004_50042901_74_dialog_content = "この女の子の絵は…",
  ui_story_5004_50042901_75_dialog_content = "（それに触れてみたいと言う衝動がふいに起こった）",
  ui_story_5004_50042901_76_option_content = "絵に触れる",
  ui_story_5004_50042901_77_dialog_content = "…！！",
  ui_story_5004_50042901_78_dialog_content = "（濃い霧、それに聞き覚えのある叫び声…ベリエに触れた時に見た場面！？）",
  ui_story_5004_50042901_79_dialog_content = "ごめんなさい…",
  ui_story_5004_50042901_80_dialog_content = "パパ、ママ…ごめんなさい…",
  ui_story_5004_50042901_81_dialog_content = "PlayerName、PlayerName？",
  ui_story_5004_50042901_82_dialog_content = "バイス…",
  ui_story_5004_50042901_83_dialog_content = "涙が出てるわ…また何か感知した？",
  ui_story_5004_50042901_84_dialog_content = "（さっきのはベリエの記憶？どうして突然彼女の記憶が見えたんだ？）",
  ui_story_5004_50042901_85_dialog_content = "（あの女の子の絵、ベリエと関係がある？確か、彼女の両親は…）",
  ui_story_5004_50042901_86_dialog_content = "（いや…あれは暗鬼が僕を惑わすために見せたものだ。\nはっきりするまでは黙っていよう）",
  ui_story_5004_50042901_87_dialog_content = "何でもない…幻覚を見たんだ…暗鬼の仕業じゃないかな。",
  ui_story_5004_50042901_88_dialog_content = "この絵みたいなもの、気を付けて。たぶん、人の意識に影響するんだ。",
  ui_story_5004_50042901_89_dialog_content = "これは…どうして！？",
  ui_story_5004_50042901_90_dialog_content = "ん？コソコソ何してんの？",
  ui_story_5004_50042901_91_dialog_content = "その2つの絵、あたしたちの小さい頃に似てね？何してんだろ？",
  ui_story_5004_50042901_92_dialog_content = "来ないで！",
  ui_story_5004_50042901_93_dialog_content = "あ～！なんで燃やすんだよ、まだ見てないのに。",
  ui_story_5004_50042901_94_dialog_content = "見ないでいいの！",
  ui_story_5004_50042901_95_dialog_content = "グォォ！",
  ui_story_5004_50042901_96_dialog_content = "暗鬼が出た！気ぃつけな！",
  ui_story_5004_50042901_97_dialog_content = "グオォ！グギィ！",
  ui_story_5004_50042901_98_dialog_content = "絵の中から出てこられるみたいだ！みんな、戦闘準備を！",
  ui_story_5004_50043001_1_dialog_content = "倒せたけど…ビーチで遭遇した暗鬼より、手強くなかった？",
  ui_story_5004_50043001_2_dialog_content = "そうね。ビーチの時よりも明らかに苦戦したわ。",
  ui_story_5004_50043001_3_dialog_content = "けど、今のも分身でしかない…\nここを覆い尽くしてる暗力には、少しも変化がないよ。",
  ui_story_5004_50043001_4_dialog_content = "敵の本体が見つからないとなると、ちょっと厄介そうだね。",
  ui_story_5004_50043001_5_dialog_content = "この場所、あまりにもおかしすぎるわ。こんな状況は生まれて初めて。",
  ui_story_5004_50043001_6_dialog_content = "ジュヌヴィエーヴ、帽子についてる飾り、貸してくんない？",
  ui_story_5004_50043001_7_dialog_content = "何する気？壊したら許さないわよ。",
  ui_story_5004_50043001_8_dialog_content = "おりゃ――！",
  ui_story_5004_50043001_9_dialog_content = "何放り投げてるのよ！！",
  ui_story_5004_50043001_10_dialog_content = "あいたっ！？僕の顔に当たった！今、上から落ちてきたよね？",
  ui_story_5004_50043001_11_dialog_content = "この空間、方向も狂っているのね？",
  ui_story_5004_50043001_12_dialog_content = "カレンも月繭を投げて試してみたら？",
  ui_story_5004_50043001_13_dialog_content = "…月繭を投げるより、あなたが弓を撃った方が早いのではないかしら。",
  ui_story_5004_50043001_14_dialog_content = "確かにそうね…",
  ui_story_5004_50043001_15_dialog_content = "待って待って！もし上から弓が降って来て誰かに当たったらどうするの！？",
  ui_story_5004_50043001_16_dialog_content = "大丈夫だよ、私がいるから！弓のあとにミサイルも撃っちゃおうか～？",
  ui_story_5004_50043001_17_dialog_content = "勘弁してよ！他の方法を考えよう！",
  ui_story_5004_50043001_18_dialog_content = "あの口の絵とお話できないかしら？",
  ui_story_5004_50043001_19_dialog_content = "やめとこうよ。なんだかあの絵、気持ち悪いし。",
  ui_story_5004_50043001_20_dialog_content = "まるでこの世界の物じゃないみたいだ。",
  ui_story_5004_50043001_21_dialog_content = "ねぇ…",
  ui_story_5004_50043001_22_dialog_content = "あの絵は…どうかな？",
  ui_story_5004_50043001_23_dialog_content = "あの女の子の絵？後ろのドアを指さしてるみたいだね。",
  ui_story_5004_50043001_24_dialog_content = "僕たちに入れって言ってるのかな？",
  ui_story_5004_50043001_25_dialog_content = "やってみるしかないわね。あの絵に悪意はなさそうだし。",
  ui_story_5004_50043001_26_dialog_content = "でもこんなに小さいのに…どうやって通り抜けるの？",
  ui_story_5004_50043001_27_option_content = "指を入れてみる",
  ui_story_5004_50043001_28_dialog_content = "<color=#e8d9bb>ガチャ</color>",
  ui_story_5004_50043001_29_dialog_content = "何かスイッチを押したかな？待って、どうなってるの？",
  ui_story_5004_50043001_30_dialog_content = "床が小さくなってる…落ちる！！",
  ui_story_5004_50043001_31_dialog_content = "――――――！！",
  ui_story_5004_50043001_32_dialog_content = "気を失ったようだ。処理はどうする？\nあの粉がこれほど恐ろしい「怪物」を生むとは…",
  ui_story_5004_50043001_33_dialog_content = "実験データは十分に集まったわ。ここに捨てておきましょう。",
  ui_story_5004_50043001_34_dialog_content = "目が覚めてこの死体を見たら、どんな顔をすることやら。",
  ui_story_5004_50043001_35_dialog_content = "裏切りの代償ね。",
  ui_story_5004_50043001_36_dialog_content = "…君の残忍さは暗鬼にも劣らんな。",
  ui_story_5004_50043001_37_dialog_content = "うっ！！",
  ui_story_5004_50043001_38_dialog_content = "痛い…",
  ui_story_5004_50043001_39_dialog_content = "み、みんな早く降りて！",
  ui_story_5004_50043001_40_dialog_content = "息ができない…",
  ui_story_5004_50043001_41_dialog_content = "はぁ…あやうく窒息するところだった。\n真っ先に落ちてつぶされるところだったよ！最初にボタンに触ったからかな？",
  ui_story_5004_50043001_42_dialog_content = "あはは、お陰でみんな助かったわ、PlayerName。",
  ui_story_5004_50043001_43_dialog_content = "ガルー先輩が遊んでるゲームでいうなら、第2ステージってことじゃない？",
  ui_story_5004_50043001_44_dialog_content = "どういう意味？新しい敵が出てくるってこと…？",
  ui_story_5004_50043001_45_dialog_content = "ようこそ、はるばるお越しのお客人様方。",
  ui_story_5004_50043001_46_dialog_content = "誰か来た！",
  ui_story_5004_50043001_47_dialog_content = "わが城と庭園――「迷夢の虚域」へようこそ。",
  ui_story_5004_50043001_48_dialog_content = "「迷夢の虚域」？あなたがここの主ということ？",
  ui_story_5004_50043001_49_dialog_content = "おんな主と思っていただいて結構よ。\nここで10年あまりもの間、あのおもちゃたちと暮らしているんですもの。",
  ui_story_5004_50043001_50_dialog_content = "歓迎のために用意した「駒」、楽しんでもらえたかしら？",
  ui_story_5004_50043001_51_dialog_content = "この声は…！",
  ui_story_5004_50043001_52_dialog_content = "夢で聞いた…",
  ui_story_5004_50043001_53_dialog_content = "つまり、駒の形をした暗鬼を作ったのは君？\nどうしてそんな姿なの？",
  ui_story_5004_50043001_54_dialog_content = "まあ、そう焦らないで。空の末裔は、噂通り好奇心が強いのね。",
  ui_story_5004_50043001_55_dialog_content = "もう何年もの間、光霊がここに来ることはなかったの。できるだけたくさん、\nおしゃべりに付き合ってちょうだいな。死に急ぐこともないでしょう。",
  ui_story_5004_50043001_56_dialog_content = "ひとまず、ここでの生活の1年目に書き残した日記を読み返せば、\n質問に答えてやれるかもしれないわ…",
  ui_story_5004_50043001_57_dialog_content = "あら？おかしいわね？1冊目の日記がない。\nお前たち、盗んだんじゃないだろうね？",
  ui_story_5004_50043001_58_dialog_content = "どうしましょう、どうしましょう！？\n日記がないと、お客人に特製のお茶とお菓子を出すこともできないわ！",
  ui_story_5004_50043001_59_dialog_content = "それか…頭を切り開いて、日記を隠していないか確かめましょうか？",
  ui_story_5004_50043001_60_dialog_content = "PlayerName、様子がおかしいわ。",
  ui_story_5004_50043001_61_dialog_content = "とぼけないでください。\n私を騙したネズミを差し向けたのは、あなたでしょう！？",
  ui_story_5004_50043001_62_dialog_content = "うかつに手を出しちゃダメだよ。\nこの場所のことはまだよく分かってないんだし、ひとまず話をしてみよう。",
  ui_story_5004_50043001_63_option_content = "君は誰？",
  ui_story_5004_50043001_64_dialog_content = "私は…私は…そうね、2冊目の日記の表紙に書いてあったかしら…",
  ui_story_5004_50043001_65_dialog_content = "私は「偉大なる学者にして残酷な処刑人！」",
  ui_story_5004_50043001_66_dialog_content = "あら、そんなに立派な人物だったのね！",
  ui_story_5004_50043001_67_dialog_content = "（本当に頭がおかしいのか、それとも…）",
  ui_story_5004_50043001_68_option_content = "「迷夢の虚域」ってどういう場所？",
  ui_story_5004_50043001_69_dialog_content = "ここがそうよ！どれどれ…この場所は\n「進入者が抱く苦しみ、そして狂気に彩られたチェスボード」だそうよ。",
  ui_story_5004_50043001_70_dialog_content = "6冊目の日記にそう書いてあるわ。",
  ui_story_5004_50043001_71_dialog_content = "それに「王」が眠る場所であり、\n私があのお方と「王」を蘇らせると約束した場所でもある。",
  ui_story_5004_50043001_72_dialog_content = "（この暗力からして、確かに強力な暗鬼が潜んでいるに違いない。\nまさかあいつの言ってる「王」のこと？）",
  ui_story_5004_50043001_73_option_content = "なぜ城が海に浮かんできた？",
  ui_story_5004_50043001_74_dialog_content = "いい質問ね。",
  ui_story_5004_50043001_75_dialog_content = "「元々は偉大なる都市であったが、邪悪な空の末裔によって封印された。」",
  ui_story_5004_50043001_76_dialog_content = "「邪悪な空の末裔は報いを受け、やがてほとんどが滅ぼされた。」",
  ui_story_5004_50043001_77_dialog_content = "あらあら！この「空の末裔レシピ・ブック」には実にたくさんのことが書かれているわ。",
  ui_story_5004_50043001_78_dialog_content = "そちらの空の末裔サン、どんなおやつがお好み？\n好きなものを作って差し上げるわ。",
  ui_story_5004_50043001_79_dialog_content = "（空の末裔に封印された！？\nボナーズの楽章への執着心を利用したのは、このため？）",
  ui_story_5004_50043001_80_dialog_content = "PlayerName、デタラメだわ、まともに聞いちゃダメよ。",
  ui_story_5004_50043001_81_option_content = "もう少し様子を見て…",
  ui_story_5004_50043001_82_dialog_content = "本と日記をもう何冊か取ってきたの。もう少しおしゃべりしましょうよ。",
  ui_story_5004_50043001_83_option_content = "うん、話は出来そうにない…",
  ui_story_5004_50043001_84_dialog_content = "PlayerName、攻撃しましょう。\nデタラメに心を乱されてはいけないわ。",
  ui_story_5004_50043001_85_dialog_content = "あら！？攻撃だなんて物騒ね！",
  ui_story_5004_50043001_86_dialog_content = "そんなことしたら…私…あなたたちを殺してしまうわよ！",
  ui_story_5004_50043001_87_dialog_content = "そんなにあっさり死んではダメ。\n苦労してここまで来たんだから、もっと多くの真実を知りたいでしょう？",
  ui_story_5004_50043001_88_dialog_content = "私とおしゃべりしたくない？暴力はおやめなさいな。お茶を用意してあげるわ！",
  ui_story_5004_50043001_89_dialog_content = "…3、4、5、6…7人ね？今すぐ用意するわ！",
  ui_story_5004_50043001_90_dialog_content = "あっという間に行っちゃった…待って、僕たち8人のはずじゃ？",
  ui_story_5004_50043001_91_dialog_content = "ボナーズがいないわ！？",
  ui_story_5004_50043001_92_dialog_content = "待ちなさい！ボナーズをどこへ！？",
  ui_story_5004_50043001_93_dialog_content = "無作法な人ね…彼女なら、お茶会にふさわしい場所へ送り込んだまでよ。",
  ui_story_5004_50043001_94_dialog_content = "今すぐ連れ戻しなさい。",
  ui_story_5004_50043001_95_dialog_content = "あなた…私に命令する気？アッハハハ！！なんて可愛らしいのかしら！",
  ui_story_5004_50043001_96_dialog_content = "お茶会を邪魔する無礼な輩は…い、いけないわ、殺してはならない…耐えるのよ、私！！",
  ui_story_5004_50043001_97_dialog_content = "ああ、そうよ…あなた、白夜城の人間ね？お前からあの連中のにおいがするよ。",
  ui_story_5004_50043001_98_dialog_content = "傲慢で身勝手、自分の事しか眼中にない。",
  ui_story_5004_50043001_99_dialog_content = "今の言葉、そっくりそのままお返しするわ。白夜城の護衛隊長として――",
  ui_story_5004_50043001_100_dialog_content = "光霊を脅かす暗鬼には、私が制裁を下す！",
  ui_story_5004_50043001_101_dialog_content = "フフ…",
  ui_story_5004_50043001_102_dialog_content = "アハハハ…",
  ui_story_5004_50043001_103_dialog_content = "アハハハハハ――！！！",
  ui_story_5004_50043001_104_dialog_content = "見事な台詞よ！一人前ね！",
  ui_story_5004_50043001_105_dialog_content = "かわいらしい護衛隊長様だわ。\nああ、もう我慢できない、これ以上は耐えられないわ！",
  ui_story_5004_50043001_106_dialog_content = "そんなにお遊びがお好きなら、私のおもちゃで遊ばせてあげましょう！",
  ui_story_5004_50043001_107_dialog_content = "グギィ――！！",
  ui_story_5004_50043001_108_dialog_content = "敵だ！みんな気をつけて！",
  ui_story_5004_50043101_1_dialog_content = "素晴らしい戦いぶりね、護衛隊長さん。",
  ui_story_5004_50043101_2_dialog_content = "あなたたちが戦うところを見ながらお茶も飲めて、とってもいい気分だわ。",
  ui_story_5004_50043101_3_dialog_content = "でも、もう体じゅう傷だらけみたいだし、\n武器を操る動きも鈍くなってきてるわね。",
  ui_story_5004_50043101_4_dialog_content = "フフ…光霊の力もその程度ということかしら。\n私の作ったおもちゃにここまで苦労するなんてね。",
  ui_story_5004_50043101_5_dialog_content = "私を怒らせないことね、歯向かえば死ぬわ。\nそれより、おしゃべりしましょうよ。でないと、もっと苦しむことになるわ。",
  ui_story_5004_50043101_6_dialog_content = "十と何年も日記をつけてきたの…でも、こんなに面白い話は初めてよ…",
  ui_story_5004_50043101_7_dialog_content = "もっと…もっと私とおしゃべりしてちょうだい！！",
  ui_story_5004_50043101_8_dialog_content = "…一体何が目的？",
  ui_story_5004_50043101_9_dialog_content = "目的？そうね…研究にはもう飽き飽きしてるし、美食家にでもなろうかしら？",
  ui_story_5004_50043101_10_dialog_content = "そうだわ！お気に入りの「空の末裔レシピ・ブック」みたいに\n「光霊レシピ・ブック」を書けばいいのよ！",
  ui_story_5004_50043101_11_dialog_content = "すぅ…はぁ…ダメダメ、考えただけで…興奮してきちゃう。\n思わずあなたたちを殺してしまいそう！",
  ui_story_5004_50043101_12_dialog_content = "ダメよ…簡単に終わっちゃ面白くないもの。\n長い間準備してきたお茶会に「王」がいないなんて、話にならないわ。",
  ui_story_5004_50043101_13_dialog_content = "「静かなる王」、私に力を与える新たなる主。\nきっとあなたたちで作ったお菓子を、気に入ってくださるわ。",
  ui_story_5004_50043101_14_dialog_content = "そうだわ！私の力を見せてやりましょう。\n恐怖と絶望で下ごしらえをするの…",
  ui_story_5004_50043101_15_dialog_content = "そうすれば、きっともっとおいしくなるわ！",
  ui_story_5004_50043101_16_dialog_content = "な～にが力だよ…ただのセッコい小細工じゃん！",
  ui_story_5004_50043101_17_dialog_content = "暗鬼め、大口を叩くのもほどほどになさい！",
  ui_story_5004_50043101_18_dialog_content = "お前の生み出した玩具じゃ、足止めがせいぜいよ。",
  ui_story_5004_50043101_19_dialog_content = "操り人形を生み出して制御するために、お前も消耗している。",
  ui_story_5004_50043101_20_dialog_content = "本体を捕まえれば、それで終わりよ！",
  ui_story_5004_50043101_21_dialog_content = "確かに私には大した力なんてないわ。でも「王」にはある。",
  ui_story_5004_50043101_22_dialog_content = "「白夜城には、暗鬼の強大な力を求める身の程知らずが大勢いる。」",
  ui_story_5004_50043101_23_dialog_content = "「彼らの中には暗鬼と取引を交わし、\nひいては自らの身体や生命と引き換えに暗力を手に入れようとする者もいる。」",
  ui_story_5004_50043101_24_dialog_content = "見てごらんなさい。この本、10何年も前に書かれたものよ。\n白夜城は今もこんななのかしら？",
  ui_story_5004_50043101_25_dialog_content = "そういう反逆者を守るのってどういう気持ち？\n護衛隊長さん、教えてくださらない？",
  ui_story_5004_50043101_26_dialog_content = "邪な怪物め。そんな話で動揺すると思ったら大間違いよ。",
  ui_story_5004_50043101_27_dialog_content = "あら――馬鹿ではないようね。\n護衛隊長って、腕っぷしだけで上り詰められるわけじゃないのね。",
  ui_story_5004_50043101_28_dialog_content = "つまり、白夜城にはそうまで腐敗した輩がいるってこと、\nとっくに分かっているのね？",
  ui_story_5004_50043101_29_dialog_content = "ああ、決して陥落することのない都市、そびえ立つ白い塔…フフ…アハハハ！！！",
  ui_story_5004_50043101_30_dialog_content = "希望の英雄と思われながら、嘘にまみれた貴族たち。",
  ui_story_5004_50043101_31_dialog_content = "人々が希望を託す連中の正体は、騙し合いの絶えない偽善者ばかり。",
  ui_story_5004_50043101_32_dialog_content = "ペテンだらけの人間が、よく貴族になれたものね。アハハハ！！",
  ui_story_5004_50043101_33_dialog_content = "ねえ、そうでしょ！そう思わない？どうなのよ！",
  ui_story_5004_50043101_34_dialog_content = "<color=#FFB400>ベリエ・ゴーティエ</color>！",
  ui_story_5004_50043101_35_dialog_content = "私のことを知ってる？…あなた一体何者！？どうして私を知ってるの！？",
  ui_story_5004_50043101_36_dialog_content = "ゴーティエ！ゴーティエ！ゴーティエ！！",
  ui_story_5004_50043101_37_dialog_content = "そりゃあ知ってるわよ。あなたの愚かな家族のことも！",
  ui_story_5004_50043101_38_dialog_content = "私の日記にはどれもあなたの家族の名前が出てくるわ！",
  ui_story_5004_50043101_39_dialog_content = "ここへ来たのは、その体に流れる血と\n背負った罪の償いのためじゃなかったのかしら？",
  ui_story_5004_50043101_40_dialog_content = "晶石には確かに強大な力がある…",
  ui_story_5004_50043101_41_dialog_content = "でも、死神を手なずけようとするなんて、おかしな話よね！！",
  ui_story_5004_50043101_42_dialog_content = "強大で混じりけのない力、\nそれは破壊と征服のために使われるべきなのよ！",
  ui_story_5004_50043101_43_dialog_content = "白夜城のつまらない人間どものお楽しみなんかに使うものじゃないわ！！",
  ui_story_5004_50043101_44_dialog_content = "私の家族のことまで、どうして知ってるの…？",
  ui_story_5004_50043101_45_dialog_content = "どうしてかって…？あらまあ！覚えてないのね？\nなんて都合のいい、いえ、なんて哀れなことかしら！",
  ui_story_5004_50043101_46_dialog_content = "あらあら、なんてかわいそう…\n私のように日記をたくさん書いておけばよかったのよ。",
  ui_story_5004_50043101_47_dialog_content = "お菓子を多めに用意してあげるわ。\nあなたの隣にいる小娘で作ったお菓子をね！",
  ui_story_5004_50043101_48_dialog_content = "ラファエルに手を出したら許さない！",
  ui_story_5004_50043101_49_dialog_content = "ベリエちゃん…",
  ui_story_5004_50043101_50_dialog_content = "あら。分かったわよ、その子に手出しはしないわ。フフフ…",
  ui_story_5004_50043101_51_dialog_content = "私は何もしないけど、「駒」同然のあなたにその子を守れる？",
  ui_story_5004_50043101_52_dialog_content = "あなたたちのひたむきな感情…全部まるごと、本に残してあげましょう！",
  ui_story_5004_50043101_53_dialog_content = "ここで死んだ後も、私の筆の下で永遠に生き続けることになるのよ！",
  ui_story_5004_50043101_54_dialog_content = "題名はどうしようかしら？\n「愚者と無邪気の恋模様」？「ある駒の哀歌」？",
  ui_story_5004_50043101_55_dialog_content = "光霊って、みんなほほえましいほどに愚かね。\n1人ずつ縛って、拷問して、本を書いてあげたいわ！",
  ui_story_5004_50043101_56_dialog_content = "ああ！そうそう！あなたたちをお菓子にして、紅茶と一緒にいただかないと！",
  ui_story_5004_50043101_57_dialog_content = "そうしてあなたたちの生涯について読みながら、その血肉を味わうの…",
  ui_story_5004_50043101_58_dialog_content = "あのおバカな子は「愚かな音楽家」って題名にしようかしらね。",
  ui_story_5004_50043101_59_dialog_content = "たった一度の演奏のために…\n何も知らないで、封印を解くなんて。ウフフ。",
  ui_story_5004_50043101_60_dialog_content = "暗鬼を遣わせて、ホテルに潜入させて、<color=#FFB400>仕掛けを施して</color>…\n潮汐祭で集まってきた光霊たちの力を抽出したの。",
  ui_story_5004_50043101_61_dialog_content = "「静かなる王」を蘇らせたのは、あなたたちの力ってこと！",
  ui_story_5004_50043101_62_dialog_content = "私ってなんて非の打ち所のない戦略家で、戦術家で、陰謀家で、\nチェスの打ち手なのかしら！それから文学者でもあるわ！",
  ui_story_5004_50043101_63_dialog_content = "結局、やっぱり話は通じないか…\nここに長い間引きこもりすぎて、精神に異常をきたしてる！",
  ui_story_5004_50043101_64_dialog_content = "あら…よくも…よくもそんなことが言えたわね！記録に値するわ！",
  ui_story_5004_50043101_65_dialog_content = "でも、この手でお菓子に変えてやる前に、\n私の新しいおもちゃで殺されないようにしてね？分かった？",
  ui_story_5004_50043101_66_dialog_content = "それじゃ、がんばってね！",
  ui_story_5004_50043201_1_dialog_content = "はぁ…はぁ…",
  ui_story_5004_50043201_2_dialog_content = "PlayerName、また鼻血が出てるわ…無理しないで。",
  ui_story_5004_50043201_3_dialog_content = "僕は平気だよ…ちょっと疲れただけ…",
  ui_story_5004_50043201_4_dialog_content = "（でも、さすがに立て続けに戦ってるから…精神への負荷が大きすぎる…）",
  ui_story_5004_50043201_5_dialog_content = "終わった？私は次のお菓子を楽しむ準備をしてるわ。",
  ui_story_5004_50043201_6_dialog_content = "今回の戦いぶりは――",
  ui_story_5004_50043201_7_dialog_content = "「子供の殴り合いみたいな指揮とおばあさんが杖を振るかのような動き」。",
  ui_story_5004_50043201_8_dialog_content = "実際、あなたたちの動きがますます鈍くなってるわ。\nお茶を4杯と、お菓子を1ついただけたもの。",
  ui_story_5004_50043201_9_dialog_content = "チッ…何て奴！お遊びのつもり？",
  ui_story_5004_50043201_10_dialog_content = "こんなハリボテの分身を私たちと戦わせようなんて、どういうつもりよ！？",
  ui_story_5004_50043201_11_dialog_content = "正々堂々と勝負なさい！",
  ui_story_5004_50043201_12_dialog_content = "アハハハ！あなたの、あなたたちの相手をしろって？\nこんなみじめなおもちゃじゃ相手にならない？",
  ui_story_5004_50043201_13_dialog_content = "あなたたちのことをもっと知りたいの。\n心を込めて作った食べ物こそが…何よりもおいしいんだもの。",
  ui_story_5004_50043201_14_dialog_content = "それに「静かなる王」もまだお目覚めでないわ。\nおしゃべりする時間はまだまだあるの。",
  ui_story_5004_50043201_15_dialog_content = "あっ、1冊目の日記がやっと見つかったわ。\n何が書いてあるのか見てみましょう…",
  ui_story_5004_50043201_16_dialog_content = "ぷぷ…ぷははははは！！これはまさしくお宝ね！！\nこっちへいらっしゃいな、読んで聞かせてあげるわ！！",
  ui_story_5004_50043201_17_dialog_content = "…コホン！それじゃ、喉の調子を整えて。",
  ui_story_5004_50043201_18_dialog_content = "ゴーティエ家のお嬢様、貧相な頭ではピンと来ないのかしら？",
  ui_story_5004_50043201_19_dialog_content = "こんなにも晶石に詳しいのは誰？…夢の中でお前を呼ぶのは誰？",
  ui_story_5004_50043201_20_dialog_content = "あなた…暗鬼に寝返った、ピュロス家の唯一の生き残り…\nキャロライン・ピュロスね！？",
  ui_story_5004_50043201_21_dialog_content = "アッハハハハ！！！ご名答！",
  ui_story_5004_50043201_22_dialog_content = "あらやだ、光霊だったころの名前なんて恥ずかしくてたまらないわ！！",
  ui_story_5004_50043201_23_dialog_content = "日記って、他人に読んで聞かせるべきものじゃないわね。",
  ui_story_5004_50043201_24_dialog_content = "ああ、それでも聞かせてあげたいの！真剣にお聞きなさい！",
  ui_story_5004_50043201_25_dialog_content = "昔は光霊だったですって？",
  ui_story_5004_50043201_26_dialog_content = "暗鬼に膝を屈し、魂を売った愚か者…ここにもいたのね。",
  ui_story_5004_50043201_27_dialog_content = "うふふふ…自分が光霊だったこと、もう少しで忘れちゃうところだったわ。",
  ui_story_5004_50043201_28_dialog_content = "けど日記には、暗鬼になってからどれほど自由でどれほど愉快か、\nぎっしり書かれてるわ。",
  ui_story_5004_50043201_29_dialog_content = "白夜城にいた頃より何倍も楽しいわ！",
  ui_story_5004_50043201_30_dialog_content = "本題に戻りましょう。さっき話したけど、\nあなたの家は私の家と違って、晶石をエネルギー源として利用しようとするだけ…",
  ui_story_5004_50043201_31_dialog_content = "あれほど残虐であれほど惨たらしい力、武器にしないなんてありえないわ！",
  ui_story_5004_50043201_34_dialog_content = "白夜城が暗鬼を撃退するための強力な武器になるはずだった。\nすべての暗鬼を極夜へ送り帰すことだってできたでしょうに！",
  ui_story_5004_50043201_35_dialog_content = "でも、あなたたち軟弱者の一族が白夜城の城主に告げ口したのよ。\nああっ！ここまで読んだら、また腹が立ってきたわ！",
  ui_story_5004_50043201_36_dialog_content = "ピュロス家はあちこちで落ちぶれた光霊を捕まえて、\n晶石の実験をしてたでしょ。",
  ui_story_5004_50043201_37_dialog_content = "同族の体を実験に使うだなんて、まともな人のやることじゃないよ！",
  ui_story_5004_50043201_38_dialog_content = "確かに若い頃の私はまともじゃなかったわ。\n晶石の実験にのめり込んで…フフフ…",
  ui_story_5004_50043201_39_dialog_content = "でも私がいなければ、今のベリエもなかった…私の自慢の実験体よ…",
  ui_story_5004_50043201_40_dialog_content = "まさか…ベリエちゃんは…",
  ui_story_5004_50043201_41_dialog_content = "…",
  ui_story_5004_50043201_42_dialog_content = "この日記、あなたに関することが詳しく書かれてるわ。\n好きな食べ物、スポーツまでね。",
  ui_story_5004_50043201_43_dialog_content = "寝る時に何を抱いて寝るのかまで、つぶさに書かれてるの。",
  ui_story_5004_50043201_44_dialog_content = "どうやら書き手に愛されていたみたいね！",
  ui_story_5004_50043201_45_dialog_content = "あら！書き手は私だったわ。\nこれじゃぁまるで、けがれなき少女が変態ののぞき魔に愛されてしまったみたいね。",
  ui_story_5004_50043201_46_dialog_content = "不完全な作品ではあったけど、\n私の実験において重要な一区切りになったわ。",
  ui_story_5004_50043201_47_dialog_content = "私はあなたに山ほど愛を注いだの。",
  ui_story_5004_50043201_48_dialog_content = "暗力を用いて作った特殊な晶石の粉末…\n今もその体の中で成長していることでしょう。",
  ui_story_5004_50043201_49_dialog_content = "あなたの体に巣食い…あなたの感情と意志を餌としているの。",
  ui_story_5004_50043201_50_dialog_content = "やめて…",
  ui_story_5004_50043201_51_dialog_content = "それにしても、あなたは不安定だったわ…\nアハハハ――やっとここまで来たわ、一番お気に入りのシーンよ！",
  ui_story_5004_50043201_52_dialog_content = "ああ、あなたが点けた美しい火。\nあなたが殺した大勢の光霊たちの叫び声――",
  ui_story_5004_50043201_53_dialog_content = "もうやめて！！！",
  ui_story_5004_50043201_54_dialog_content = "調子に乗らないで！",
  ui_story_5004_50043201_55_dialog_content = "うふふ…「王」が私を呼んでるわ…",
  ui_story_5004_50043201_56_dialog_content = "すぐに戻るわね。あなたたちもあの時こんがり焼かれた光霊たちと同じように、\nおいしい料理に仕上げてあげる。",
  ui_story_5004_50043201_57_dialog_content = "やめて…もうやめて！！",
  ui_story_5004_50043201_58_dialog_content = "ベリエちゃん！落ち着いて！",
  ui_story_5004_50043201_59_dialog_content = "ラファエル、感知でベリエの気持ちを鎮めてみるよ！",
  ui_story_5004_50043201_60_dialog_content = "分かった…急いで…とても苦しんでるの…",
  ui_story_5004_50043201_61_dialog_content = "（狂暴な力がベリエの体の中で蠢いてるのが分かる）",
  ui_story_5004_50043201_62_dialog_content = "（光霊の持つ力じゃない。でも暗力とも違う…）",
  ui_story_5004_50043201_63_dialog_content = "（キャロラインが言うように、破滅を象徴する残虐な力なのかもしれない…）",
  ui_story_5004_50043201_64_dialog_content = "（ベリエはずっとこの力を制御しようとしてきた。\nでもキャロラインに刺激されて…）",
  ui_story_5004_50043201_65_dialog_content = "（今、少しずつ制御できなくなってきてる）",
  ui_story_5004_50043201_66_dialog_content = "ベリエちゃん…",
  ui_story_5004_50043201_67_dialog_content = "ラファエル…私は平気よ…PlayerName、ありがとう。",
  ui_story_5004_50043201_68_dialog_content = "ごめんなさい…私、過去をみんなに隠してたの…",
  ui_story_5004_50043201_69_dialog_content = "でもキャロラインの実験のせいか…単にあまりの苦痛で、\n本能的に思い出さないようにしていたのか分からないけど…",
  ui_story_5004_50043201_70_dialog_content = "過去のことはぼんやりとしか思い出せないの…",
  ui_story_5004_50043201_71_dialog_content = "小さい頃…ピュロス家の人間に連れ去られたことだけは覚えてる…",
  ui_story_5004_50043201_72_dialog_content = "何も見えない部屋に閉じ込められて…晶石の粉末を与えられたの。",
  ui_story_5004_50043201_73_dialog_content = "それから私の体は、まるで呪いをかけられたみたいになって…\n私を苦しめる晶石から逃れられない日々を送ることになったわ。",
  ui_story_5004_50043201_74_dialog_content = "あとで知ったの…ピュロス家は光霊を兵器に改造する実験をしてた…\nこの晶石を利用して。",
  ui_story_5004_50043201_75_dialog_content = "いいんだよ…ベリエちゃん。皆それぞれ、過去があるんだよ。",
  ui_story_5004_50043201_76_dialog_content = "楽しい記憶はみんなに話せばいいし、嫌な記憶は忘れればいいの。\nそれで新しい生活を始めたって、誰も責めたりしないよ。",
  ui_story_5004_50043201_77_dialog_content = "ん？あたしも、まーロクな過去がないし、気にしないかな。",
  ui_story_5004_50043201_78_dialog_content = "わざわざ話して恥をかくことなんてないのよ。\n私もまったく気にしないわ。",
  ui_story_5004_50043201_79_dialog_content = "私たちは仲間よ。過去に何があろうと、今のあなたを信じてるわ！",
  ui_story_5004_50043201_80_dialog_content = "疑問の余地はない。これほどの重い罪を犯したキャロラインに審判を下し、\n惨劇を繰り返させないことが急務よ。",
  ui_story_5004_50043201_81_dialog_content = "僕もみんなと同じ考えだよ。",
  ui_story_5004_50043201_82_dialog_content = "ありがとう…みんな…",
  ui_story_5004_50043201_83_dialog_content = "キャロライン・ピュロス…かつては白夜城の貴族だったそうだけれど、\nいまや名誉の一片も残っていない。",
  ui_story_5004_50043201_84_dialog_content = "暗鬼と手を組むだけでは飽き足らず…\n同族に対して残酷な仕打ち…",
  ui_story_5004_50043201_85_dialog_content = "それから、彼女がずっと口にしている「王」。\n本当に絶大な力を持っているのだとしたら…",
  ui_story_5004_50043201_86_dialog_content = "「王」の覚醒を阻止するべきね。",
  ui_story_5004_50043201_87_dialog_content = "でも、この空間よ。どうやって彼女の本体を探し出すの？",
  ui_story_5004_50043201_88_dialog_content = "あの…さっきPlayerNameが感知で助けてくれた時に…",
  ui_story_5004_50043201_89_dialog_content = "晶石の力が大量に集まっている場所を感じ取った気がするの…",
  ui_story_5004_50043201_90_dialog_content = "そこに隠れてるかもしれない…",
  ui_story_5004_50043201_91_dialog_content = "ベリエ、ナイスよ！それじゃ、出発しましょ！",
  ui_story_5004_50043201_92_dialog_content = "ええ。厳しい戦いになりそうね。",
  ui_story_5004_50043201_93_dialog_content = "ベリエちゃん…安心してね。\nキッチリ落とし前つけさせちゃうから！",
  ui_story_5004_50043201_94_dialog_content = "うん…終わったら、約束通り一緒に白夜城へ帰ろうね。",
  ui_story_5004_50043201_95_dialog_content = "この先にどんな敵が待っていようと…私、逃げないわ！",
  ui_story_5004_50043301_1_dialog_content = "あら？よくここを見つけたわね。",
  ui_story_5004_50043301_2_dialog_content = "オッホン！「<color=#FFB400>謁見の間</color>へようこそ。おいで下さって感激よ。\nさあ、新たなる王の前に頭を垂れなさい。」",
  ui_story_5004_50043301_3_dialog_content = "「これは晶石の力を使って手に入れた新しい姿…\nベリエ、あなたと同じ力よ。」",
  ui_story_5004_50043301_4_dialog_content = "「ただ違うのは、あなたは実験体に過ぎないということ。\n私は晶石の力を思うままにコントロールできる完全体なの。」",
  ui_story_5004_50043301_5_dialog_content = "「そして<color=#FFB400>静かなる王</color>は晶石の力で蘇り…\n再び我々の前に君臨する。」",
  ui_story_5004_50043301_6_dialog_content = "んん～、今のセリフ、あなたたちの悲惨な死を記録するための、\n追悼文の冒頭よ。気に入ってもらえたかしら？",
  ui_story_5004_50043301_7_dialog_content = "<color=#e8d9bb>キャロラインが後ろに手を振ると、晶石が破裂して粉末になった。\n粉末は濃い霧となって、王に吸い込まれた</color>",
  ui_story_5004_50043301_8_dialog_content = "…",
  ui_story_5004_50043301_9_dialog_content = "ごらんなさい…晶石の力と暗鬼は、こんなにも相性がいいの。",
  ui_story_5004_50043301_10_dialog_content = "かつての私は、これこそ神が光霊に与えし究極の武器だと勘違いしていたわ。\n今考えると、あまりに愚かだった。いっそ埋まっちゃいたいわね！",
  ui_story_5004_50043301_11_dialog_content = "これは「神」が暗鬼にこそ贈りたもうたものだったのよ！",
  ui_story_5004_50043301_12_dialog_content = "無駄話は聞き飽きたわ。",
  ui_story_5004_50043301_13_dialog_content = "正々堂々と戦いなさい！",
  ui_story_5004_50043301_14_dialog_content = "ついに、ついによ…フフフ…フヒヒヒヒ！あなたたちを殺したくてたまらないわ！",
  ui_story_5004_50043301_15_dialog_content = "早く、早く早く！！もっと苦しみを、もっと絶望を。\nそうしてうま味を引き出すのよ！！",
  ui_story_5004_50043302_1_dialog_content = "うぅ、いくら倒してもキリがないわ！",
  ui_story_5004_50043302_2_dialog_content = "ザコに手こずってる場合じゃないよ…燃え尽きろ！！",
  ui_story_5004_50043302_3_dialog_content = "グギィ…グゥ…ありえない…この私が…",
  ui_story_5004_50043302_4_dialog_content = "すごい…頭に命中した。顔から光が消えていくわ！",
  ui_story_5004_50043302_5_dialog_content = "う…うまくいった…？",
  ui_story_5004_50043302_6_dialog_content = "…",
  ui_story_5004_50043302_7_dialog_content = "イッヒヒヒヒヒ！な～んちゃって！",
  ui_story_5004_50043302_8_dialog_content = "！！",
  ui_story_5004_50043302_9_dialog_content = "スモーキー！",
  ui_story_5004_50043302_10_dialog_content = "痛いわ…さっさとどいてちょうだい！",
  ui_story_5004_50043302_11_dialog_content = "あーあ…不意打ち食らうなんて。ジュヌヴィエーヴ、ありがと。",
  ui_story_5004_50043302_12_dialog_content = "待ちなさい！ひどいケガよ、急いでラファエルの治療を受けなさい！",
  ui_story_5004_50043302_13_dialog_content = "（どうしよう、どれだけ攻撃しても倒せない…\nそれに駒の暗鬼も、次から次へと出てくる…）",
  ui_story_5004_50043302_14_dialog_content = "（おかしい！今まで暗鬼に変身した敵はいたけど…こんな力はなかった！）",
  ui_story_5004_50043302_15_dialog_content = "（まさか、あの王…）",
  ui_story_5004_50043302_16_dialog_content = "PlayerName！集中して！戦局は一瞬で変わるもの。\nどこかでチャンスが訪れるかもしれないわ！",
  ui_story_5004_50043302_17_dialog_content = "隙を見せちゃダメよ！",
  ui_story_5004_50043302_18_dialog_content = "何をコソコソしてるの？\n大きな声で喋ってくれないと、遺言を日記に書けないじゃない！！",
  ui_story_5004_50043302_19_dialog_content = "咲き誇れ！！",
  ui_story_5004_50043302_20_dialog_content = "ゲホゲホ…煙が立ち込めてる。\nベリエが攻撃を防いで…晶石を爆破させて、反撃した？",
  ui_story_5004_50043302_21_dialog_content = "…",
  ui_story_5004_50043302_22_dialog_content = "なかなかやるじゃない。",
  ui_story_5004_50043302_23_dialog_content = "効いてない…？",
  ui_story_5004_50043302_24_dialog_content = "いったいどういうこと…？キズ1つ付けられないなんて。",
  ui_story_5004_50043302_25_dialog_content = "いや…あれは…",
  ui_story_5004_50043302_26_dialog_content = "つまらない小細工だけど、実験体のあなたにしては十分の出来ね。",
  ui_story_5004_50043302_27_dialog_content = "でもね、ベリエ。あなたはみじめで哀れな失敗作に過ぎないの。",
  ui_story_5004_50043302_28_dialog_content = "あなたは結局…役立たずなのよ。",
  ui_story_5004_50043302_29_dialog_content = "あれほど大勢を…自分の両親まで殺したあなたが…他人を救えるとでもいうの？",
  ui_story_5004_50043302_30_dialog_content = "警告したはずよ…お前は愛する人たちを死に至らしめ、\n深淵に落ちるだろう、って。",
  ui_story_5004_50043302_31_dialog_content = "私は…違う…",
  ui_story_5004_50043302_32_dialog_content = "両親…？",
  ui_story_5004_50043302_33_dialog_content = "グォォ！！",
  ui_story_5004_50043302_34_dialog_content = "ちょっと！邪魔しないでよ！",
  ui_story_5004_50043302_35_dialog_content = "カレン、バイス！ラファエルに援護を！",
  ui_story_5004_50043302_36_dialog_content = "無防備なご両親をどれほど惨たらしく殺したのか、\nあなたは覚えているわよね…",
  ui_story_5004_50043302_37_dialog_content = "死を受け入れなさいな…そうすれば罪は償える。苦しみから解放されるのよ。",
  ui_story_5004_50043302_38_dialog_content = "ごめんなさい…みんな…ごめんなさい…パパ、ママ…",
  ui_story_5004_50043302_39_dialog_content = "ベリエちゃん！",
  ui_story_5004_50043302_40_dialog_content = "ベリエちゃん…そんなヤツの言うこと、聞いちゃダメ！\n…ご両親を殺したのはそいつだよ！",
  ui_story_5004_50043302_41_dialog_content = "あなたは力を制御できずに火事を起こした…\nでも、その後すぐに意識を失ったんだよ！",
  ui_story_5004_50043302_42_dialog_content = "そいつがあなたを人質にして、あなたの両親と一族の人達を殺したの！！",
  ui_story_5004_50043302_43_dialog_content = "…",
  ui_story_5004_50043302_44_dialog_content = "逮捕されたピュロス家の人の証言だよ。嘘じゃない！！",
  ui_story_5004_50043302_45_dialog_content = "余計なことを！！",
  ui_story_5004_50043302_46_dialog_content = "わぁっ！！",
  ui_story_5004_50043302_47_dialog_content = "イッヒヒ…まだ邪魔者がいたとはね。",
  ui_story_5004_50043302_48_dialog_content = "でもそれより、あなたって子は…アハハハハ！！！",
  ui_story_5004_50043302_49_dialog_content = "今まで自分が殺したってずっと信じてたのね！！",
  ui_story_5004_50043302_50_dialog_content = "！！！",
  ui_story_5004_50043302_51_dialog_content = "どう？目覚めた時に両親がどんな姿だったか覚えてる？",
  ui_story_5004_50043302_52_dialog_content = "私がわざわざ目の前に並べておいてあげたのよ――\nあなたが自分でそうしたと思い込むようにね！！",
  ui_story_5004_50043302_53_dialog_content = "なんておバカなのかしら。本気にしてたの？何年ぐらい？",
  ui_story_5004_50043302_54_dialog_content = "…許さない…",
  ui_story_5004_50043302_55_dialog_content = "日記を読み返すたびに、この時の場面を思い返して、\n全身が震えるほど興奮しちゃうの！",
  ui_story_5004_50043302_56_dialog_content = "10何年も、そう思い込んでいたのね！！",
  ui_story_5004_50043302_57_dialog_content = "この日記は何よりも大切な宝よ！あなたたちとどれほど分かち合いたいことか！",
  ui_story_5004_50043302_58_dialog_content = "今までお遊びの相手をしてきたのも、\nこの手でその美しいお顔を記録するため！ウヒ…ヒヒヒヒ！！",
  ui_story_5004_50043302_59_dialog_content = "どう？うれしい？実の親を殺した苦しみを心に抱えながら、\nひっそりと自分を偽って生きてきたのよね。",
  ui_story_5004_50043302_60_dialog_content = "それで真相を知った瞬間のあなたの表情！ああ、なんて美しいの！",
  ui_story_5004_50043302_61_dialog_content = "顔をまるごと剥がして、日記の表紙にしたいぐらいだわ！！",
  ui_story_5004_50043302_62_dialog_content = "ゴーティエ！ゴーティエ！裏切者のゴーティエの人間には\nそういう最期がおあつらえ向きよ！！",
  ui_story_5004_50043302_63_dialog_content = "よくも、私たちに、そんな…！",
  ui_story_5004_50043302_64_dialog_content = "失敗作ごときが、完璧な私ともうすぐ蘇る王に\n対抗できるだなんて思わないことね！",
  ui_story_5004_50043302_65_dialog_content = "私に偽りの罪を背負わせたことも、\n私の友達を傷つけようとしたことも――",
  ui_story_5004_50043302_66_dialog_content = "絶対に許さない！！！",
  ui_story_5004_50043302_67_dialog_content = "これは…ベリエが押さえ込んでいた力…！？",
  ui_story_5004_50043302_68_dialog_content = "こんな力を解放したら、君までキャロラインみたいになってしまうんじゃ…！",
  ui_story_5004_50043302_69_dialog_content = "私は弱かったせいで、家族を失った。\n苦しんで、自責の念にさいなまれてきた…",
  ui_story_5004_50043302_70_dialog_content = "そのすべての元凶が今私の目の前にいて、\nまた大切な人を傷つけようとしてる！",
  ui_story_5004_50043302_71_dialog_content = "キャロライン・ピュロス…！",
  ui_story_5004_50043302_72_dialog_content = "制御できなくなっても構わない。地獄へ道連れにしてやる…！",
  ui_story_5004_50043302_73_dialog_content = "晶石が…なんというすさまじい攻撃…",
  ui_story_5004_50043302_74_dialog_content = "キャロラインが押さえつけられてる！\nでも…動きは止められたけど、倒せそうにないわ！",
  ui_story_5004_50043302_75_dialog_content = "痛くもかゆくもないわ――！王よ！私にさらなる力を！！\n身の程知らずの反逆者たちに、私が罰を与えましょう！！",
  ui_story_5004_50043302_76_dialog_content = "…",
  ui_story_5004_50043302_77_dialog_content = "やっぱり！僕の推測だけど…",
  ui_story_5004_50043302_78_dialog_content = "キャロラインの無敵の力、あの王と関係がありそうだ！",
  ui_story_5004_50043302_79_dialog_content = "みんな！キャロラインが動けないうちに王を集中攻撃するんだ！！",
  ui_story_5004_50043402_1_dialog_content = "…！！",
  ui_story_5004_50043402_2_dialog_content = "！！小賢しい虫けらが、よくも！！",
  ui_story_5004_50043402_3_dialog_content = "私の長年の念願を壊すなんて！！",
  ui_story_5004_50043402_4_dialog_content = "ここからは私たちが反撃する番ね！",
  ui_story_5004_50043402_5_dialog_content = "あたしのやわ肌を傷つけた罪、その命で償いな！",
  ui_story_5004_50043402_6_dialog_content = "ありえない、ありえないわ！私は決してこんな虫けらに負けたりしない！",
  ui_story_5004_50043402_7_dialog_content = "お前たちは単なる駒…絶対に無理…私は白夜城の晶石学者…\n私こそが、ここの…「クイーン」なのよ！",
  ui_story_5004_50043402_8_dialog_content = "わが王よ！力をください！どうしてお声が聞こえないのです！",
  ui_story_5004_50043402_9_dialog_content = "私はまだ…まだ…終わりじゃない！私のお茶会は…私…！",
  ui_story_5004_50043402_10_dialog_content = "呪ってやる！！みんなまとめてよ…\n私にはまだまだお菓子が、絶品の光霊があるもの！！恥知らず！裏切者！！",
  ui_story_5004_50043402_11_dialog_content = "永遠に閉じ込めてやる――！！",
  ui_story_5004_50043402_12_dialog_content = "あなたの言うことなんて、もう何1つ信じないわ…！消えて…！！",
  ui_story_5004_50043402_13_dialog_content = "お茶会…決して…ああああ――！！！",
  ui_story_5004_50043402_14_dialog_content = "ふぅ…ふぅ…",
  ui_story_5004_50043402_15_dialog_content = "こ、これで勝った、の…？",
  ui_story_5004_50043402_16_dialog_content = "ベリエちゃん！晶石が増えてるよ！どうして！？",
  ui_story_5004_50043402_17_dialog_content = "平気よ…ラファエル、あなたとみんなが無事なら、それでいいの…",
  ui_story_5004_50043402_18_dialog_content = "私は討った…家族の仇を…あなたを守った…これでいいの…",
  ui_story_5004_50043402_19_dialog_content = "ベリエちゃん？目を覚まして！眠っちゃダメ！",
  ui_story_5004_50043402_20_dialog_content = "いけない、PlayerName！\nいますぐベリエちゃんを白夜城へ連れて行かなくちゃ！",
  ui_story_5004_50043402_21_dialog_content = "でも、まだボナーズが見つからないんだ…\nそれに、どうすれば脱出できるのか…",
  ui_story_5004_50043402_22_dialog_content = "危ない！地面が割れてる！",
  ui_story_5004_50043402_23_dialog_content = "気をつけて！！",
  ui_story_5004_50043402_24_dialog_content = "！！！",
  ui_story_5004_50043402_25_dialog_content = "今度はどこに落ちてるの！？",
  ui_story_5004_50043402_26_dialog_content = "永遠に閉じ込めてやる――！！",
  ui_story_5004_50043402_27_dialog_content = "…儀式は…お茶会は…永遠に終わらない…",
  ui_story_5004_50043402_28_dialog_content = "イヒ…イヒヒヒヒ…"
}
return config
